-- ====================================================================================================
-- 4. Functions (44)
-- ====================================================================================================
CREATE OR REPLACE FUNCTION public.pp5_apply_academic_year_transition_v2_without_context(p_draft_id uuid, p_expected_revision text, p_confirmation_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_draft public.academic_year_transition_drafts%rowtype;
  v_current_rev text;
  v_expected_token text;
  v_settings public.school_settings%rowtype;
  v_transition_id uuid;
  v_manifest jsonb;
  v_student record;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));

  lock table public.students,public.student_year_rosters,public.school_settings,public.scores,
    public.attendance_daily,public.attendance_monthly,public.assessments,public.student_growth,
    public.student_comments,public.teacher_assignments in share row exclusive mode;

  select * into v_draft
  from public.academic_year_transition_drafts
  where id = p_draft_id
  for update;

  if v_draft.id is null then
    raise exception 'ไม่พบฉบับร่างการเลื่อนชั้นรหัส %', p_draft_id;
  end if;

  if v_draft.status <> 'validated' then
    raise exception 'ฉบับร่างต้องผ่านการตรวจสอบ (validated) ก่อน Apply เท่านั้น (สถานะปัจจุบัน: %)', v_draft.status;
  end if;

  v_expected_token := format('CONFIRM_APPLY_%s_TO_%s', v_draft.source_year, v_draft.target_year);
  if p_confirmation_token is distinct from v_expected_token then
    raise exception 'Confirmation token ไม่ถูกต้อง (ต้องการ: %)', v_expected_token;
  end if;

  v_current_rev := public.pp5_compute_academic_year_revision(v_draft.source_year);
  if v_current_rev is distinct from p_expected_revision or v_current_rev is distinct from v_draft.source_revision then
    raise exception 'Source revision ไม่ตรงกับค่าที่ตรวจสอบไว้ ข้อมูลมีการเปลี่ยนแปลงหลังการตรวจสอบ';
  end if;

  select * into v_settings
  from public.school_settings
  order by updated_at desc nulls last
  limit 1
  for update;

  if v_settings.academic_year is distinct from v_draft.source_year
     or v_draft.target_year::integer <> v_draft.source_year::integer+1 then
    raise exception 'ปีต้นทางไม่ใช่ปีปัจจุบันหรือปีปลายทางไม่ใช่ปีถัดไป';
  end if;
  if exists(select 1 from public.student_year_rosters where academic_year=v_draft.target_year)
    or exists(select 1 from public.students where academic_year=v_draft.target_year)
    or exists(select 1 from public.scores where academic_year=v_draft.target_year)
    or exists(select 1 from public.assessments where academic_year=v_draft.target_year)
    or exists(select 1 from public.attendance_daily where academic_year=v_draft.target_year)
    or exists(select 1 from public.attendance_monthly where academic_year=v_draft.target_year)
    or exists(select 1 from public.student_growth where academic_year=v_draft.target_year)
    or exists(select 1 from public.student_comments where academic_year=v_draft.target_year) then
    raise exception 'ปีปลายทางมีข้อมูลแล้ว ต้องตรวจสอบก่อนเลื่อนชั้น';
  end if;
  if exists(select 1 from public.academic_year_transition_students where draft_id=p_draft_id and selected_action='pending_review')
    or (select count(*) from public.academic_year_transition_students where draft_id=p_draft_id)
       <> (select count(*) from public.students where academic_year=v_draft.source_year and status='active') then
    raise exception 'คำตัดสินยังไม่ครบ';
  end if;
  if exists(select 1 from public.academic_year_transition_students ts join public.students s on s.id=ts.student_id
    where ts.draft_id=p_draft_id and (s.academic_year is distinct from v_draft.source_year or s.status<>'active'
      or s.grade is distinct from ts.source_grade or s.room is distinct from ts.source_room))
    or exists(select 1 from public.students s where s.academic_year=v_draft.source_year and s.status='active'
      and not exists(select 1 from public.student_year_rosters r where r.academic_year=v_draft.source_year and r.student_id=s.id)) then
    raise exception 'ทะเบียนต้นทางไม่ตรงกับฉบับร่างหรือไม่ครบ';
  end if;
  if exists(select 1 from public.academic_year_transition_students ts where ts.draft_id=p_draft_id
    and ts.selected_action in ('promote','retain') and (coalesce(btrim(ts.target_room),'')=''
      or ts.target_grade is distinct from case when ts.selected_action='retain' then ts.source_grade
        else case ts.source_grade when 'อ.1' then 'อ.2' when 'อ.2' then 'อ.3' when 'อ.3' then 'ป.1'
        when 'ป.1' then 'ป.2' when 'ป.2' then 'ป.3' when 'ป.3' then 'ป.4' when 'ป.4' then 'ป.5' when 'ป.5' then 'ป.6' end end)) then
    raise exception 'ชั้นหรือห้องปลายทางไม่ถูกต้อง';
  end if;
  -- Preserve exact lifecycle/settings/roster for rollback, not only row counts.
  -- Build data manifest before locking
  v_manifest := jsonb_build_object(
    'closedAt', now(),
    'sourceYear', v_draft.source_year,
    'targetYear', v_draft.target_year,
    'scoresCount', (select count(*) from public.scores where academic_year = v_draft.source_year),
    'attendanceDailyCount', (select count(*) from public.attendance_daily where academic_year = v_draft.source_year),
    'assessmentsCount', (select count(*) from public.assessments where academic_year = v_draft.source_year),
    'growthCount', (select count(*) from public.student_growth where academic_year = v_draft.source_year),
    'studentCount', (select count(*) from public.students where academic_year = v_draft.source_year and status = 'active')
  );

  -- Record in legacy transition table for audit & backward compatibility
  insert into public.academic_year_transitions (
    from_year, to_year, status, student_count, promoted_count,
    graduated_count, snapshot, summary, requested_by, applied_at
  ) values (
    v_draft.source_year, v_draft.target_year, 'applied',
    coalesce((v_draft.summary->>'studentCount')::integer, 0),
    coalesce((v_draft.summary->>'promoteCount')::integer, 0),
    coalesce((v_draft.summary->>'graduateCount')::integer, 0),
    jsonb_build_object('draftId', p_draft_id, 'manifest', v_manifest,
      'studentsBefore', (select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) from public.students s join public.academic_year_transition_students ts on ts.student_id=s.id where ts.draft_id=p_draft_id),
      'rostersBefore', (select coalesce(jsonb_agg(to_jsonb(r) order by r.student_id),'[]'::jsonb) from public.student_year_rosters r where r.academic_year=v_draft.source_year),
      'settingsBefore', to_jsonb(v_settings)),
    v_draft.summary,
    auth.uid(),
    now()
  ) returning id into v_transition_id;

  -- Process each student according to individual decision
  for v_student in
    select ts.*, s.status as student_lifecycle
    from public.academic_year_transition_students ts
    join public.students s on s.id = ts.student_id
    where ts.draft_id = p_draft_id
  loop
    -- Update closing year roster
    update public.student_year_rosters
    set enrollment_status = case v_student.selected_action
          when 'promote' then 'completed'
          when 'retain' then 'retained'
          when 'graduate' then 'graduated'
          when 'transfer_out' then 'transferred_out'
          when 'withdraw' then 'withdrawn'
          when 'deceased' then 'deceased'
          else 'completed'
        end,
        updated_at = now()
    where academic_year = v_draft.source_year and student_id = v_student.student_id;

    if v_student.selected_action in ('promote', 'retain') then
      -- Create provisional roster for target year
      insert into public.student_year_rosters (
        academic_year, student_id, prefix, first_name, last_name, gender, national_id, grade, room, student_number,
        enrollment_status, source, is_provisional, dmc_verification_status,
        source_transition_id, created_at, updated_at
      ) values (
        v_draft.target_year,
        v_student.student_id,
        (select prefix from public.students where id=v_student.student_id),
        (select first_name from public.students where id=v_student.student_id),
        (select last_name from public.students where id=v_student.student_id),
        (select gender from public.students where id=v_student.student_id),
        (select national_id from public.students where id=v_student.student_id),
        v_student.target_grade,
        v_student.target_room,
        v_student.target_student_number,
        'enrolled',
        'transition',
        true,
        'not_checked',
        v_transition_id,
        now(),
        now()
      ) on conflict (academic_year, student_id) do update
      set grade = excluded.grade,
          room = excluded.room,
          student_number = excluded.student_number,
          enrollment_status = 'enrolled',
          is_provisional = true,
          updated_at = now();

      -- Advance active student in main table
      update public.students
      set academic_year = v_draft.target_year,
          grade = v_student.target_grade,
          room = v_student.target_room,
          student_number = v_student.target_student_number,
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'graduate' then
      -- Lifecycle graduated, no target roster
      update public.students
      set status = 'graduated',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'transfer_out' then
      update public.students
      set status = 'transferred_out',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'withdraw' then
      update public.students
      set status = 'withdrawn',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'deceased' then
      update public.students
      set status = 'deceased',
          updated_at = now()
      where id = v_student.student_id;
    end if;
  end loop;

  update public.academic_year_transitions set snapshot=snapshot || jsonb_build_object(
    'studentsAfter',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) from public.students s join public.academic_year_transition_students ts on ts.student_id=s.id where ts.draft_id=p_draft_id),
    'rostersAfter',(select coalesce(jsonb_agg(to_jsonb(r) order by r.academic_year,r.student_id),'[]'::jsonb) from public.student_year_rosters r where r.academic_year in (v_draft.source_year,v_draft.target_year)))
  where id=v_transition_id;
  -- Lock closing year and set target year as current
  insert into public.academic_years (
    academic_year, is_current, status, is_locked, locked_at, locked_by, lock_reason, data_manifest
  ) values (
    v_draft.source_year, false, 'closed', true, now(), auth.uid(), 'ปิดปีการศึกษาและเลื่อนชั้นสู่ปี ' || v_draft.target_year, v_manifest
  ) on conflict (academic_year) do update
  set is_current = false,
      status = 'closed',
      is_locked = true,
      locked_at = now(),
      locked_by = auth.uid(),
      lock_reason = excluded.lock_reason,
      data_manifest = v_manifest;

  insert into public.academic_years (
    academic_year, is_current, status, is_locked
  ) values (
    v_draft.target_year, true, 'active', false
  ) on conflict (academic_year) do update
  set is_current = true,
      status = 'active',
      is_locked = false;

  -- Update school_settings
  update public.school_settings
  set academic_year = v_draft.target_year,
      semester = 1,
      updated_at = now()
  where id = v_settings.id;

  update public.academic_year_transitions set snapshot=snapshot || jsonb_build_object('settingsAfter', (select to_jsonb(s) from public.school_settings s where s.id=v_settings.id)) where id=v_transition_id;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'apply_transition','academic_history',v_transition_id::text,jsonb_build_object('academic_year',v_draft.source_year,'target_year',v_draft.target_year));
  -- Mark draft as applied
  update public.academic_year_transition_drafts
  set status = 'applied',
      applied_by = auth.uid(),
      applied_at = now(),
      transition_id = v_transition_id,
      updated_at = now()
  where id = p_draft_id;

  return jsonb_build_object(
    'success', true,
    'transitionId', v_transition_id,
    'sourceYear', v_draft.source_year,
    'targetYear', v_draft.target_year,
    'manifest', v_manifest
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_apply_academic_year_transition_v2(p_draft_id uuid, p_expected_revision text, p_confirmation_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_year text;v_capture jsonb;v_result jsonb;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  select source_year into v_year from public.academic_year_transition_drafts where id=p_draft_id for update;
  if v_year is null then raise exception 'ไม่พบฉบับร่างการเลื่อนชั้น';end if;
  -- Avoid source changes between revision preview and capture.
  lock table public.students,public.student_year_rosters,public.student_details,public.school_settings,
    public.school_signatures,public.subjects,public.teachers,public.teacher_assignments,public.holidays
    in share row exclusive mode;
  v_capture:=public.pp5_capture_year_report_context(v_year,md5(public.pp5_build_year_report_context(v_year)::text),'เก็บข้อมูลประจำปีก่อนปิดปีและเลื่อนชั้น');
  v_result:=public.pp5_apply_academic_year_transition_v2_without_context(p_draft_id,p_expected_revision,p_confirmation_token);
  update public.academic_year_transitions set snapshot=snapshot || jsonb_build_object('reportContextSnapshotId',v_capture->>'id')
    where id=(v_result->>'transitionId')::uuid;
  return v_result || jsonb_build_object('reportContextSnapshotId',v_capture->>'id');
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_apply_academic_year_transition(p_target_year text, p_expected_student_count integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.pp5_assert_admin();
  raise exception 'กรุณาใช้หน้าจัดการเลื่อนชั้น V2 ตรวจฉบับร่างและเก็บข้อมูลประจำปีก่อนปิดปี';
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_apply_dmc_student_import(p_rows jsonb, p_academic_year text, p_file_name text, p_file_type text, p_source_count integer, p_skipped_count integer DEFAULT 0, p_measured_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_import_id uuid;
  v_incoming integer;
  v_existing integer;
  v_inserted integer;
  v_preserved_missing integer;
  v_snapshot_count integer;
  v_measured_on date := coalesce(p_measured_on, current_date);
  v_summary jsonb;
begin
  perform public.pp5_validate_dmc_student_payload(p_rows, p_academic_year);
  if lower(coalesce(p_file_type, '')) not in ('csv', 'xlsx') then
    raise exception 'ชนิดไฟล์ DMC ไม่ถูกต้อง';
  end if;
  if coalesce(p_source_count, 0) < jsonb_array_length(p_rows)
     or coalesce(p_skipped_count, 0) < 0 then
    raise exception 'จำนวนแถวของไฟล์ DMC ไม่ถูกต้อง';
  end if;

  perform pg_advisory_xact_lock(hashtext('pp5_dmc_import:' || p_academic_year));
  v_incoming := jsonb_array_length(p_rows);

  -- Lock every existing row that will be snapshotted so a concurrent edit
  -- cannot slip between the snapshot and the upsert.
  perform 1 from public.students s
  where exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = s.id)
  for update;
  perform 1 from public.student_details d
  where exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = d.student_id)
  for update;
  perform 1 from public.student_growth g
  where g.measured_on = v_measured_on
    and exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = g.student_id)
  for update;
  perform 1 from public.student_year_rosters roster
  where roster.academic_year = p_academic_year
    and exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = roster.student_id)
  for update;

  select count(*)::integer into v_existing
  from public.students s
  where exists (
    select 1 from jsonb_array_elements(p_rows) item
    where item->>'student_id' = s.id
  );
  v_inserted := v_incoming - v_existing;

  select count(*)::integer into v_preserved_missing
  from public.student_year_rosters roster
  where roster.academic_year = p_academic_year
    and roster.status = 'active'
    and not exists (
      select 1 from jsonb_array_elements(p_rows) item
      where item->>'student_id' = roster.student_id
    );

  insert into public.student_import_runs (
    academic_year, file_name, file_type, source_count, valid_count,
    skipped_count, inserted_count, updated_count, preserved_missing_count,
    summary, requested_by, status, snapshot_count, measured_on, applied_at
  ) values (
    p_academic_year, left(coalesce(p_file_name, ''), 255), lower(p_file_type),
    p_source_count, v_incoming, p_skipped_count, v_inserted, v_existing,
    v_preserved_missing, jsonb_build_object('state', 'snapshot_created'),
    auth.uid(), 'applied', 0, v_measured_on, clock_timestamp()
  ) returning id into v_import_id;

  insert into public.student_import_snapshots (
    import_id, student_id, was_student_present,
    student_row, detail_row, growth_row, roster_row
  )
  select
    v_import_id,
    incoming.student_id,
    s.id is not null,
    case when s.id is null then null else to_jsonb(s) end,
    (select to_jsonb(d) from public.student_details d where d.student_id = incoming.student_id),
    (select to_jsonb(g) from public.student_growth g
      where g.student_id = incoming.student_id and g.measured_on = v_measured_on limit 1),
    (select to_jsonb(roster) from public.student_year_rosters roster
      where roster.student_id = incoming.student_id and roster.academic_year = p_academic_year)
  from jsonb_to_recordset(p_rows) as incoming(student_id text)
  left join public.students s on s.id = incoming.student_id;

  get diagnostics v_snapshot_count = row_count;
  if v_snapshot_count <> v_incoming then
    raise exception 'สร้าง snapshot ก่อนนำเข้าไม่ครบ: ต้องได้ % แต่ได้ %', v_incoming, v_snapshot_count;
  end if;

  insert into public.students (
    id, national_id, student_number, prefix, first_name, last_name,
    gender, grade, room, academic_year, status, updated_at
  )
  select
    r.student_id, nullif(r.national_id, ''), r.student_number,
    nullif(r.prefix, ''), r.first_name, r.last_name,
    r.gender, r.grade, r.room, p_academic_year, 'active', now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, national_id text, student_number integer, prefix text,
    first_name text, last_name text, gender text, grade text, room text
  )
  on conflict (id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    academic_year = excluded.academic_year,
    status = 'active',
    updated_at = now();

  insert into public.student_details (
    student_id, birth_date, religion, blood_type, ethnicity, nationality,
    address, subdistrict, district, province,
    father_name, father_last_name, father_occupation,
    mother_name, mother_last_name, mother_occupation,
    guardian_name, guardian_occupation, guardian_relation,
    disadvantage, disposal_blocked, source_data, updated_at
  )
  select
    r.student_id, nullif(r.birth_date, '')::date,
    nullif(r.religion, ''), nullif(r.blood_type, ''),
    nullif(r.ethnicity, ''), nullif(r.nationality, ''),
    nullif(r.address, ''), nullif(r.subdistrict, ''),
    nullif(r.district, ''), nullif(r.province, ''),
    nullif(r.father_name, ''), nullif(r.father_last_name, ''), nullif(r.father_occupation, ''),
    nullif(r.mother_name, ''), nullif(r.mother_last_name, ''), nullif(r.mother_occupation, ''),
    nullif(r.guardian_name, ''), nullif(r.guardian_occupation, ''), nullif(r.guardian_relation, ''),
    nullif(r.disadvantage, ''), nullif(r.disposal_blocked, ''),
    coalesce(r.source_data, '{}'::jsonb), now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, birth_date text, religion text, blood_type text,
    ethnicity text, nationality text, address text, subdistrict text,
    district text, province text, father_name text, father_last_name text,
    father_occupation text, mother_name text, mother_last_name text,
    mother_occupation text, guardian_name text, guardian_occupation text,
    guardian_relation text, disadvantage text, disposal_blocked text,
    source_data jsonb
  )
  on conflict (student_id) do update set
    birth_date = excluded.birth_date,
    religion = excluded.religion,
    blood_type = excluded.blood_type,
    ethnicity = excluded.ethnicity,
    nationality = excluded.nationality,
    address = excluded.address,
    subdistrict = excluded.subdistrict,
    district = excluded.district,
    province = excluded.province,
    father_name = excluded.father_name,
    father_last_name = excluded.father_last_name,
    father_occupation = excluded.father_occupation,
    mother_name = excluded.mother_name,
    mother_last_name = excluded.mother_last_name,
    mother_occupation = excluded.mother_occupation,
    guardian_name = excluded.guardian_name,
    guardian_occupation = excluded.guardian_occupation,
    guardian_relation = excluded.guardian_relation,
    disadvantage = excluded.disadvantage,
    disposal_blocked = excluded.disposal_blocked,
    source_data = excluded.source_data,
    updated_at = now();

  insert into public.student_growth (
    student_id, measured_on, academic_year, weight_kg, height_cm,
    recorded_by, updated_at
  )
  select
    r.student_id, v_measured_on, p_academic_year,
    r.weight_kg, r.height_cm, auth.uid(), now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, weight_kg numeric, height_cm numeric
  )
  where r.weight_kg is not null or r.height_cm is not null
  on conflict (student_id, measured_on) do update set
    academic_year = excluded.academic_year,
    weight_kg = excluded.weight_kg,
    height_cm = excluded.height_cm,
    recorded_by = excluded.recorded_by,
    updated_at = now();

  insert into public.student_year_rosters (
    academic_year, student_id, national_id, student_number, prefix,
    first_name, last_name, gender, grade, room, status, updated_at
  )
  select
    p_academic_year, r.student_id, nullif(r.national_id, ''), r.student_number,
    nullif(r.prefix, ''), r.first_name, r.last_name, r.gender,
    r.grade, r.room, 'active', now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, national_id text, student_number integer, prefix text,
    first_name text, last_name text, gender text, grade text, room text
  )
  on conflict (academic_year, student_id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    status = 'active',
    updated_at = now();

  v_summary := jsonb_build_object(
    'academicYear', p_academic_year,
    'sourceCount', p_source_count,
    'validCount', v_incoming,
    'skippedCount', p_skipped_count,
    'insertedCount', v_inserted,
    'updatedCount', v_existing,
    'preservedMissingCount', v_preserved_missing,
    'resultRosterCount', v_incoming + v_preserved_missing,
    'measurementDate', v_measured_on,
    'snapshotCount', v_snapshot_count,
    'rollbackAvailable', true,
    'destructiveChanges', 0
  );

  update public.student_import_runs
  set summary = v_summary,
      snapshot_count = v_snapshot_count,
      applied_at = clock_timestamp()
  where id = v_import_id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, detail)
  values (auth.uid(), 'dmc_student_import', 'student_import_run', v_import_id::text, v_summary);

  return v_summary || jsonb_build_object('importId', v_import_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_assert_academic_year_writable(p_year text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_locked boolean;
begin
  if coalesce(trim(p_year), '') = '' then
    return;
  end if;

  select is_locked into v_locked
  from public.academic_years
  where academic_year = trim(p_year);

  if coalesce(v_locked, false) then
    raise exception using
      errcode = '55000',
      message = format('ปีการศึกษา %s ถูกล็อกแล้ว ไม่อนุญาตให้เพิ่ม ลบ หรือแก้ไขข้อมูลย้อนหลัง', p_year);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_assert_admin()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.pp5_current_role(), '') <> 'admin'
     and session_user not in ('postgres', 'supabase_admin') then
    raise exception using
      errcode = '42501',
      message = 'รายการนี้สำหรับผู้ดูแลระบบเท่านั้น';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_build_year_report_context(p_year text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with s as (select * from public.school_settings order by updated_at desc nulls last,id limit 1)
  select public.pp5_normalize_context_json(jsonb_build_object(
    'version',1,'academic_year',p_year,
    'school',(select to_jsonb(s)-'settings_json'-'updated_at' || jsonb_build_object('settings_json',coalesce(s.settings_json,'{}'::jsonb)-'backup') from s),
    'signatures',(select coalesce(jsonb_agg(to_jsonb(x) order by x.settings_id),'[]'::jsonb) from public.school_signatures x where x.settings_id=(select id from s)),
    'subjects',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb) from public.subjects x),
    'teachers',(select coalesce(jsonb_agg(to_jsonb(x)-'password_hash'-'email' order by x.id),'[]'::jsonb) from public.teachers x),
    'assignments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.grade,x.room,x.id),'[]'::jsonb) from public.teacher_assignments x where x.academic_year=p_year),
    'rosters',(select coalesce(jsonb_agg(to_jsonb(x) order by x.student_id),'[]'::jsonb) from public.student_year_rosters x where x.academic_year=p_year),
    'students',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb) from public.students x where exists(select 1 from public.student_year_rosters r where r.academic_year=p_year and r.student_id=x.id)),
    'details',(select coalesce(jsonb_agg(to_jsonb(x) order by x.student_id),'[]'::jsonb) from public.student_details x where exists(select 1 from public.student_year_rosters r where r.academic_year=p_year and r.student_id=x.student_id)),
    'holidays',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb) from public.holidays x)
  ));
$function$;

CREATE OR REPLACE FUNCTION public.pp5_can_read_student(p_student_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when auth.uid() is null then false
    when public.pp5_current_role() in ('admin', 'teacher') then true
    when public.pp5_current_role() = 'parent' and exists (
      select 1 from public.user_profiles p
      join public.parent_student_links l on l.parent_user_id = p.id
      where p.id = auth.uid() and p.active = true and l.student_id = p_student_id
    ) then true
    else false
  end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_capture_year_report_context(p_year text, p_expected_revision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb; v_current text; v_revision text; v_id uuid;
begin
  perform public.pp5_assert_admin();
  if p_year is null or p_year !~ '^[0-9]{4}$' then raise exception 'ปีการศึกษาไม่ถูกต้อง';end if;
  if coalesce(length(btrim(p_reason)),0)<5 then raise exception 'กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร';end if;
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  lock table public.students,public.student_year_rosters,public.student_details,public.school_settings,
    public.school_signatures,public.subjects,public.teachers,public.teacher_assignments,public.holidays
    in share row exclusive mode;
  if (select count(*) from public.school_settings)<>1 then raise exception 'การตั้งค่าโรงเรียนต้องมีชุดเดียว กรุณาตรวจสอบก่อนเก็บสำเนา';end if;
  select academic_year into v_current from public.school_settings order by updated_at desc nulls last,id limit 1;
  if p_year is distinct from v_current then raise exception 'สร้างสำเนาได้เฉพาะปีปัจจุบัน ห้ามนำข้อมูลปัจจุบันไปอ้างว่าเป็นข้อมูลปีเก่า';end if;
  v:=public.pp5_build_year_report_context(p_year);v_revision:=md5(v::text);
  if p_expected_revision is distinct from v_revision then raise exception 'ข้อมูลเปลี่ยนหลังตรวจ กรุณาตรวจรายการใหม่ก่อนบันทึก';end if;
  if jsonb_array_length(v->'rosters')=0 or jsonb_array_length(v->'subjects')=0
     or coalesce(btrim(v->'school'->>'school_name'),'')='' then
    raise exception 'ข้อมูลโรงเรียน ทะเบียน หรือรายวิชายังไม่ครบ ไม่สามารถสร้างสำเนาได้';
  end if;
  if exists(select 1 from public.students s where s.academic_year=p_year and s.status='active'
    and not exists(select 1 from public.student_year_rosters r where r.academic_year=p_year and r.student_id=s.id)) then
    raise exception 'นักเรียนปัจจุบันบางคนยังไม่มีทะเบียนรายปี กรุณาตรวจทะเบียนก่อน';
  end if;
  select id into v_id from (select id,revision from public.academic_year_report_snapshots
    where academic_year=p_year order by captured_at desc,id desc limit 1) latest where revision=v_revision;
  if v_id is null then
    insert into public.academic_year_report_snapshots(academic_year,revision,payload,reason,captured_by)
    values(p_year,v_revision,v,btrim(p_reason),auth.uid()) returning id into v_id;
    insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail)
    values(auth.uid(),'capture_year_report_context','academic_history',p_year,
      jsonb_build_object('academic_year',p_year,'snapshot_id',v_id,'revision',v_revision,'reason',btrim(p_reason)));
  end if;
  return jsonb_build_object('success',true,'id',v_id,'academic_year',p_year,'revision',v_revision);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_check_academic_year_lock_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_year text;
begin
  if tg_op in ('INSERT', 'UPDATE') then
    v_year := new.academic_year;
    perform public.pp5_assert_academic_year_writable(v_year);
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_year := old.academic_year;
    perform public.pp5_assert_academic_year_writable(v_year);
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_compute_academic_year_revision(p_year text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rev text;
begin
  select md5(concat(
    trim(p_year), ':',
    count(*), ':',
    coalesce(string_agg(id || '-' || coalesce(updated_at::text, ''), ',' order by id), '')
  ))
  into v_rev
  from public.students
  where academic_year = trim(p_year)
    and status = 'active';

  return coalesce(v_rev, md5(trim(p_year)));
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_correct_historical_record(p_table text, p_year text, p_key jsonb, p_expected jsonb, p_patch jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_keys text[]; v_fields text[]; v_before jsonb; v_after jsonb; v_merged jsonb;
  v_where text; v_set text; v_count integer; v_grade numeric; v_status text;
  v_sum numeric; v_rawmax numeric; v_finalmax numeric;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  if p_year is null or p_year !~ '^\d{4}$' or length(btrim(coalesce(p_reason,''))) < 5 then
    raise exception 'กรุณาระบุปีและเหตุผลอย่างน้อย 5 ตัวอักษร';
  end if;
  if not exists(select 1 from public.academic_years where academic_year=p_year and not is_current and not is_locked)
    or exists(select 1 from public.school_settings where academic_year=p_year) then
    raise exception 'ปีนี้ยังล็อกอยู่หรือเป็นปีปัจจุบัน กรุณาเปิดแก้ปีเก่าก่อน';
  end if;
  case p_table
    when 'scores' then
      v_keys := array['student_id','subject_id','semester','academic_year'];
      v_fields := array['formative_score','summative_score','total_score','grade_point','grade_text','score_breakdown'];
    when 'student_comments' then
      v_keys := array['student_id','academic_year','semester']; v_fields := array['comment'];
    when 'assessments' then v_keys := array['id']; v_fields := array['score'];
    when 'attendance_daily' then v_keys := array['student_id','attendance_date']; v_fields := array['status'];
    when 'student_year_rosters' then
      v_keys := array['student_id','academic_year']; v_fields := array['prefix','first_name','last_name','grade','room','student_number'];
    else raise exception 'ไม่อนุญาตให้แก้ตารางนี้';
  end case;
  if jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_patch) is distinct from 'object'
    or jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'ข้อมูลไม่ถูกต้อง'; end if;
  if (select count(*) from jsonb_object_keys(p_key)) <> cardinality(v_keys)
    or exists(select 1 from unnest(v_keys) k where not p_key ? k or p_key->>k is null)
    or exists(select 1 from jsonb_object_keys(p_patch) k where not k = any(v_fields))
    or p_patch = '{}'::jsonb then raise exception 'ฟิลด์หรือรหัสข้อมูลไม่ถูกต้อง'; end if;
  select string_agg(format('t.%I::text = ($1->>%L)',k,k),' and ') into v_where from unnest(v_keys) k;
  execute format('select to_jsonb(t) from public.%I t where %s and t.academic_year::text=$2 for update',p_table,v_where)
    into v_before using p_key,p_year;
  if v_before is null then raise exception 'ไม่พบข้อมูลในปีที่เลือก'; end if;
  if v_before is distinct from p_expected then raise exception 'ข้อมูลถูกแก้หลังจากเปิด กรุณาโหลดใหม่' using errcode='40001'; end if;
  if not exists(select 1 from public.student_year_rosters where academic_year=p_year and student_id=v_before->>'student_id') then
    raise exception 'ไม่พบทะเบียนนักเรียนของปีนี้';
  end if;
  v_merged := v_before || p_patch;
  if p_table='scores' then
    if not (p_patch ?& v_fields) then raise exception 'ต้องส่งคะแนนครบชุด'; end if;
    if jsonb_typeof(v_merged->'score_breakdown') is distinct from 'object'
      or (v_merged->'score_breakdown') - array['scores','mid','final','total','grade','entered','entryState']
        is distinct from coalesce(v_before->'score_breakdown','{}'::jsonb) - array['scores','mid','final','total','grade','entered','entryState'] then
      raise exception 'ห้ามเปลี่ยนข้อมูลประกอบและคะแนนเต็มเดิม';
    end if;
    if (v_merged->>'formative_score')::numeric is null or (v_merged->>'summative_score')::numeric is null
       or (v_merged->>'total_score')::numeric is null
       or not ((v_merged->>'formative_score')::numeric between 0 and 100)
       or not ((v_merged->>'summative_score')::numeric between 0 and 100)
       or not ((v_merged->>'total_score')::numeric between 0 and 100)
       or abs((v_merged->>'total_score')::numeric-(v_merged->>'formative_score')::numeric-(v_merged->>'summative_score')::numeric)>0.051 then
       raise exception 'คะแนนรวมไม่ถูกต้อง';
    end if;
    v_grade := case when round((v_merged->>'total_score')::numeric)>=80 then 4
      when round((v_merged->>'total_score')::numeric)>=75 then 3.5 when round((v_merged->>'total_score')::numeric)>=70 then 3
      when round((v_merged->>'total_score')::numeric)>=65 then 2.5 when round((v_merged->>'total_score')::numeric)>=60 then 2
      when round((v_merged->>'total_score')::numeric)>=55 then 1.5 when round((v_merged->>'total_score')::numeric)>=50 then 1 else 0 end;
    if (v_merged->>'grade_point')::numeric is distinct from v_grade
      or coalesce(v_merged->>'grade_text','') not in ('ร','มส',v_grade::text) then raise exception 'ผลการเรียนไม่ตรงกับคะแนน'; end if;
    if jsonb_typeof(v_before#>'{score_breakdown,scores}')='array' then
      if jsonb_typeof(v_merged#>'{score_breakdown,scores}') is distinct from 'array'
        or v_merged#>'{score_breakdown,fullScores}' is distinct from v_before#>'{score_breakdown,fullScores}'
        or v_merged#>'{score_breakdown,fullFinal}' is distinct from v_before#>'{score_breakdown,fullFinal}'
        or jsonb_array_length(v_merged#>'{score_breakdown,scores}') <> jsonb_array_length(v_before#>'{score_breakdown,scores}') then
        raise exception 'ห้ามเปลี่ยนโครงสร้างคะแนนเต็มระหว่างแก้ย้อนหลัง';
      end if;
      if exists(select 1 from jsonb_array_elements(v_merged#>'{score_breakdown,scores}') with ordinality a(val,n)
        where val::text::numeric < 0 or val::text::numeric > (v_merged#>'{score_breakdown,fullScores}'->>(n::int-1))::numeric) then
        raise exception 'คะแนนรายครั้งเกินคะแนนเต็ม';
      end if;
      select sum(val::text::numeric) into v_sum from jsonb_array_elements(v_merged#>'{score_breakdown,scores}') val;
      select sum(val::text::numeric) into v_rawmax from jsonb_array_elements(v_merged#>'{score_breakdown,fullScores}') val;
      v_finalmax := (v_merged#>>'{score_breakdown,fullFinal}')::numeric;
      if v_rawmax is null or v_rawmax<=0 or v_finalmax is null or v_finalmax not between 0 and 100
        or abs(round(v_sum/v_rawmax*(100-v_finalmax),1)-(v_merged->>'formative_score')::numeric)>0.051
        or (v_merged->>'summative_score')::numeric>v_finalmax then raise exception 'คะแนนรายครั้งไม่ตรงคะแนนรวม'; end if;
    end if;
    if (v_merged#>>'{score_breakdown,total}')::numeric is distinct from (v_merged->>'total_score')::numeric
      or (v_merged#>>'{score_breakdown,mid}')::numeric is distinct from (v_merged->>'formative_score')::numeric
      or (v_merged#>>'{score_breakdown,final}')::numeric is distinct from (v_merged->>'summative_score')::numeric then
      raise exception 'รายละเอียดคะแนนไม่ตรงคะแนนรวม'; end if;
  elsif p_table='attendance_daily' then
    if coalesce(v_merged->>'status','') not in ('present','absent','leave','late') then raise exception 'สถานะเวลาเรียนไม่ถูกต้อง'; end if;
  elsif p_table='assessments' then
    if (v_merged->>'score')::numeric is null or not ((v_merged->>'score')::numeric between 0 and 3) then raise exception 'ผลประเมินต้องอยู่ระหว่าง 0–3'; end if;
    if v_before->>'assessment_type'='activity' and (v_merged->>'score')::numeric not in (0,1) then raise exception 'กิจกรรมใช้ 0 หรือ 1'; end if;
  elsif p_table='student_comments' then
    if length(btrim(coalesce(v_merged->>'comment','')))=0 then raise exception 'กรุณาระบุความคิดเห็น'; end if;
  elsif p_table='student_year_rosters' then
    if length(btrim(coalesce(v_merged->>'first_name','')))=0 or length(btrim(coalesce(v_merged->>'last_name','')))=0
       or coalesce(v_merged->>'grade','') not in ('อ.1','อ.2','อ.3','ป.1','ป.2','ป.3','ป.4','ป.5','ป.6')
       or length(btrim(coalesce(v_merged->>'room','')))=0 then raise exception 'ชื่อ ชั้น หรือห้องไม่ถูกต้อง'; end if;
  end if;
  select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$3)).%I',k,p_table,k),',') into v_set from jsonb_object_keys(p_patch) k;
  v_set := v_set || ',updated_at=clock_timestamp()';
  if p_table in ('scores','assessments','student_comments') then v_set:=v_set||',recorded_by=auth.uid()'; end if;
  execute format('update public.%I t set %s where %s and t.academic_year::text=$2 returning to_jsonb(t)',p_table,v_set,v_where)
    into v_after using p_key,p_year,v_merged;
  get diagnostics v_count=row_count;
  if v_count<>1 then raise exception 'ผลการบันทึกไม่ครบ ยกเลิกการแก้ไข'; end if;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail)
    values(auth.uid(),'correct_record','academic_history',p_key::text,
      jsonb_build_object('academic_year',p_year,'table',p_table,'reason',btrim(p_reason),'before',v_before,'after',v_after));
  return v_after;
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_create_academic_year_transition_draft(p_target_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_source_year text;
  v_existing_draft public.academic_year_transition_drafts%rowtype;
  v_draft_id uuid;
  v_revision text;
  v_student_count integer := 0;
  v_promote_count integer := 0;
  v_graduate_count integer := 0;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_target_data_count integer := 0;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));

  select academic_year into v_source_year
  from public.school_settings
  order by updated_at desc nulls last
  limit 1;

  if coalesce(trim(v_source_year), '') = '' then
    raise exception 'ไม่พบปีการศึกษาปัจจุบันในการตั้งค่าระบบ';
  end if;

  if coalesce(p_target_year, '') !~ '^[0-9]{4}$' then
    v_blockers := v_blockers || jsonb_build_array('ปีการศึกษาใหม่ต้องเป็นตัวเลข 4 หลัก');
  elsif p_target_year::integer <> v_source_year::integer + 1 then
    v_blockers := v_blockers || jsonb_build_array(
      format('เพื่อความปลอดภัย ระบบอนุญาตให้เปลี่ยนจากปี %s เป็น %s เท่านั้น', v_source_year, v_source_year::integer + 1)
    );
  end if;

  -- Check existing active draft (Idempotent return)
  select * into v_existing_draft
  from public.academic_year_transition_drafts
  where source_year = v_source_year
    and status in ('draft', 'validated')
  order by created_at desc
  limit 1;

  v_revision := public.pp5_compute_academic_year_revision(v_source_year);

  if v_existing_draft.id is not null then
    if v_existing_draft.source_revision = v_revision and v_existing_draft.target_year = p_target_year then
      return jsonb_build_object(
        'success', true,
        'draftId', v_existing_draft.id,
        'sourceYear', v_existing_draft.source_year,
        'targetYear', v_existing_draft.target_year,
        'status', v_existing_draft.status,
        'isIdempotent', true,
        'summary', v_existing_draft.summary,
        'blockers', v_existing_draft.blockers,
        'warnings', v_existing_draft.warnings
      );
    else
      -- Invalidate old stale draft
      update public.academic_year_transition_drafts
      set status = 'cancelled', updated_at = now()
      where id = v_existing_draft.id;
    end if;
  end if;

  -- Target year data check
  select count(*) into v_target_data_count
  from public.students
  where academic_year = p_target_year;

  if v_target_data_count > 0 then
    v_blockers := v_blockers || jsonb_build_array(
      format('ปี %s มีข้อมูลนักเรียนอยู่แล้ว %s คน จึงไม่อนุญาตให้สร้างทับ', p_target_year, v_target_data_count)
    );
  end if;

  -- Create fresh draft
  insert into public.academic_year_transition_drafts (
    source_year, target_year, status, source_revision, created_by
  ) values (
    v_source_year, p_target_year, 'draft', v_revision, auth.uid()
  ) returning id into v_draft_id;

  -- Populate student decision rows
  insert into public.academic_year_transition_students (
    draft_id, student_id, source_grade, source_room, source_student_number,
    source_enrollment_status, default_action, selected_action, target_grade, target_room
  )
  select
    v_draft_id,
    s.id,
    s.grade,
    s.room,
    s.student_number,
    coalesce(r.enrollment_status, 'enrolled'),
    case s.grade
      when 'ป.6' then 'graduate'
      else 'promote'
    end as default_action,
    case s.grade
      when 'ป.6' then 'graduate'
      else 'promote'
    end as selected_action,
    case s.grade
      when 'ป.6' then null
      else public.pp5_default_promoted_grade(s.grade)
    end as target_grade,
    s.room as target_room
  from public.students s
  left join public.student_year_rosters r
    on r.academic_year = v_source_year and r.student_id = s.id
  where s.academic_year = v_source_year
    and s.status = 'active';

  select count(*) into v_student_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id;

  select count(*) into v_promote_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id and selected_action = 'promote';

  select count(*) into v_graduate_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id and selected_action = 'graduate';

  if v_student_count = 0 then
    v_blockers := v_blockers || jsonb_build_array('ไม่พบนักเรียนสถานะ active ในปีปัจจุบัน');
  end if;

  update public.academic_year_transition_drafts
  set summary = jsonb_build_object(
        'studentCount', v_student_count,
        'promoteCount', v_promote_count,
        'graduateCount', v_graduate_count,
        'retainCount', 0,
        'targetYear', p_target_year,
        'sourceYear', v_source_year
      ),
      blockers = v_blockers,
      warnings = v_warnings,
      updated_at = now()
  where id = v_draft_id;

  return jsonb_build_object(
    'success', true,
    'draftId', v_draft_id,
    'sourceYear', v_source_year,
    'targetYear', p_target_year,
    'status', 'draft',
    'studentCount', v_student_count,
    'promoteCount', v_promote_count,
    'graduateCount', v_graduate_count,
    'blockers', v_blockers,
    'warnings', v_warnings
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_current_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select role
  from public.user_profiles
  where id = auth.uid() and active = true;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_default_promoted_grade(p_grade text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_grade
    when 'อ.1' then 'อ.2'
    when 'อ.2' then 'อ.3'
    when 'อ.3' then 'ป.1'
    when 'ป.1' then 'ป.2'
    when 'ป.2' then 'ป.3'
    when 'ป.3' then 'ป.4'
    when 'ป.4' then 'ป.5'
    when 'ป.5' then 'ป.6'
    else p_grade
  end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_dmc_student_rollback_guard(p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run public.student_import_runs%rowtype;
  v_later_imports integer := 0;
  v_changed_students integer := 0;
  v_dependent_records integer := 0;
  v_eligible boolean := false;
  v_reason text := '';
begin
  perform public.pp5_assert_admin();

  select * into v_run
  from public.student_import_runs
  where id = p_import_id;

  if v_run.id is null then
    raise exception 'ไม่พบประวัติการนำเข้า DMC ที่ระบุ';
  end if;

  select count(*)::integer into v_later_imports
  from public.student_import_runs later_run
  where later_run.academic_year = v_run.academic_year
    and later_run.status = 'applied'
    and (
      later_run.created_at > v_run.created_at
      or (later_run.created_at = v_run.created_at and later_run.id::text > v_run.id::text)
    );

  if v_run.snapshot_count > 0 then
    select count(*)::integer into v_changed_students
    from public.student_import_snapshots snap
    left join public.students s on s.id = snap.student_id
    left join public.student_details d on d.student_id = snap.student_id
    left join public.student_growth g
      on g.student_id = snap.student_id and g.measured_on = v_run.measured_on
    left join public.student_year_rosters roster
      on roster.student_id = snap.student_id and roster.academic_year = v_run.academic_year
    where snap.import_id = v_run.id
      and (
        (snap.was_student_present and s.id is null)
        or (s.id is not null and s.updated_at > v_run.applied_at)
        or (snap.detail_row is not null and d.student_id is null)
        or (d.student_id is not null and d.updated_at > v_run.applied_at)
        or (snap.growth_row is not null and g.id is null)
        or (g.id is not null and g.updated_at > v_run.applied_at)
        or (roster.student_id is null)
        or (roster.updated_at > v_run.applied_at)
      );

    select count(*)::integer into v_dependent_records
    from (
      select a.student_id::text as student_id
      from public.attendance_daily a
      join public.student_import_snapshots snap on snap.student_id = a.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select a.student_id::text
      from public.attendance_monthly a
      join public.student_import_snapshots snap on snap.student_id = a.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select score.student_id::text
      from public.scores score
      join public.student_import_snapshots snap on snap.student_id = score.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select assessment.student_id::text
      from public.assessments assessment
      join public.student_import_snapshots snap on snap.student_id = assessment.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select comment_row.student_id::text
      from public.student_comments comment_row
      join public.student_import_snapshots snap on snap.student_id = comment_row.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select link.student_id::text
      from public.parent_student_links link
      join public.student_import_snapshots snap on snap.student_id = link.student_id::text
      where snap.import_id = v_run.id and not snap.was_student_present
      union all
      select growth.student_id::text
      from public.student_growth growth
      join public.student_import_snapshots snap on snap.student_id = growth.student_id::text
      where snap.import_id = v_run.id
        and not snap.was_student_present
        and growth.measured_on is distinct from v_run.measured_on
      union all
      select roster.student_id::text
      from public.student_year_rosters roster
      join public.student_import_snapshots snap on snap.student_id = roster.student_id::text
      where snap.import_id = v_run.id
        and not snap.was_student_present
        and roster.academic_year is distinct from v_run.academic_year
    ) dependencies;
  end if;

  v_eligible := v_run.status = 'applied'
    and v_run.snapshot_count > 0
    and v_later_imports = 0
    and v_changed_students = 0
    and v_dependent_records = 0;

  v_reason := case
    when v_run.status <> 'applied' then 'รายการนี้ถูกย้อนกลับแล้วหรือไม่ได้อยู่ในสถานะใช้งาน'
    when v_run.snapshot_count < 1 then 'รายการนี้สร้างก่อนติดตั้งระบบ snapshot จึงย้อนกลับอัตโนมัติไม่ได้'
    when v_later_imports > 0 then 'มีการนำเข้า DMC รายการใหม่กว่าของปีเดียวกัน ต้องย้อนรายการล่าสุดก่อน'
    when v_changed_students > 0 then format('มีนักเรียน %s คนถูกแก้ไขต่อหลังการนำเข้า', v_changed_students)
    when v_dependent_records > 0 then format('นักเรียนที่เพิ่มใหม่มีข้อมูลต่อเนื่อง %s รายการ', v_dependent_records)
    else 'พร้อมย้อนกลับอย่างปลอดภัย'
  end;

  return jsonb_build_object(
    'importId', v_run.id,
    'academicYear', v_run.academic_year,
    'status', v_run.status,
    'snapshotCount', v_run.snapshot_count,
    'insertedCount', v_run.inserted_count,
    'updatedCount', v_run.updated_count,
    'laterImportCount', v_later_imports,
    'changedStudentCount', v_changed_students,
    'dependentRecordCount', v_dependent_records,
    'eligible', v_eligible,
    'reason', v_reason
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_get_academic_year_transition_draft(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_draft public.academic_year_transition_drafts%rowtype;
  v_current_rev text;
  v_students jsonb;
begin
  perform public.pp5_assert_admin();

  select * into v_draft
  from public.academic_year_transition_drafts
  where id = p_draft_id;

  if v_draft.id is null then
    raise exception 'ไม่พบฉบับร่างการเลื่อนชั้นรหัส %', p_draft_id;
  end if;

  v_current_rev := public.pp5_compute_academic_year_revision(v_draft.source_year);

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', ts.id,
      'studentId', ts.student_id,
      'studentNumber', ts.source_student_number,
      'prefix', s.prefix,
      'firstName', s.first_name,
      'lastName', s.last_name,
      'nationalId', s.national_id,
      'sourceGrade', ts.source_grade,
      'sourceRoom', ts.source_room,
      'sourceEnrollmentStatus', ts.source_enrollment_status,
      'defaultAction', ts.default_action,
      'selectedAction', ts.selected_action,
      'targetGrade', ts.target_grade,
      'targetRoom', ts.target_room,
      'targetStudentNumber', ts.target_student_number,
      'reasonCode', ts.reason_code,
      'reasonNote', ts.reason_note,
      'validationErrors', ts.validation_errors,
      'warningCodes', ts.warning_codes
    ) order by ts.source_grade, ts.source_room, ts.source_student_number nulls last, s.id
  ), '[]'::jsonb)
  into v_students
  from public.academic_year_transition_students ts
  join public.students s on s.id = ts.student_id
  where ts.draft_id = p_draft_id;

  return jsonb_build_object(
    'success', true,
    'draft', to_jsonb(v_draft),
    'isRevisionMatching', (v_current_rev = v_draft.source_revision),
    'currentRevision', v_current_rev,
    'students', v_students
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_get_academic_years_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_items jsonb;
  v_current_year text;
begin
  select academic_year into v_current_year
  from public.school_settings
  order by updated_at desc nulls last
  limit 1;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'academicYear', y.academic_year,
      'isCurrent', (y.academic_year = v_current_year),
      'status', y.status,
      'isLocked', coalesce(y.is_locked, false),
      'lockedAt', y.locked_at,
      'lockReason', y.lock_reason,
      'dataManifest', y.data_manifest
    ) order by y.academic_year desc
  ), '[]'::jsonb)
  into v_items
  from public.academic_years y;

  return jsonb_build_object(
    'success', true,
    'currentYear', v_current_year,
    'years', v_items
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_get_year_report_context(p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v public.academic_year_report_snapshots%rowtype;
begin
  perform public.pp5_assert_admin();
  if p_year is null or p_year !~ '^[0-9]{4}$' then raise exception 'ปีการศึกษาไม่ถูกต้อง';end if;
  select * into v from public.academic_year_report_snapshots where academic_year=p_year order by captured_at desc,id desc limit 1;
  if v.id is null then raise exception 'ปีนี้ยังไม่มีสำเนาข้อมูลโรงเรียนและรายวิชา ห้ามใช้ข้อมูลปัจจุบันแทนปีเก่า';end if;
  return jsonb_build_object('id',v.id,'academic_year',v.academic_year,'revision',v.revision,'captured_at',v.captured_at,'provenance',v.provenance,'payload',v.payload);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_guard_public_settings_signatures()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.settings_json is not null and new.settings_json ?| array[
    'signatures', 'director_signature', 'directorSignature', 'academic_head_signature',
    'academicHeadSignature', 'teacher_signatures', 'teacherSignatures',
    'school_stamp', 'schoolStamp', 'include_signatures'
  ] then
    raise exception using
      errcode = '42501',
      message = 'Signatures and stamps are private and must not be written to school_settings. Use pp5_save_school_signatures instead.';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_history_set_year_lock(p_year text, p_locked boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_result jsonb; v_before jsonb;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  if p_year !~ '^\d{4}$' or length(btrim(coalesce(p_reason,''))) < 5 then
    raise exception 'กรุณาระบุปีและเหตุผลอย่างน้อย 5 ตัวอักษร';
  end if;
  select to_jsonb(y) into v_before from public.academic_years y where academic_year = p_year for update;
  if v_before is null or coalesce((v_before->>'is_current')::boolean, false)
     or exists(select 1 from public.school_settings where academic_year = p_year) then
    raise exception 'เปิดแก้ย้อนหลังได้เฉพาะปีเดิมที่มีทะเบียนแล้ว';
  end if;
  v_result := public.pp5_set_academic_year_lock(p_year, p_locked, p_reason);
  insert into public.audit_logs(actor_id, action, entity_type, entity_id, detail)
  values(auth.uid(), case when p_locked then 'lock_year' else 'unlock_year' end, 'academic_history', p_year,
    jsonb_build_object('academic_year',p_year,'reason',btrim(p_reason),'before',v_before,'after',v_result));
  return v_result;
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_line_issue_link_code()
 RETURNS TABLE(code text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code text;
  v_try integer := 0;
begin
  if auth.uid() is null or public.pp5_current_role() is distinct from 'parent' then
    raise exception using errcode = '42501', message = 'เฉพาะบัญชีผู้ปกครอง';
  end if;
  loop
    v_try := v_try + 1;
    -- gen_random_uuid() draws from a cryptographically strong source (random() does not).
    v_code := lpad(((('x' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))::bit(48)::bigint) % 1000000)::text, 6, '0');
    begin
      insert into public.line_link_codes (parent_user_id, code, expires_at)
      values (auth.uid(), v_code, now() + interval '15 minutes')
      on conflict (parent_user_id) do update set code = excluded.code, expires_at = excluded.expires_at;
      exit;
    exception when unique_violation then
      if v_try >= 10 then raise; end if;
    end;
  end loop;
  return query select v_code, now() + interval '15 minutes';
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_list_dmc_student_imports(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  perform public.pp5_assert_admin();

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'importId', history.id,
      'academicYear', history.academic_year,
      'fileName', history.file_name,
      'fileType', history.file_type,
      'sourceCount', history.source_count,
      'validCount', history.valid_count,
      'skippedCount', history.skipped_count,
      'insertedCount', history.inserted_count,
      'updatedCount', history.updated_count,
      'preservedMissingCount', history.preserved_missing_count,
      'snapshotCount', history.snapshot_count,
      'status', history.status,
      'createdAt', history.created_at,
      'appliedAt', history.applied_at,
      'rolledBackAt', history.rolled_back_at,
      'rollbackAvailable', (guard.result->>'eligible')::boolean,
      'rollbackReason', guard.result->>'reason'
    ) order by history.created_at desc, history.id desc
  ), '[]'::jsonb)
  into v_result
  from (
    select *
    from public.student_import_runs
    order by created_at desc, id desc
    limit greatest(1, least(coalesce(p_limit, 10), 50))
  ) history
  cross join lateral (
    select public.pp5_dmc_student_rollback_guard(history.id) as result
  ) guard;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_merge_settings_json(p_key text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  if coalesce(public.pp5_current_role(), '') <> 'admin' then
    raise exception 'Only admins may change school settings' using errcode = '42501';
  end if;
  if p_key is null or p_key !~ '^[a-z][a-z_]{0,39}$' then
    raise exception 'Invalid settings key' using errcode = '22023';
  end if;
  if p_key in ('signatures', 'director_signature', 'academic_head_signature', 'teacher_signatures', 'school_stamp') then
    raise exception 'Signatures must be saved through the private signature service' using errcode = '42501';
  end if;
  if p_value is null or octet_length(p_value::text) > 65536 then
    raise exception 'Invalid settings value' using errcode = '22023';
  end if;

  update public.school_settings s
     set settings_json = jsonb_set(coalesce(s.settings_json, '{}'::jsonb), array[p_key], p_value, true)
   where s.id = (select id from public.school_settings order by id limit 1)
  returning s.settings_json into v_result;

  if v_result is null then
    raise exception 'No school settings row (or no permission to change it)' using errcode = 'P0002';
  end if;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_normalize_context_json(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare result jsonb;
begin
 case jsonb_typeof(p_value)
 when 'number' then return to_jsonb(trim_scale((p_value#>>'{}')::numeric));
 when 'array' then select coalesce(jsonb_agg(public.pp5_normalize_context_json(value) order by n),'[]'::jsonb) into result from jsonb_array_elements(p_value) with ordinality x(value,n); return result;
 when 'object' then select coalesce(jsonb_object_agg(key,public.pp5_normalize_context_json(value)),'{}'::jsonb) into result from jsonb_each(p_value); return result;
 else return p_value;
 end case;
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_preview_academic_year_transition_rollback_v2(p_transition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_t public.academic_year_transitions%rowtype; v_blockers jsonb:='[]'::jsonb; v_students jsonb; v_rosters jsonb; v_settings jsonb; v_revision text; v_scores bigint; v_attendance bigint;
begin
  perform public.pp5_assert_admin();
  select * into v_t from public.academic_year_transitions where id=p_transition_id;
  if v_t.id is null then raise exception 'ไม่พบรายการเลื่อนชั้น'; end if;
  if v_t.status<>'applied' then v_blockers:=v_blockers||jsonb_build_array('รายการนี้ย้อนกลับไปแล้วหรือยังไม่ได้ดำเนินการ'); end if;
  if not (v_t.snapshot ?& array['studentsBefore','rostersBefore','settingsBefore','studentsAfter','rostersAfter','settingsAfter']) then
    v_blockers:=v_blockers||jsonb_build_array('รายการเก่าไม่มีสำเนาครบชุด ต้องตรวจและคืนข้อมูลโดยผู้ดูแล');
  end if;
  if not exists(select 1 from public.school_settings where academic_year=v_t.to_year)
    or exists(select 1 from public.academic_year_transitions where status='applied' and from_year=v_t.to_year) then
    v_blockers:=v_blockers||jsonb_build_array('ปีปัจจุบันเปลี่ยนไปแล้ว ย้อนรายการนี้อัตโนมัติไม่ได้');
  end if;
  select count(*) into v_scores from public.scores where academic_year=v_t.to_year;
  select count(*) into v_attendance from public.attendance_daily where academic_year=v_t.to_year;
  if v_scores>0 or v_attendance>0
    or exists(select 1 from public.attendance_monthly where academic_year=v_t.to_year)
    or exists(select 1 from public.assessments where academic_year=v_t.to_year)
    or exists(select 1 from public.student_growth where academic_year=v_t.to_year)
    or exists(select 1 from public.student_comments where academic_year=v_t.to_year)
    or exists(select 1 from public.teacher_assignments where academic_year=v_t.to_year) then
    v_blockers:=v_blockers||jsonb_build_array('ปีใหม่มีข้อมูลแล้ว ต้องแก้เฉพาะรายการ ห้ามย้อนทั้งปี');
  end if;
  select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) into v_students from public.students s
    where s.id in(select r->>'id' from jsonb_array_elements(coalesce(v_t.snapshot->'studentsBefore','[]'::jsonb)) r);
  select coalesce(jsonb_agg(to_jsonb(r) order by r.academic_year,r.student_id),'[]'::jsonb) into v_rosters from public.student_year_rosters r where r.academic_year in(v_t.from_year,v_t.to_year);
  select to_jsonb(s) into v_settings from public.school_settings s where s.id::text=v_t.snapshot#>>'{settingsBefore,id}';
  if v_students is distinct from v_t.snapshot->'studentsAfter'
    or v_rosters is distinct from v_t.snapshot->'rostersAfter'
    or v_settings is distinct from v_t.snapshot->'settingsAfter'
    or exists(select 1 from public.students where academic_year=v_t.to_year and id not in(select r->>'id' from jsonb_array_elements(coalesce(v_t.snapshot->'studentsBefore','[]'::jsonb)) r)) then
    v_blockers:=v_blockers||jsonb_build_array('ทะเบียนหรือข้อมูลนักเรียนเปลี่ยนหลังเลื่อนชั้น ต้องตรวจรายการเปลี่ยนแปลงก่อน');
  end if;
  v_revision:=md5(jsonb_build_array(v_t.id,v_t.status,v_students,v_rosters,v_settings,v_blockers)::text);
  return jsonb_build_object('success',true,'transitionId',v_t.id,'sourceYear',v_t.from_year,'targetYear',v_t.to_year,
    'canRollback',jsonb_array_length(v_blockers)=0,'blockers',v_blockers,'targetScoresCount',v_scores,'targetAttendanceCount',v_attendance,'revision',v_revision);
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_preview_academic_year_transition(p_target_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_year text;
  v_student_count integer := 0;
  v_roster_count integer := 0;
  v_promote_count integer := 0;
  v_graduate_count integer := 0;
  v_target_data_count integer := 0;
  v_grade_counts jsonb := '{}'::jsonb;
  v_unknown_grades jsonb := '[]'::jsonb;
  v_target_counts jsonb := '{}'::jsonb;
  v_blockers jsonb := '[]'::jsonb;
begin
  perform public.pp5_assert_admin();

  select academic_year
    into v_current_year
  from public.school_settings
  order by updated_at desc nulls last
  limit 1;

  if coalesce(trim(v_current_year), '') = '' then
    raise exception 'ไม่พบปีการศึกษาปัจจุบันในการตั้งค่าระบบ';
  end if;

  if coalesce(p_target_year, '') !~ '^[0-9]{4}$' then
    v_blockers := v_blockers || jsonb_build_array('ปีการศึกษาใหม่ต้องเป็นตัวเลข 4 หลัก');
  elsif coalesce(v_current_year, '') !~ '^[0-9]{4}$' then
    v_blockers := v_blockers || jsonb_build_array('ปีการศึกษาปัจจุบันไม่ใช่ตัวเลข 4 หลัก');
  elsif p_target_year::integer <> v_current_year::integer + 1 then
    v_blockers := v_blockers || jsonb_build_array(
      format('เพื่อความปลอดภัย ระบบอนุญาตให้เปลี่ยนจากปี %s เป็น %s เท่านั้น', v_current_year, v_current_year::integer + 1)
    );
  end if;

  select count(*)::integer
    into v_student_count
  from public.students
  where academic_year = v_current_year
    and status = 'active';

  select count(*)::integer
    into v_roster_count
  from public.student_year_rosters
  where academic_year = v_current_year
    and status = 'active';

  select coalesce(jsonb_object_agg(grade, grade_count), '{}'::jsonb)
    into v_grade_counts
  from (
    select grade, count(*)::integer as grade_count
    from public.students
    where academic_year = v_current_year
      and status = 'active'
    group by grade
    order by grade
  ) counts;

  select count(*)::integer
    into v_graduate_count
  from public.students
  where academic_year = v_current_year
    and status = 'active'
    and grade in ('ป.6', 'ม.3');

  select count(*)::integer
    into v_promote_count
  from public.students
  where academic_year = v_current_year
    and status = 'active'
    and grade in ('อ.1', 'อ.2', 'อ.3', 'ป.1', 'ป.2', 'ป.3', 'ป.4', 'ป.5', 'ม.1', 'ม.2');

  select coalesce(jsonb_agg(grade order by grade), '[]'::jsonb)
    into v_unknown_grades
  from (
    select distinct grade
    from public.students
    where academic_year = v_current_year
      and status = 'active'
      and grade not in ('อ.1', 'อ.2', 'อ.3', 'ป.1', 'ป.2', 'ป.3', 'ป.4', 'ป.5', 'ป.6', 'ม.1', 'ม.2', 'ม.3')
  ) unsupported;

  select jsonb_build_object(
      'students', (select count(*) from public.students where academic_year = p_target_year),
      'rosters', (select count(*) from public.student_year_rosters where academic_year = p_target_year),
      'teacherAssignments', (select count(*) from public.teacher_assignments where academic_year = p_target_year),
      'attendanceDaily', (select count(*) from public.attendance_daily where academic_year = p_target_year),
      'attendanceMonthly', (select count(*) from public.attendance_monthly where academic_year = p_target_year),
      'scores', (select count(*) from public.scores where academic_year = p_target_year),
      'assessments', (select count(*) from public.assessments where academic_year = p_target_year),
      'growth', (select count(*) from public.student_growth where academic_year = p_target_year),
      'comments', (select count(*) from public.student_comments where academic_year = p_target_year)
    )
    into v_target_counts;

  select coalesce(sum(value::integer), 0)::integer
    into v_target_data_count
  from jsonb_each_text(v_target_counts);

  if v_student_count = 0 then
    v_blockers := v_blockers || jsonb_build_array('ไม่พบนักเรียนสถานะ active ในปีปัจจุบัน');
  end if;

  if jsonb_array_length(v_unknown_grades) > 0 then
    v_blockers := v_blockers || jsonb_build_array(
      format('พบระดับชั้นที่ยังไม่มีกฎเลื่อนชั้น: %s', v_unknown_grades::text)
    );
  end if;

  if v_target_data_count > 0 then
    v_blockers := v_blockers || jsonb_build_array(
      format('ปี %s มีข้อมูลอยู่แล้ว %s รายการ จึงไม่อนุญาตให้เขียนทับ', p_target_year, v_target_data_count)
    );
  end if;

  if exists (
    select 1
    from public.academic_year_transitions
    where from_year = v_current_year
      and to_year = p_target_year
      and status = 'applied'
  ) then
    v_blockers := v_blockers || jsonb_build_array('มีรายการเปลี่ยนปีนี้ที่ใช้งานอยู่แล้ว');
  end if;

  return jsonb_build_object(
    'success', true,
    'canApply', jsonb_array_length(v_blockers) = 0,
    'currentYear', v_current_year,
    'suggestedNewYear', (v_current_year::integer + 1)::text,
    'targetYear', p_target_year,
    'studentCount', v_student_count,
    'currentRosterCount', v_roster_count,
    'gradeCounts', v_grade_counts,
    'promoteCount', v_promote_count,
    'graduateCount', v_graduate_count,
    'studentsPromoted', v_promote_count,
    'studentsGraduated', v_graduate_count,
    'unknownGrades', v_unknown_grades,
    'targetDataCount', v_target_data_count,
    'targetCounts', v_target_counts,
    'blockers', v_blockers,
    'snapshotCoverage', jsonb_build_array(
      'school_settings', 'students', 'student_year_rosters',
      'teacher_assignments', 'subjects', 'academic_years'
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_preview_dmc_student_import(p_rows jsonb, p_academic_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_incoming integer;
  v_existing integer;
  v_current_roster integer;
  v_preserved_missing integer;
  v_grade_counts jsonb;
begin
  perform public.pp5_validate_dmc_student_payload(p_rows, p_academic_year);
  v_incoming := jsonb_array_length(p_rows);

  select count(*)::integer into v_existing
  from public.students s
  where exists (
    select 1 from jsonb_array_elements(p_rows) item
    where item->>'student_id' = s.id
  );

  select count(*)::integer into v_current_roster
  from public.student_year_rosters
  where academic_year = p_academic_year and status = 'active';

  select count(*)::integer into v_preserved_missing
  from public.student_year_rosters roster
  where roster.academic_year = p_academic_year
    and roster.status = 'active'
    and not exists (
      select 1 from jsonb_array_elements(p_rows) item
      where item->>'student_id' = roster.student_id
    );

  select coalesce(jsonb_object_agg(class_name, student_count), '{}'::jsonb)
    into v_grade_counts
  from (
    select concat(item->>'grade', '/', item->>'room') as class_name,
           count(*)::integer as student_count
    from jsonb_array_elements(p_rows) item
    group by item->>'grade', item->>'room'
    order by item->>'grade', item->>'room'
  ) counts;

  return jsonb_build_object(
    'academicYear', p_academic_year,
    'incomingCount', v_incoming,
    'insertedCount', v_incoming - v_existing,
    'updatedCount', v_existing,
    'currentRosterCount', v_current_roster,
    'preservedMissingCount', v_preserved_missing,
    'resultRosterCount', v_incoming + v_preserved_missing,
    'gradeCounts', v_grade_counts,
    'destructiveChanges', 0
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_preview_dmc_student_rollback(p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return public.pp5_dmc_student_rollback_guard(p_import_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_preview_year_report_context(p_year text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb; v_current text; v_latest public.academic_year_report_snapshots%rowtype;
begin
  perform public.pp5_assert_admin();
  if p_year is null or p_year !~ '^[0-9]{4}$' then raise exception 'ปีการศึกษาไม่ถูกต้อง';end if;
  select academic_year into v_current from public.school_settings order by updated_at desc nulls last,id limit 1;
  select * into v_latest from public.academic_year_report_snapshots where academic_year=p_year order by captured_at desc,id desc limit 1;
  if p_year=v_current then v:=public.pp5_build_year_report_context(p_year);end if;
  return jsonb_build_object('academic_year',p_year,'current_year',v_current,'can_capture',p_year=v_current,
    'revision',case when v is not null then md5(v::text) end,
    'counts',case when v is not null then jsonb_build_object('rosters',jsonb_array_length(v->'rosters'),
      'subjects',jsonb_array_length(v->'subjects'),'teachers',jsonb_array_length(v->'teachers'),
      'assignments',jsonb_array_length(v->'assignments'),'details',jsonb_array_length(v->'details'),
      'signatures',jsonb_array_length(v->'signatures')) end,
    'snapshot',case when v_latest.id is not null then jsonb_build_object('id',v_latest.id,
      'revision',v_latest.revision,'captured_at',v_latest.captured_at,'captured_by',v_latest.captured_by,
      'reason',v_latest.reason,'provenance',v_latest.provenance) end,
    'changed_since_capture',case when v is not null then md5(v::text) is distinct from v_latest.revision end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_replace_parent_links(p_parent_user_id uuid, p_student_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_role text;
  target_role text;
  target_active boolean;
  clean_ids text[];
  existing_count integer;
begin
  select role into actor_role from public.user_profiles
    where id = auth.uid() and active = true for share;
  if actor_role is distinct from 'admin' then
    raise exception using errcode = '42501', message = 'Active administrator required';
  end if;
  select role, active into target_role, target_active
    from public.user_profiles where id = p_parent_user_id for update;
  if not found then
    raise exception using errcode = '22023', message = 'Parent profile does not exist';
  end if;
  if target_role is distinct from 'parent' then
    raise exception using errcode = '22023', message = 'Target profile is not a parent account';
  end if;
  select coalesce(array_agg(distinct btrim(id)), '{}'::text[])
    into clean_ids from unnest(coalesce(p_student_ids, '{}'::text[])) as id where btrim(id) <> '';
  if cardinality(clean_ids) > 0 then
    select count(*) into existing_count from public.students where id = any(clean_ids);
    if existing_count <> cardinality(clean_ids) then
      raise exception using errcode = '22023', message = 'One or more student IDs do not exist';
    end if;
  end if;
  delete from public.parent_student_links where parent_user_id = p_parent_user_id;
  insert into public.parent_student_links(parent_user_id, student_id)
    select p_parent_user_id, id from unnest(clean_ids) as id on conflict do nothing;
  return jsonb_build_object('success', true, 'studentIds', to_jsonb(clean_ids));
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_restore_academic_records(p_year text, p_students text[], p_rows jsonb, p_mode text DEFAULT 'missing_only'::text, p_revision text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_confirm text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare item jsonb; t text; raw jsonb; normalized jsonb; keys text[]; fields text[]; keyrow jsonb; oldrow jsonb; plan jsonb:='[]'; seen text[]:='{}'; fingerprint text; rev text; where_sql text; columns_sql text; values_sql text; set_sql text; inserted integer:=0; replaced integer:=0; skipped integer:=0; date_value date; start_date date; snapshot jsonb; snapshot_id uuid; context_before text; expected_grade numeric; total numeric;
begin
 perform public.pp5_assert_admin();
 perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
 lock table public.students,public.subjects,public.student_year_rosters,public.scores,public.assessments,public.attendance_daily,public.attendance_monthly,public.student_growth,public.student_comments,public.school_settings,public.academic_years,public.academic_year_report_snapshots in share row exclusive mode;
 if p_year is null or p_year !~ '^\d{4}$' or not exists(select 1 from academic_years where academic_year=p_year and not is_current and not is_locked) or exists(select 1 from school_settings where academic_year=p_year) then raise exception 'เปิดแก้ปีเก่าที่เลือกก่อนกู้คืน'; end if;
 if p_mode is null or p_mode not in ('missing_only','replace_selected') or coalesce(cardinality(p_students),0)=0 or cardinality(p_students)>1000 or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 1000 or octet_length(p_rows::text)>4000000 then raise exception 'เลือกนักเรียนและข้อมูลครั้งละ 1–1000 รายการ'; end if;
 if exists(select 1 from unnest(p_students) selected(student_id) where selected.student_id is null or not exists(select 1 from students existing where existing.id=selected.student_id)) then raise exception 'มีรหัสนักเรียนที่ไม่พบในระบบ ต้องตรวจทะเบียนก่อนกู้คืน'; end if;
 start_date:=make_date(p_year::integer-543,5,1);
 select coalesce(string_agg(id::text||':'||revision,',' order by captured_at,id),'') into context_before from academic_year_report_snapshots where academic_year=p_year;
 for item in select value from jsonb_array_elements(p_rows) loop
  if jsonb_typeof(item) is distinct from 'object' then raise exception 'รายการกู้คืนไม่ถูกต้อง'; end if;
  t:=item->>'table'; raw:=item->'row';
  if t='academic_year_report_snapshots' then
   if snapshot is not null or jsonb_typeof(raw->'payload') is distinct from 'object' or raw->>'academic_year' is distinct from p_year or raw#>>'{payload,academic_year}' is distinct from p_year or raw#>>'{payload,version}' is distinct from '1' or raw->>'revision' is distinct from md5((raw->'payload')::text) then raise exception 'สำเนาประจำปีไม่ตรงปีหรือผลตรวจความถูกต้อง'; end if;
   snapshot:=public.pp5_normalize_context_json(raw->'payload');
   if snapshot#>>'{school,school_name}' is null or jsonb_typeof(snapshot->'subjects') is distinct from 'array' or jsonb_array_length(snapshot->'subjects')=0 or jsonb_typeof(snapshot->'rosters') is distinct from 'array' or jsonb_typeof(snapshot->'students') is distinct from 'array' or jsonb_typeof(snapshot->'details') is distinct from 'array' or jsonb_typeof(snapshot->'assignments') is distinct from 'array' or jsonb_typeof(snapshot->'signatures') is distinct from 'array' or jsonb_typeof(snapshot->'holidays') is distinct from 'array' then raise exception 'ข้อมูลประกอบปีในสำเนาไม่ครบโครงสร้าง'; end if;
   continue;
  end if;
  case t
   when 'scores' then keys:=array['student_id','subject_id','semester','academic_year']; fields:=keys||array['formative_score','summative_score','total_score','grade_point','grade_text','score_breakdown'];
   when 'assessments' then keys:=array['student_id','assessment_type','criteria_code','semester','academic_year']; fields:=keys||array['score'];
   when 'attendance_daily' then keys:=array['student_id','attendance_date']; fields:=keys||array['academic_year','status','remark'];
   when 'attendance_monthly' then keys:=array['student_id','year_month','day_number']; fields:=keys||array['academic_year','status'];
   when 'student_growth' then keys:=array['student_id','measured_on']; fields:=keys||array['academic_year','weight_kg','height_cm','month','round_no','note','bmi','nutrition_status'];
   when 'student_comments' then keys:=array['student_id','academic_year','semester']; fields:=keys||array['comment'];
   when 'student_year_rosters' then keys:=array['student_id','academic_year']; fields:=keys||array['national_id','student_number','prefix','first_name','last_name','gender','grade','room','status','enrollment_status'];
   else raise exception 'ตารางนี้ไม่อนุญาตให้กู้คืน';
  end case;
  if jsonb_typeof(raw) is distinct from 'object' or raw->>'academic_year' is distinct from p_year or raw->>'student_id' is null or not (raw->>'student_id'=any(p_students)) or exists(select 1 from unnest(keys) k where raw->>k is null) then raise exception 'รายการอยู่นอกปีหรือนักเรียนที่เลือก'; end if;
  select jsonb_object_agg(k,raw->k) into normalized from unnest(fields) k where raw ? k;
  -- Populate the real composite type first: no arbitrary column names or SQL from the file.
  execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',t) into raw using normalized;
  select jsonb_object_agg(k,raw->k) into normalized from unnest(fields) k;
  select jsonb_object_agg(k,normalized->k) into keyrow from unnest(keys) k;
  fingerprint:=t||':'||keyrow::text;
  if fingerprint=any(seen) then raise exception 'ข้อมูลซ้ำในไฟล์ กรุณาตรวจให้เหลือหนึ่งรายการต่อรหัส'; end if; seen:=array_append(seen,fingerprint);
  if normalized ? 'semester' and coalesce((normalized->>'semester')::int,0) not in (1,2) then raise exception 'ภาคเรียนไม่ถูกต้อง'; end if;
  if t='scores' then
   if not exists(select 1 from subjects where id=normalized->>'subject_id') then raise exception 'ไม่พบรหัสรายวิชาเดิม ต้องตรวจหลักฐานก่อนกู้คืน'; end if;
   if coalesce((normalized->>'formative_score')::numeric,-1) not between 0 and 100 or coalesce((normalized->>'summative_score')::numeric,-1) not between 0 and 100 or coalesce((normalized->>'total_score')::numeric,-1) not between 0 and 100 or abs((normalized->>'total_score')::numeric-(normalized->>'formative_score')::numeric-(normalized->>'summative_score')::numeric)>0.051 or jsonb_typeof(normalized->'score_breakdown') is distinct from 'object' then raise exception 'คะแนนรวมในไฟล์ไม่ถูกต้อง'; end if;
   total:=round((normalized->>'total_score')::numeric);
   expected_grade:=case when total>=80 then 4 when total>=75 then 3.5 when total>=70 then 3 when total>=65 then 2.5 when total>=60 then 2 when total>=55 then 1.5 when total>=50 then 1 else 0 end;
   if (normalized->>'grade_point') is not null and (normalized->>'grade_point')::numeric<>expected_grade then raise exception 'ผลการเรียนในไฟล์ไม่ตรงคะแนน'; end if;
   if coalesce(normalized->>'grade_text','')<>'' and normalized->>'grade_text' not in ('ร','มส',expected_grade::text) then raise exception 'ข้อความผลการเรียนไม่ตรงคะแนน'; end if;
   if exists(select 1 from (values('total','total_score'),('mid','formative_score'),('final','summative_score')) x(k,f) where normalized->'score_breakdown' ? k and (normalized#>>array['score_breakdown',k])::numeric is distinct from (normalized->>f)::numeric) then raise exception 'รายละเอียดคะแนนไม่ตรงคะแนนรวม'; end if;
  elsif t='assessments' then
   if coalesce((normalized->>'score')::int,-1) not between 0 and 3 or (normalized->>'assessment_type'='activity' and (normalized->>'score')::int not in (0,1)) or btrim(normalized->>'criteria_code')='' then raise exception 'ผลประเมินไม่ถูกต้อง'; end if;
  elsif t in ('attendance_daily','attendance_monthly','student_growth') then
   if t='attendance_daily' then date_value:=(normalized->>'attendance_date')::date;
   elsif t='attendance_monthly' then date_value:=(normalized->>'year_month'||'-'||lpad(normalized->>'day_number',2,'0'))::date;
   else date_value:=(normalized->>'measured_on')::date;
    if coalesce((normalized->>'month')::int,0) not between 1 and 12 or coalesce((normalized->>'round_no')::int,0)<1 or (normalized->>'weight_kg')::numeric<=0 or (normalized->>'height_cm')::numeric<=0 then raise exception 'ข้อมูลการเติบโตไม่ถูกต้อง'; end if;
   end if;
   if date_value<start_date or date_value>=start_date+interval '1 year' then raise exception 'วันที่อยู่นอกปีการศึกษาที่เลือก'; end if;
   if t<>'student_growth' and coalesce(normalized->>'status','') not in ('present','absent','leave','late') then raise exception 'สถานะเวลาเรียนไม่ถูกต้อง'; end if;
  elsif t='student_comments' then
   if coalesce(btrim(normalized->>'comment'),'')='' then raise exception 'ความคิดเห็นว่าง'; end if;
  elsif t='student_year_rosters' then
   if coalesce(btrim(normalized->>'first_name'),'')='' or coalesce(btrim(normalized->>'last_name'),'')='' or coalesce(btrim(normalized->>'room'),'')='' or coalesce(normalized->>'grade','') not in ('อ.1','อ.2','อ.3','ป.1','ป.2','ป.3','ป.4','ป.5','ป.6') or coalesce(normalized->>'enrollment_status','') not in ('enrolled','completed','retained','graduated','transferred_out','withdrawn','deceased','pending_review') then raise exception 'ทะเบียนในไฟล์ไม่ถูกต้อง'; end if;
  end if;
  if t<>'student_year_rosters' and not exists(select 1 from student_year_rosters where academic_year=p_year and student_id=normalized->>'student_id') and not exists(select 1 from jsonb_array_elements(p_rows) z where z->>'table'='student_year_rosters' and z#>>'{row,academic_year}'=p_year and z#>>'{row,student_id}'=normalized->>'student_id') then raise exception 'ไม่พบทะเบียนปีนี้ เลือกกู้ทะเบียนพร้อมกันก่อน'; end if;
  select string_agg(format('t.%I::text=($1->>%L)',k,k),' and ') into where_sql from unnest(keys) k;
  execute format('select to_jsonb(t) from public.%I t where %s',t,where_sql) into oldrow using keyrow;
  if oldrow is not null and oldrow->>'academic_year' is distinct from p_year then raise exception 'รหัสวันที่ชนกับข้อมูลปีอื่น ห้ามเขียนทับข้ามปี'; end if;
  if oldrow is null then inserted:=inserted+1; elsif p_mode='missing_only' then skipped:=skipped+1; else replaced:=replaced+1; end if;
  plan:=plan||jsonb_build_array(jsonb_build_object('table',t,'key',keyrow,'fields',to_jsonb(fields),'row',normalized,'before',oldrow));
 end loop;
 rev:=md5(jsonb_build_object('year',p_year,'students',p_students,'mode',p_mode,'plan',plan,'snapshot',snapshot,'context_before',context_before)::text);
 if p_revision is null then return jsonb_build_object('revision',rev,'insert',inserted,'replace',replaced,'skip',skipped,'context',snapshot is not null,'items',plan); end if;
 if p_revision<>rev then raise exception 'ข้อมูลเปลี่ยนหลังตรวจรายการ กรุณาตรวจใหม่' using errcode='40001'; end if;
 if length(btrim(coalesce(p_reason,'')))<5 or p_confirm is distinct from 'CONFIRM_RESTORE_'||p_year||'_'||rev then raise exception 'ระบุเหตุผลและยืนยันรายการที่ตรวจแล้ว'; end if;
 -- Every item has been validated before any write. A later database failure rolls back all.
 for item in select value from jsonb_array_elements(plan) order by case when value->>'table'='student_year_rosters' then 0 else 1 end loop
  t:=item->>'table'; normalized:=item->'row'; oldrow:=nullif(item->'before','null'::jsonb); keyrow:=item->'key';
  if oldrow is not null and p_mode='missing_only' then continue; end if;
  select array_agg(value) into fields from jsonb_array_elements_text(item->'fields');
  if t in ('scores','student_comments','attendance_daily','attendance_monthly','student_growth') then
   fields:=fields||'recorded_by'::text;
   normalized:=normalized||jsonb_build_object('recorded_by',auth.uid());
  end if;
  select string_agg(format('%I',k),','),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',t,k),',') into columns_sql,values_sql from unnest(fields) k;
  if oldrow is null then
   execute format('insert into public.%I(%s) select %s',t,columns_sql,values_sql) using normalized;
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',k,t,k),',') into set_sql from unnest(fields) k;
   select string_agg(format('t.%I::text=($2->>%L)',k,k),' and ') into where_sql from jsonb_object_keys(keyrow) k;
   execute format('update public.%I t set %s,updated_at=clock_timestamp() where %s',t,set_sql,where_sql) using normalized,keyrow;
  end if;
  insert into audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'restore_record','academic_history',keyrow::text,jsonb_build_object('academic_year',p_year,'table',t,'reason',btrim(p_reason),'revision',rev,'before',oldrow,'after',normalized));
 end loop;
 if snapshot is not null then
  insert into academic_year_report_snapshots(academic_year,revision,payload,reason,captured_by,provenance) values(p_year,md5(snapshot::text),snapshot,btrim(p_reason),auth.uid(),'reviewed_backup') returning id into snapshot_id;
  insert into audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'restore_year_context','academic_history',snapshot_id::text,jsonb_build_object('academic_year',p_year,'reason',btrim(p_reason),'revision',md5(snapshot::text),'provenance','reviewed_backup'));
 end if;
 return jsonb_build_object('applied',true,'insert',inserted,'replace',replaced,'skip',skipped,'context_id',snapshot_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_rollback_academic_year_transition_v2(p_transition_id uuid, p_expected_revision text, p_confirmation_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_t public.academic_year_transitions%rowtype; v_preview jsonb; v_row jsonb;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  -- Block competing writes between preview validation and restoration.
  lock table public.students,public.student_year_rosters,public.school_settings,public.scores,
    public.attendance_daily,public.attendance_monthly,public.assessments,public.student_growth,
    public.student_comments,public.teacher_assignments in share row exclusive mode;
  select * into v_t from public.academic_year_transitions where id=p_transition_id for update;
  if v_t.id is null then raise exception 'ไม่พบรายการเลื่อนชั้น'; end if;
  v_preview:=public.pp5_preview_academic_year_transition_rollback_v2(p_transition_id);
  if not coalesce((v_preview->>'canRollback')::boolean,false) then raise exception 'ย้อนกลับไม่ได้: %',v_preview->'blockers'; end if;
  if p_expected_revision is distinct from v_preview->>'revision' then raise exception 'ข้อมูลเปลี่ยนหลังตรวจ กรุณาตรวจใหม่' using errcode='40001'; end if;
  if p_confirmation_token is distinct from format('CONFIRM_ROLLBACK_%s_TO_%s',v_t.from_year,v_t.to_year) then raise exception 'คำยืนยันไม่ถูกต้อง'; end if;
  -- Clear the unique current-year flag before restoring the previous year.
  update public.academic_years set is_current=false,status='closed',is_locked=false where academic_year=v_t.to_year;
  update public.academic_years set is_current=true,status='active',is_locked=false,locked_at=null,locked_by=null where academic_year=v_t.from_year;
  delete from public.student_year_rosters where academic_year=v_t.to_year and source_transition_id=p_transition_id;
  for v_row in select * from jsonb_array_elements(v_t.snapshot->'rostersBefore') loop
    update public.student_year_rosters set grade=v_row->>'grade',room=v_row->>'room',student_number=(v_row->>'student_number')::integer,
      enrollment_status=v_row->>'enrollment_status',status=v_row->>'status',updated_at=clock_timestamp()
      where academic_year=v_t.from_year and student_id=v_row->>'student_id';
  end loop;
  for v_row in select * from jsonb_array_elements(v_t.snapshot->'studentsBefore') loop
    update public.students set academic_year=v_row->>'academic_year',grade=v_row->>'grade',room=v_row->>'room',
      student_number=(v_row->>'student_number')::integer,status=v_row->>'status',updated_at=clock_timestamp() where id=v_row->>'id';
  end loop;
  update public.school_settings set academic_year=v_t.snapshot#>>'{settingsBefore,academic_year}',
    semester=(v_t.snapshot#>>'{settingsBefore,semester}')::integer,updated_at=clock_timestamp()
    where id::text=v_t.snapshot#>>'{settingsBefore,id}';
  update public.academic_year_transitions set status='rolled_back',rolled_back_at=clock_timestamp(),updated_at=clock_timestamp() where id=p_transition_id;
  update public.academic_year_transition_drafts set status='rolled_back',updated_at=clock_timestamp() where transition_id=p_transition_id;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'rollback_transition','academic_history',p_transition_id::text,
    jsonb_build_object('academic_year',v_t.from_year,'target_year',v_t.to_year,'reason','ยืนยันย้อนการเลื่อนชั้นก่อนเริ่มใช้ปีใหม่'));
  return jsonb_build_object('success',true,'transitionId',p_transition_id,'restoredYear',v_t.from_year);
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_rollback_academic_year_transition(p_transition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_transition public.academic_year_transitions%rowtype;
  v_settings_id text;
  v_target_data_count integer := 0;
  v_untracked_rosters integer := 0;
  v_untracked_assignments integer := 0;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));

  select *
    into v_transition
  from public.academic_year_transitions
  where id = p_transition_id
  for update;

  if v_transition.id is null then
    raise exception 'ไม่พบ snapshot ที่ระบุ';
  end if;
  if v_transition.status <> 'applied' then
    raise exception 'ย้อนกลับได้เฉพาะรายการที่มีสถานะ applied';
  end if;

  select id
    into v_settings_id
  from public.school_settings
  where academic_year = v_transition.to_year
  order by updated_at desc nulls last
  limit 1
  for update;

  if v_settings_id is null then
    raise exception 'ปีปัจจุบันไม่ตรงกับปีปลายทางของ snapshot';
  end if;

  select
      (select count(*) from public.attendance_daily where academic_year = v_transition.to_year)
    + (select count(*) from public.attendance_monthly where academic_year = v_transition.to_year)
    + (select count(*) from public.scores where academic_year = v_transition.to_year)
    + (select count(*) from public.assessments where academic_year = v_transition.to_year)
    + (select count(*) from public.student_growth where academic_year = v_transition.to_year)
    + (select count(*) from public.student_comments where academic_year = v_transition.to_year)
    into v_target_data_count;

  select count(*)::integer
    into v_untracked_rosters
  from public.student_year_rosters
  where academic_year = v_transition.to_year
    and source_transition_id is distinct from v_transition.id;

  select count(*)::integer
    into v_untracked_assignments
  from public.teacher_assignments
  where academic_year = v_transition.to_year
    and source_transition_id is distinct from v_transition.id;

  if v_target_data_count > 0 or v_untracked_rosters > 0 or v_untracked_assignments > 0 then
    raise exception 'ไม่สามารถย้อนกลับอัตโนมัติ: ปี % มีข้อมูลใหม่แล้ว (ธุรกรรม %, ทะเบียน %, ครูประจำชั้น %)',
      v_transition.to_year, v_target_data_count, v_untracked_rosters, v_untracked_assignments;
  end if;

  insert into public.students (
    id, national_id, student_number, prefix, first_name, last_name,
    gender, grade, room, academic_year, status, created_at, updated_at
  )
  select
    item->>'id', nullif(item->>'national_id', ''), nullif(item->>'student_number', '')::integer,
    item->>'prefix', item->>'first_name', item->>'last_name', item->>'gender',
    item->>'grade', item->>'room', item->>'academic_year', item->>'status',
    coalesce(nullif(item->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(item->>'updated_at', '')::timestamptz, now())
  from jsonb_array_elements(v_transition.snapshot->'students') item
  on conflict (id) do update
  set national_id = excluded.national_id,
      student_number = excluded.student_number,
      prefix = excluded.prefix,
      first_name = excluded.first_name,
      last_name = excluded.last_name,
      gender = excluded.gender,
      grade = excluded.grade,
      room = excluded.room,
      academic_year = excluded.academic_year,
      status = excluded.status,
      created_at = excluded.created_at,
      updated_at = excluded.updated_at;

  delete from public.student_year_rosters
  where academic_year = v_transition.to_year
    and source_transition_id = v_transition.id;

  delete from public.teacher_assignments
  where academic_year = v_transition.to_year
    and source_transition_id = v_transition.id;

  update public.academic_years
  set status = 'archived',
      is_current = false,
      closed_at = now(),
      updated_at = now()
  where academic_year = v_transition.to_year;

  insert into public.academic_years (
    academic_year, status, is_current, opened_at, closed_at, metadata, updated_at
  ) values (
    v_transition.from_year, 'active', true, now(), null,
    jsonb_build_object('restoredFromTransitionId', v_transition.id), now()
  )
  on conflict (academic_year) do update
  set status = 'active',
      is_current = true,
      closed_at = null,
      metadata = coalesce(public.academic_years.metadata, '{}'::jsonb)
        || jsonb_build_object('restoredFromTransitionId', v_transition.id),
      updated_at = now();

  update public.school_settings
  set academic_year = v_transition.from_year,
      semester = coalesce(nullif(v_transition.snapshot->'schoolSettings'->>'semester', '')::integer, 1),
      updated_at = now()
  where id = v_settings_id;

  update public.academic_year_transitions
  set status = 'rolled_back',
      rolled_back_at = now(),
      updated_at = now()
  where id = v_transition.id;

  if auth.uid() is not null then
    insert into public.audit_logs (actor_id, action, entity_type, entity_id, detail)
    values (
      auth.uid(), 'academic_year_transition_rolled_back', 'academic_year_transition',
      v_transition.id::text,
      jsonb_build_object('fromYear', v_transition.to_year, 'toYear', v_transition.from_year)
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'message', format('ย้อนกลับจากปี %s เป็นปี %s เรียบร้อยแล้ว', v_transition.to_year, v_transition.from_year),
    'transitionId', v_transition.id,
    'restoredToYear', v_transition.from_year,
    'studentCount', v_transition.student_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_rollback_dmc_student_import(p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run public.student_import_runs%rowtype;
  v_guard jsonb;
  v_summary jsonb;
  v_deleted_new_students integer := 0;
begin
  perform public.pp5_assert_admin();

  select * into v_run
  from public.student_import_runs
  where id = p_import_id
  for update;

  if v_run.id is null then
    raise exception 'ไม่พบประวัติการนำเข้า DMC ที่ระบุ';
  end if;

  -- Use the same year-scoped lock as the import RPC so an import and its
  -- rollback can never overlap.
  perform pg_advisory_xact_lock(hashtext('pp5_dmc_import:' || v_run.academic_year));

  -- Rollback is rare and admin-only. These locks make the safety check and
  -- restore one indivisible operation, so new attendance/score rows cannot
  -- appear after the guard has approved the rollback.
  lock table public.students, public.student_details, public.student_growth,
    public.student_year_rosters, public.attendance_daily, public.attendance_monthly,
    public.scores, public.assessments, public.student_comments,
    public.parent_student_links in share row exclusive mode;

  v_guard := public.pp5_dmc_student_rollback_guard(p_import_id);
  if coalesce((v_guard->>'eligible')::boolean, false) is not true then
    raise exception 'ไม่สามารถย้อนกลับอัตโนมัติ: %', coalesce(v_guard->>'reason', 'ไม่ผ่านเงื่อนไขความปลอดภัย');
  end if;

  insert into public.students (
    id, national_id, student_number, prefix, first_name, last_name,
    gender, grade, room, academic_year, status, created_at, updated_at
  )
  select
    snap.student_row->>'id', nullif(snap.student_row->>'national_id', ''),
    nullif(snap.student_row->>'student_number', '')::integer,
    snap.student_row->>'prefix', snap.student_row->>'first_name', snap.student_row->>'last_name',
    snap.student_row->>'gender', snap.student_row->>'grade', snap.student_row->>'room',
    snap.student_row->>'academic_year', snap.student_row->>'status',
    coalesce(nullif(snap.student_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.student_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.was_student_present
  on conflict (id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    academic_year = excluded.academic_year,
    status = excluded.status,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.student_details d
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = d.student_id
    and snap.detail_row is null;

  insert into public.student_details (
    student_id, birth_date, religion, blood_type, address,
    father_name, father_occupation, mother_name, mother_occupation,
    guardian_name, guardian_occupation, guardian_relation, guardian_phone,
    updated_at, ethnicity, nationality, subdistrict, district, province,
    father_last_name, mother_last_name, disadvantage, disposal_blocked, source_data
  )
  select
    snap.student_id, nullif(snap.detail_row->>'birth_date', '')::date,
    snap.detail_row->>'religion', snap.detail_row->>'blood_type', snap.detail_row->>'address',
    snap.detail_row->>'father_name', snap.detail_row->>'father_occupation',
    snap.detail_row->>'mother_name', snap.detail_row->>'mother_occupation',
    snap.detail_row->>'guardian_name', snap.detail_row->>'guardian_occupation',
    snap.detail_row->>'guardian_relation', snap.detail_row->>'guardian_phone',
    coalesce(nullif(snap.detail_row->>'updated_at', '')::timestamptz, now()),
    snap.detail_row->>'ethnicity', snap.detail_row->>'nationality',
    snap.detail_row->>'subdistrict', snap.detail_row->>'district', snap.detail_row->>'province',
    snap.detail_row->>'father_last_name', snap.detail_row->>'mother_last_name',
    snap.detail_row->>'disadvantage', snap.detail_row->>'disposal_blocked',
    coalesce(snap.detail_row->'source_data', '{}'::jsonb)
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.detail_row is not null
  on conflict (student_id) do update set
    birth_date = excluded.birth_date,
    religion = excluded.religion,
    blood_type = excluded.blood_type,
    address = excluded.address,
    father_name = excluded.father_name,
    father_occupation = excluded.father_occupation,
    mother_name = excluded.mother_name,
    mother_occupation = excluded.mother_occupation,
    guardian_name = excluded.guardian_name,
    guardian_occupation = excluded.guardian_occupation,
    guardian_relation = excluded.guardian_relation,
    guardian_phone = excluded.guardian_phone,
    updated_at = excluded.updated_at,
    ethnicity = excluded.ethnicity,
    nationality = excluded.nationality,
    subdistrict = excluded.subdistrict,
    district = excluded.district,
    province = excluded.province,
    father_last_name = excluded.father_last_name,
    mother_last_name = excluded.mother_last_name,
    disadvantage = excluded.disadvantage,
    disposal_blocked = excluded.disposal_blocked,
    source_data = excluded.source_data;

  delete from public.student_growth growth
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = growth.student_id
    and growth.measured_on = v_run.measured_on
    and snap.growth_row is null;

  insert into public.student_growth (
    id, student_id, measured_on, academic_year, weight_kg, height_cm,
    recorded_by, created_at, updated_at
  )
  select
    nullif(snap.growth_row->>'id', '')::bigint,
    snap.student_id,
    nullif(snap.growth_row->>'measured_on', '')::date,
    snap.growth_row->>'academic_year',
    nullif(snap.growth_row->>'weight_kg', '')::numeric,
    nullif(snap.growth_row->>'height_cm', '')::numeric,
    nullif(snap.growth_row->>'recorded_by', '')::uuid,
    coalesce(nullif(snap.growth_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.growth_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.growth_row is not null
  on conflict (student_id, measured_on) do update set
    academic_year = excluded.academic_year,
    weight_kg = excluded.weight_kg,
    height_cm = excluded.height_cm,
    recorded_by = excluded.recorded_by,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.student_year_rosters roster
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = roster.student_id
    and roster.academic_year = v_run.academic_year
    and snap.roster_row is null;

  insert into public.student_year_rosters (
    academic_year, student_id, national_id, student_number, prefix,
    first_name, last_name, gender, grade, room, status, source_transition_id,
    created_at, updated_at
  )
  select
    snap.roster_row->>'academic_year', snap.student_id,
    nullif(snap.roster_row->>'national_id', ''),
    nullif(snap.roster_row->>'student_number', '')::integer,
    snap.roster_row->>'prefix', snap.roster_row->>'first_name', snap.roster_row->>'last_name',
    snap.roster_row->>'gender', snap.roster_row->>'grade', snap.roster_row->>'room',
    snap.roster_row->>'status', nullif(snap.roster_row->>'source_transition_id', '')::uuid,
    coalesce(nullif(snap.roster_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.roster_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.roster_row is not null
  on conflict (academic_year, student_id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    status = excluded.status,
    source_transition_id = excluded.source_transition_id,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.students s
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and not snap.was_student_present
    and snap.student_id = s.id;
  get diagnostics v_deleted_new_students = row_count;

  v_summary := jsonb_build_object(
    'success', true,
    'importId', v_run.id,
    'academicYear', v_run.academic_year,
    'restoredStudentCount', v_run.updated_count,
    'removedNewStudentCount', v_deleted_new_students,
    'snapshotCount', v_run.snapshot_count,
    'message', format('ย้อนกลับการนำเข้า DMC ปี %s เรียบร้อยแล้ว', v_run.academic_year)
  );

  update public.student_import_runs
  set status = 'rolled_back',
      rolled_back_at = clock_timestamp(),
      rolled_back_by = auth.uid(),
      rollback_summary = v_summary
  where id = v_run.id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, detail)
  values (auth.uid(), 'dmc_student_import_rolled_back', 'student_import_run', v_run.id::text, v_summary);

  return v_summary;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_save_academic_year_transition_decisions(p_draft_id uuid, p_decisions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_draft public.academic_year_transition_drafts%rowtype;
  v_item jsonb;
  v_student_id text;
  v_action text;
  v_target_grade text;
  v_target_room text;
  v_reason_code text;
  v_reason_note text;
  v_updated_count integer := 0;
begin
  perform public.pp5_assert_admin();

  select * into v_draft
  from public.academic_year_transition_drafts
  where id = p_draft_id;

  if v_draft.id is null then
    raise exception 'ไม่พบฉบับร่างการเลื่อนชั้นรหัส %', p_draft_id;
  end if;

  if v_draft.status not in ('draft', 'validated') then
    raise exception 'ฉบับร่างนี้อยู่ในสถานะ % ไม่สามารถแก้ไขคำตัดสินได้', v_draft.status;
  end if;

  for v_item in select * from jsonb_array_elements(p_decisions)
  loop
    v_student_id := text(v_item->>'studentId');
    v_action := text(v_item->>'action');
    v_target_grade := v_item->>'targetGrade';
    v_target_room := coalesce(v_item->>'targetRoom', '1');
    v_reason_code := v_item->>'reasonCode';
    v_reason_note := v_item->>'reasonNote';

    if v_action not in ('promote', 'retain', 'graduate', 'transfer_out', 'withdraw', 'deceased', 'pending_review') then
      raise exception 'คำสั่ง % ไม่ถูกต้อง', v_action;
    end if;

    if v_action = 'retain' and coalesce(v_reason_note, '') = '' then
      raise exception 'กรณีซ้ำชั้น กรุณาระบุเหตุผลการซ้ำชั้น';
    end if;

    update public.academic_year_transition_students
    set selected_action = v_action,
        target_grade = case
          when v_action = 'retain' then source_grade
          when v_action = 'graduate' then null
          when v_action in ('transfer_out', 'withdraw', 'deceased') then null
          else coalesce(v_target_grade, target_grade)
        end,
        target_room = v_target_room,
        reason_code = v_reason_code,
        reason_note = v_reason_note,
        decided_by = auth.uid(),
        decided_at = now(),
        updated_at = now()
    where draft_id = p_draft_id and student_id = v_student_id;

    v_updated_count := v_updated_count + 1;
  end loop;

  -- Reset validated status back to draft so admin must re-validate
  update public.academic_year_transition_drafts
  set status = 'draft',
      updated_at = now()
  where id = p_draft_id;

  return jsonb_build_object(
    'success', true,
    'draftId', p_draft_id,
    'updatedCount', v_updated_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_save_school_signatures(p_settings_id text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_role text;
  signature_row public.school_signatures%rowtype;
  signature_key text;
begin
  select role into actor_role from public.user_profiles
    where id = auth.uid() and active = true for share;
  if actor_role is distinct from 'admin' then
    raise exception using errcode = '42501', message = 'Active administrator required';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'Signature payload must be an object';
  end if;
  if exists (select 1 from jsonb_object_keys(p_payload) k where k <> all (array[
      'director','academicHead','schoolStamp','teacher','teachers','replaceTeachers','includeSignatures'])) then
    raise exception using errcode = '22023', message = 'Unknown signature field';
  end if;
  foreach signature_key in array array['director','academicHead','schoolStamp','teacher'] loop
    if p_payload ? signature_key and jsonb_typeof(p_payload->signature_key) <> 'string' then
      raise exception using errcode = '22023', message = 'Signature image must be a string; empty string clears it';
    end if;
  end loop;
  if p_payload ? 'teachers' and jsonb_typeof(p_payload->'teachers') <> 'object' then
    raise exception using errcode = '22023', message = 'Teacher signatures must be an object';
  end if;
  if p_payload ? 'teachers' and exists (
    select 1 from jsonb_each(p_payload->'teachers') kv where jsonb_typeof(kv.value) <> 'string'
  ) then
    raise exception using errcode = '22023', message = 'Teacher signature image must be a string';
  end if;
  foreach signature_key in array array['replaceTeachers','includeSignatures'] loop
    if p_payload ? signature_key and jsonb_typeof(p_payload->signature_key) <> 'boolean' then
      raise exception using errcode = '22023', message = 'Signature option must be boolean';
    end if;
  end loop;

  perform 1 from public.school_settings where id = p_settings_id for update;
  if not found then raise exception using errcode = '22023', message = 'School settings not found'; end if;
  insert into public.school_signatures(settings_id) values (p_settings_id) on conflict do nothing;
  select * into signature_row from public.school_signatures where settings_id = p_settings_id for update;
  foreach signature_key in array array['director','academicHead','schoolStamp','teacher'] loop
    if p_payload ? signature_key then
      signature_row.signatures := jsonb_set(signature_row.signatures, array[signature_key], p_payload->signature_key);
    end if;
  end loop;
  if p_payload ? 'teachers' then
    signature_row.signatures := jsonb_set(signature_row.signatures, '{teachers}',
      case when p_payload->'replaceTeachers' = 'true'::jsonb then p_payload->'teachers'
      else coalesce(signature_row.signatures->'teachers', '{}'::jsonb) || (p_payload->'teachers') end);
  end if;
  if p_payload ? 'includeSignatures' then
    signature_row.include_signatures := (p_payload->>'includeSignatures')::boolean;
  end if;
  update public.school_signatures set signatures = signature_row.signatures,
    include_signatures = signature_row.include_signatures, updated_at = now() where settings_id = p_settings_id;
  return jsonb_build_object('success', true, 'signatures', signature_row.signatures,
    'includeSignatures', signature_row.include_signatures);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_save_score_batch(p_subject_id text, p_semester integer, p_academic_year text, p_rows jsonb, p_clear_student_ids text[] DEFAULT '{}'::text[], p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS SETOF scores
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_saved integer;
  v_expected integer;
  v_targets text[];
begin
  if auth.uid() is null or coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception 'Only active staff may save scores' using errcode = '42501';
  end if;
  if p_subject_id is null or btrim(p_subject_id) = '' or p_semester not in (1, 2)
     or p_semester is null or p_academic_year is null or p_academic_year !~ '^[0-9]{4}$'
     or p_rows is null or jsonb_typeof(p_rows) <> 'array' or p_clear_student_ids is null then
    raise exception 'Invalid score batch context' using errcode = '22023';
  end if;
  v_expected := jsonb_array_length(p_rows);
  if v_expected > 1000 or cardinality(p_clear_student_ids) > 1000 then
    raise exception 'Score batch exceeds 1000 students' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(p_clear_student_ids) id where id is null or btrim(id) = '') then
    raise exception 'Invalid cleared student ID' using errcode = '22023';
  end if;

  -- Cast the complete batch to the real table row type before any mutation.
  if exists (
    select 1 from jsonb_populate_recordset(null::public.scores, p_rows) r
    where r.student_id is null or btrim(r.student_id::text) = ''
       or r.subject_id::text is distinct from p_subject_id
       or r.semester::text is distinct from p_semester::text
       or r.academic_year::text is distinct from p_academic_year
       or r.student_id::text = any(p_clear_student_ids)
       or r.total_score is null or not (r.total_score between 0 and 100)
       or r.formative_score is null or not (r.formative_score between 0 and 100)
       or r.summative_score is null or not (r.summative_score between 0 and 100)
       or abs(r.total_score - r.formative_score - r.summative_score) > 0.051
       or r.grade_point is null or not (r.grade_point between 0 and 4)
  ) then
    raise exception 'Invalid row in score batch' using errcode = '22023';
  end if;
  if (select count(distinct r.student_id) from jsonb_populate_recordset(null::public.scores, p_rows) r) <> v_expected then
    raise exception 'Duplicate student in score batch' using errcode = '22023';
  end if;
  select array_agg(distinct id) into v_targets from (
    select r.student_id::text id from jsonb_populate_recordset(null::public.scores, p_rows) r
    union all select unnest(p_clear_student_ids)
  ) wanted;
  if coalesce(cardinality(v_targets), 0) = 0 then
    raise exception 'Empty score batch' using errcode = '22023';
  end if;

  -- Serialize score writers, including existing direct upserts, while validating
  -- the timestamp and applying deletions/upserts. The lock releases at commit.
  lock table public.scores in share row exclusive mode;
  if p_expected_updated_at is not null and exists (
    select 1 from public.scores s
    where s.subject_id::text = p_subject_id and s.semester::text = p_semester::text
      and s.academic_year::text = p_academic_year and s.student_id::text = any(v_targets)
      and s.updated_at > p_expected_updated_at
  ) then
    raise exception 'Scores changed after loading; reload before saving' using errcode = '40001';
  end if;

  delete from public.scores s
  where s.subject_id::text = p_subject_id and s.semester::text = p_semester::text
    and s.academic_year::text = p_academic_year and s.student_id::text = any(p_clear_student_ids);

  return query
    insert into public.scores (
      student_id, subject_id, semester, academic_year, formative_score,
      summative_score, total_score, grade_point, grade_text, score_breakdown,
      recorded_by, updated_at
    )
    select r.student_id, r.subject_id, r.semester, r.academic_year, r.formative_score,
      r.summative_score, r.total_score, r.grade_point, r.grade_text,
      coalesce(r.score_breakdown, '{}'::jsonb), auth.uid(), now()
    from jsonb_populate_recordset(null::public.scores, p_rows) r
    on conflict (student_id, subject_id, semester, academic_year) do update set
      formative_score = excluded.formative_score, summative_score = excluded.summative_score,
      total_score = excluded.total_score, grade_point = excluded.grade_point,
      grade_text = excluded.grade_text, score_breakdown = excluded.score_breakdown,
      recorded_by = excluded.recorded_by, updated_at = excluded.updated_at
    returning *;
  get diagnostics v_saved = row_count;
  if v_saved <> v_expected then
    raise exception 'Incomplete score batch; rolled back' using errcode = '40001';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_set_academic_year_lock(p_year text, p_locked boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_year text;
  v_exists boolean;
begin
  perform public.pp5_assert_admin();

  v_year := trim(coalesce(p_year, ''));
  if v_year = '' then
    raise exception 'กรุณาระบุปีการศึกษา';
  end if;

  select exists(select 1 from public.academic_years where academic_year = v_year) into v_exists;

  if not v_exists then
    insert into public.academic_years (
      academic_year, is_current, status, is_locked, lock_reason, locked_at, locked_by
    ) values (
      v_year, false, case when p_locked then 'closed' else 'active' end,
      p_locked, p_reason, case when p_locked then now() else null end, auth.uid()
    );
  else
    update public.academic_years
    set is_locked = p_locked,
        lock_reason = coalesce(p_reason, lock_reason),
        locked_at = case when p_locked then now() else null end,
        locked_by = auth.uid()
    where academic_year = v_year;
  end if;

  return jsonb_build_object(
    'success', true,
    'academicYear', v_year,
    'isLocked', p_locked,
    'reason', p_reason,
    'updatedAt', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_student_lifecycle(p_year text, p_student_id text, p_target jsonb, p_revision text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_confirm text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s public.students; r public.student_year_rosters; before_row jsonb; rev text; result jsonb; state text; g text; room_no text; num integer;
begin
 perform public.pp5_assert_admin();
 perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
 lock table public.students,public.student_year_rosters,public.school_settings,public.academic_years in share row exclusive mode;
 if p_year is null or p_year !~ '^\d{4}$' or not exists(select 1 from academic_years where academic_year=p_year and is_current and not is_locked)
 or (select count(*) from school_settings where academic_year=p_year)<>1 then raise exception 'เลือกปีปัจจุบันที่เปิดใช้งานเท่านั้น'; end if;
 select * into s from students where id=p_student_id for update;
 if not found then raise exception 'ไม่พบนักเรียน กรุณาตรวจรหัส'; end if;
 if jsonb_typeof(p_target) is distinct from 'object' or p_target-array['status','grade','room','student_number']<>'{}'::jsonb then raise exception 'ข้อมูลปลายทางไม่ถูกต้อง'; end if;
 state:=p_target->>'status'; g:=btrim(p_target->>'grade'); room_no:=btrim(p_target->>'room'); num:=(p_target->>'student_number')::integer;
 if state is null or state not in ('enrolled','retained','graduated','transferred_out','withdrawn','deceased')
 or g is null or g not in ('อ.1','อ.2','อ.3','ป.1','ป.2','ป.3','ป.4','ป.5','ป.6') or coalesce(room_no,'')='' or length(room_no)>30 or num<=0 then raise exception 'สถานะ ชั้น ห้อง หรือเลขที่ไม่ถูกต้อง'; end if;
 if state in ('enrolled','retained') and num is not null and exists(select 1 from student_year_rosters where academic_year=p_year and student_id<>p_student_id and grade=g and room=room_no and student_number=num and enrollment_status in ('enrolled','retained')) then raise exception 'เลขที่ซ้ำในห้องปลายทาง'; end if;
 select * into r from student_year_rosters where academic_year=p_year and student_id=p_student_id;
 before_row:=jsonb_build_object('student',to_jsonb(s),'roster',case when r.student_id is null then null else to_jsonb(r) end);
 rev:=md5((before_row||jsonb_build_object('target',p_target,'year',p_year))::text);
 result:=jsonb_build_object('revision',rev,'academic_year',p_year,'before',before_row,'target',p_target,'warning','คะแนนเดิมคงอยู่ตามรายวิชาและปีเดิม กรุณาตรวจรายวิชาเมื่อเปลี่ยนชั้น');
 if p_revision is null then return result; end if;
 if p_revision<>rev then raise exception 'ข้อมูลเปลี่ยน กรุณาตรวจรายการใหม่' using errcode='40001'; end if;
 if length(btrim(coalesce(p_reason,'')))<5 or p_confirm is distinct from 'CONFIRM_STUDENT_'||p_year||'_'||rev then raise exception 'ระบุเหตุผลและยืนยันรายการที่ตรวจแล้ว'; end if;
 update students set academic_year=p_year,grade=g,room=room_no,student_number=num,status=case when state in ('enrolled','retained') then 'active' else state end,updated_at=clock_timestamp() where id=p_student_id;
 insert into student_year_rosters(academic_year,student_id,national_id,student_number,prefix,first_name,last_name,gender,grade,room,status,enrollment_status,source)
 values(p_year,s.id,s.national_id,num,s.prefix,s.first_name,s.last_name,s.gender,g,room_no,case when state in ('enrolled','retained') then 'active' else state end,state,'manual')
 on conflict(academic_year,student_id) do update set grade=excluded.grade,room=excluded.room,student_number=excluded.student_number,status=excluded.status,enrollment_status=excluded.enrollment_status,source='manual',updated_at=clock_timestamp();
 insert into audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'student_lifecycle','academic_history',s.id,jsonb_build_object('academic_year',p_year,'reason',btrim(p_reason),'before',before_row,'after',(select to_jsonb(x) from student_year_rosters x where academic_year=p_year and student_id=s.id)));
 return result||jsonb_build_object('applied',true);
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_upsert_historical_record(p_table text, p_year text, p_key jsonb, p_expected jsonb, p_values jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_keys text[]; v_fields text[]; v_before jsonb; v_after jsonb; v_where text;
  v_ym text; v_gy integer; v_day integer; v_w numeric; v_h numeric; v_date date;
  v_action text; v_row jsonb;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  if p_year is null or p_year !~ '^\d{4}$' or length(btrim(coalesce(p_reason,''))) < 5 then
    raise exception 'กรุณาระบุปีและเหตุผลอย่างน้อย 5 ตัวอักษร';
  end if;
  if not exists(select 1 from public.academic_years where academic_year=p_year and not is_current and not is_locked)
    or exists(select 1 from public.school_settings where academic_year=p_year) then
    raise exception 'ปีนี้ยังล็อกอยู่หรือเป็นปีปัจจุบัน กรุณาเปิดแก้ปีเก่าก่อน';
  end if;
  case p_table
    when 'attendance_monthly' then v_keys := array['student_id','year_month','day_number']; v_fields := array['status'];
    when 'student_growth' then
      v_keys := array['student_id','academic_year','month','round_no'];
      v_fields := array['measured_on','weight_kg','height_cm','note','nutrition_status'];
    else raise exception 'ไม่อนุญาตให้แก้ตารางนี้';
  end case;
  if jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_values) is distinct from 'object'
    or (p_expected is not null and jsonb_typeof(p_expected) is distinct from 'object') then raise exception 'ข้อมูลไม่ถูกต้อง'; end if;
  if (select count(*) from jsonb_object_keys(p_key)) <> cardinality(v_keys)
    or exists(select 1 from unnest(v_keys) k where not p_key ? k or p_key->>k is null)
    or exists(select 1 from jsonb_object_keys(p_values) k where not k = any(v_fields))
    or p_values = '{}'::jsonb then raise exception 'ฟิลด์หรือรหัสข้อมูลไม่ถูกต้อง'; end if;
  if not exists(select 1 from public.student_year_rosters where academic_year=p_year and student_id=p_key->>'student_id') then
    raise exception 'ไม่พบทะเบียนนักเรียนของปีนี้';
  end if;
  if p_table='student_growth' and p_key->>'academic_year' is distinct from p_year then
    raise exception 'ปีในรหัสข้อมูลไม่ตรงกับปีที่เลือก';
  end if;

  if p_table='attendance_monthly' then
    v_ym := p_key->>'year_month';
    if v_ym !~ '^\d{4}-(0[1-9]|1[0-2])$' or p_key->>'day_number' !~ '^\d{1,2}$' then raise exception 'เดือนหรือวันไม่ถูกต้อง'; end if;
    v_gy := substr(v_ym,1,4)::integer; v_day := (p_key->>'day_number')::integer;
    -- Thai academic year Y runs May (Y-543) to April (Y-542); other months belong to another year.
    if v_ym < format('%s-05', p_year::integer-543) or v_ym > format('%s-04', p_year::integer-542) then
      raise exception 'เดือนไม่อยู่ในปีการศึกษาที่เลือก'; end if;
    if v_day < 1 or v_day > extract(day from (date_trunc('month', (v_ym||'-01')::date) + interval '1 month - 1 day'))::integer then
      raise exception 'วันที่ไม่มีอยู่ในเดือนนี้'; end if;
    if coalesce(p_values->>'status','') not in ('present','absent','leave','late') then raise exception 'สถานะเวลาเรียนไม่ถูกต้อง'; end if;
  else
    if p_key->>'month' !~ '^\d{1,2}$' or (p_key->>'month')::integer not between 1 and 12
       or p_key->>'round_no' !~ '^\d{1,2}$' or (p_key->>'round_no')::integer < 1 then raise exception 'เดือนหรือรอบไม่ถูกต้อง'; end if;
    v_w := nullif(p_values->>'weight_kg','')::numeric; v_h := nullif(p_values->>'height_cm','')::numeric;
    if (v_w is not null and v_w not between 3 and 200) or (v_h is not null and v_h not between 40 and 220) then
      raise exception 'น้ำหนักหรือส่วนสูงไม่สมเหตุสมผล'; end if;
    if p_values ? 'measured_on' then v_date := nullif(p_values->>'measured_on','')::date; end if;
  end if;

  select string_agg(format('t.%I::text = ($1->>%L)',k,k),' and ') into v_where from unnest(v_keys) k;
  execute format('select to_jsonb(t) from public.%I t where %s for update',p_table,v_where) into v_before using p_key;
  if v_before is not null and v_before->>'academic_year' is distinct from p_year then
    raise exception 'ข้อมูลนี้เป็นของปีการศึกษาอื่น ไม่อนุญาตให้แก้จากหน้านี้';
  end if;
  if p_table='student_growth' and v_date is not null and exists(select 1 from public.student_growth g
      where g.student_id=p_key->>'student_id' and g.measured_on=v_date and g.id is distinct from (v_before->>'id')::bigint) then
    raise exception 'นักเรียนคนนี้มีข้อมูลชั่งวัดในวันที่นี้แล้ว (รอบอื่น) กรุณาเลือกวันที่อื่น';
  end if;

  if v_before is null then
    if p_expected is not null then raise exception 'ข้อมูลถูกแก้หลังจากเปิด กรุณาโหลดใหม่' using errcode='40001'; end if;
    v_action := 'create_record';
    if p_table='attendance_monthly' then
      insert into public.attendance_monthly(student_id,year_month,day_number,status,academic_year,recorded_by)
        values(p_key->>'student_id',v_ym,v_day,p_values->>'status',p_year,auth.uid()) returning to_jsonb(attendance_monthly.*) into v_after;
    else
      if v_date is null then raise exception 'กรุณาระบุวันที่ชั่งวัด'; end if;
      insert into public.student_growth(student_id,academic_year,month,round_no,measured_on,weight_kg,height_cm,bmi,note,nutrition_status,recorded_by)
        values(p_key->>'student_id',p_year,(p_key->>'month')::smallint,(p_key->>'round_no')::smallint,v_date,v_w,v_h,
          case when v_w is not null and v_h is not null then round(v_w/((v_h/100)^2),2) end,
          nullif(btrim(p_values->>'note'),''),nullif(btrim(p_values->>'nutrition_status'),''),auth.uid())
        returning to_jsonb(student_growth.*) into v_after;
    end if;
  else
    v_action := 'correct_record';
    if p_expected is null or v_before is distinct from p_expected then
      raise exception 'ข้อมูลถูกแก้หลังจากเปิด กรุณาโหลดใหม่' using errcode='40001'; end if;
    if p_table='attendance_monthly' then
      update public.attendance_monthly set status=p_values->>'status',updated_at=clock_timestamp(),recorded_by=auth.uid()
        where id=(v_before->>'id')::bigint returning to_jsonb(attendance_monthly.*) into v_after;
    else
      v_row := v_before || p_values;
      v_w := nullif(v_row->>'weight_kg','')::numeric; v_h := nullif(v_row->>'height_cm','')::numeric;
      update public.student_growth set
        measured_on=coalesce(nullif(v_row->>'measured_on','')::date,measured_on), weight_kg=v_w, height_cm=v_h,
        bmi=case when v_w is not null and v_h is not null then round(v_w/((v_h/100)^2),2) end,
        note=nullif(btrim(v_row->>'note'),''), nutrition_status=nullif(btrim(v_row->>'nutrition_status'),''),
        updated_at=clock_timestamp(), recorded_by=auth.uid()
        where id=(v_before->>'id')::bigint returning to_jsonb(student_growth.*) into v_after;
    end if;
  end if;
  if v_after is null then raise exception 'ผลการบันทึกไม่ครบ ยกเลิกการแก้ไข'; end if;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail)
    values(auth.uid(),v_action,'academic_history',p_key::text,
      jsonb_build_object('academic_year',p_year,'table',p_table,'reason',btrim(p_reason),'before',v_before,'after',v_after));
  return v_after;
end; $function$;

CREATE OR REPLACE FUNCTION public.pp5_validate_academic_year_transition_draft(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_draft public.academic_year_transition_drafts%rowtype;
  v_current_rev text;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_pending_count integer := 0;
  v_retain_count integer := 0;
  v_promote_count integer := 0;
  v_graduate_count integer := 0;
  v_total_count integer := 0;
begin
  perform public.pp5_assert_admin();

  select * into v_draft
  from public.academic_year_transition_drafts
  where id = p_draft_id;

  if v_draft.id is null then
    raise exception 'ไม่พบฉบับร่างการเลื่อนชั้นรหัส %', p_draft_id;
  end if;

  v_current_rev := public.pp5_compute_academic_year_revision(v_draft.source_year);
  if v_current_rev <> v_draft.source_revision then
    v_blockers := v_blockers || jsonb_build_array('ข้อมูลนักเรียนเปลี่ยนหลังสร้างพรีวิว กรุณาสร้างพรีวิวใหม่');
  end if;

  select count(*) into v_pending_count
  from public.academic_year_transition_students
  where draft_id = p_draft_id and selected_action = 'pending_review';

  if v_pending_count > 0 then
    v_blockers := v_blockers || jsonb_build_array(
      format('ยังมีนักเรียนรอพิจารณา %s คน ห้าม Apply จนกว่าจะตัดสินครบ', v_pending_count)
    );
  end if;

  select count(*) into v_total_count from public.academic_year_transition_students where draft_id = p_draft_id;
  select count(*) into v_promote_count from public.academic_year_transition_students where draft_id = p_draft_id and selected_action = 'promote';
  select count(*) into v_graduate_count from public.academic_year_transition_students where draft_id = p_draft_id and selected_action = 'graduate';
  select count(*) into v_retain_count from public.academic_year_transition_students where draft_id = p_draft_id and selected_action = 'retain';

  if v_total_count = 0 then
    v_blockers := v_blockers || jsonb_build_array('ไม่มีรายชื่อนักเรียนในฉบับร่างนี้');
  end if;

  if jsonb_array_length(v_blockers) = 0 then
    update public.academic_year_transition_drafts
    set status = 'validated',
        blockers = '[]'::jsonb,
        warnings = v_warnings,
        validated_by = auth.uid(),
        validated_at = now(),
        summary = jsonb_build_object(
          'studentCount', v_total_count,
          'promoteCount', v_promote_count,
          'graduateCount', v_graduate_count,
          'retainCount', v_retain_count,
          'sourceYear', v_draft.source_year,
          'targetYear', v_draft.target_year
        ),
        updated_at = now()
    where id = p_draft_id;
  else
    update public.academic_year_transition_drafts
    set blockers = v_blockers,
        warnings = v_warnings,
        updated_at = now()
    where id = p_draft_id;
  end if;

  return jsonb_build_object(
    'success', true,
    'draftId', p_draft_id,
    'canApply', (jsonb_array_length(v_blockers) = 0),
    'blockers', v_blockers,
    'warnings', v_warnings,
    'summary', jsonb_build_object(
      'studentCount', v_total_count,
      'promoteCount', v_promote_count,
      'graduateCount', v_graduate_count,
      'retainCount', v_retain_count
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_validate_dmc_student_payload(p_rows jsonb, p_academic_year text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_current_year text;
begin
  perform public.pp5_assert_admin();

  if jsonb_typeof(p_rows) <> 'array'
     or jsonb_array_length(p_rows) < 1
     or jsonb_array_length(p_rows) > 5000 then
    raise exception 'ชุดข้อมูล DMC ต้องมีนักเรียน 1-5,000 คน';
  end if;

  if coalesce(p_academic_year, '') !~ '^[0-9]{4}$' then
    raise exception 'ปีการศึกษาไม่ถูกต้อง';
  end if;

  select academic_year into v_current_year
  from public.school_settings
  order by updated_at desc nulls last
  limit 1;

  if coalesce(v_current_year, '') = '' then
    raise exception 'ไม่พบปีการศึกษาปัจจุบันในการตั้งค่าระบบ';
  end if;
  if p_academic_year <> v_current_year then
    raise exception 'อนุญาตให้นำเข้า DMC เฉพาะปีการศึกษาปัจจุบัน %', v_current_year;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where coalesce(item->>'student_id', '') !~ '^[0-9]+$'
       or (coalesce(item->>'national_id', '') <> '' and item->>'national_id' !~ '^[0-9]{13}$')
       or coalesce(trim(item->>'first_name'), '') = ''
       or coalesce(trim(item->>'last_name'), '') = ''
       or coalesce(item->>'grade', '') !~ '^[ปอม]\.[0-9]+$'
       or coalesce(item->>'room', '') !~ '^[0-9]+$'
       or coalesce(item->>'gender', '') not in ('ชาย', 'หญิง')
       or (
         coalesce(item->>'birth_date', '') <> ''
         and item->>'birth_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       )
  ) then
    raise exception 'ชุดข้อมูล DMC มีแถวที่ไม่ผ่านการตรวจสอบฝั่งฐานข้อมูล';
  end if;

  if exists (
    select item->>'student_id'
    from jsonb_array_elements(p_rows) as item
    group by item->>'student_id'
    having count(*) > 1
  ) then
    raise exception 'พบรหัสนักเรียนซ้ำในชุดข้อมูล DMC';
  end if;
end;
$function$;


