-- ====================================================================================================
-- 10. Storage buckets and their rules
-- ====================================================================================================
do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'storage schema not found: buckets skipped (only on a plain PostgreSQL test)';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('report-exports', 'report-exports', false, 5242880, array['application/pdf']::text[])
    on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('school-branding', 'school-branding', true, 2097152, array['image/jpeg', 'image/png', 'image/webp']::text[])
    on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('student-photos', 'student-photos', false, 1048576, array['image/jpeg', 'image/png', 'image/webp']::text[])
    on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  execute 'drop policy if exists "pp5_report_exports_delete_own" on storage.objects';
  execute 'create policy "pp5_report_exports_delete_own" on storage.objects as permissive for delete to "authenticated" using (((bucket_id = ''report-exports''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)))';
  execute 'drop policy if exists "pp5_report_exports_insert_own" on storage.objects';
  execute 'create policy "pp5_report_exports_insert_own" on storage.objects as permissive for insert to "authenticated" with check (((bucket_id = ''report-exports''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)))';
  execute 'drop policy if exists "pp5_report_exports_read_own" on storage.objects';
  execute 'create policy "pp5_report_exports_read_own" on storage.objects as permissive for select to "authenticated" using (((bucket_id = ''report-exports''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)))';
  execute 'drop policy if exists "pp5_school_branding_delete" on storage.objects';
  execute 'create policy "pp5_school_branding_delete" on storage.objects as permissive for delete to "authenticated" using (((bucket_id = ''school-branding''::text) AND (pp5_current_role() = ''admin''::text)))';
  execute 'drop policy if exists "pp5_school_branding_insert" on storage.objects';
  execute 'create policy "pp5_school_branding_insert" on storage.objects as permissive for insert to "authenticated" with check (((bucket_id = ''school-branding''::text) AND (pp5_current_role() = ''admin''::text) AND ((storage.foldername(name))[1] = ''banner''::text)))';
  execute 'drop policy if exists "pp5_school_branding_read" on storage.objects';
  execute 'create policy "pp5_school_branding_read" on storage.objects as permissive for select to "authenticated" using (((bucket_id = ''school-branding''::text) AND (pp5_current_role() = ''admin''::text)))';
  execute 'drop policy if exists "pp5_school_branding_update" on storage.objects';
  execute 'create policy "pp5_school_branding_update" on storage.objects as permissive for update to "authenticated" using (((bucket_id = ''school-branding''::text) AND (pp5_current_role() = ''admin''::text))) with check (((bucket_id = ''school-branding''::text) AND (pp5_current_role() = ''admin''::text) AND ((storage.foldername(name))[1] = ''banner''::text)))';
  execute 'drop policy if exists "pp5_student_photos_delete" on storage.objects';
  execute 'create policy "pp5_student_photos_delete" on storage.objects as permissive for delete to "authenticated" using (((bucket_id = ''student-photos''::text) AND (pp5_current_role() = ANY (ARRAY[''admin''::text, ''teacher''::text]))))';
  execute 'drop policy if exists "pp5_student_photos_insert" on storage.objects';
  execute 'create policy "pp5_student_photos_insert" on storage.objects as permissive for insert to "authenticated" with check (((bucket_id = ''student-photos''::text) AND (pp5_current_role() = ANY (ARRAY[''admin''::text, ''teacher''::text])) AND (EXISTS ( SELECT 1
   FROM students s
  WHERE (s.id = (storage.foldername(objects.name))[1])))))';
  execute 'drop policy if exists "pp5_student_photos_read" on storage.objects';
  execute 'create policy "pp5_student_photos_read" on storage.objects as permissive for select to "authenticated" using (((bucket_id = ''student-photos''::text) AND pp5_can_read_student((storage.foldername(name))[1])))';
  execute 'drop policy if exists "pp5_student_photos_update" on storage.objects';
  execute 'create policy "pp5_student_photos_update" on storage.objects as permissive for update to "authenticated" using (((bucket_id = ''student-photos''::text) AND (pp5_current_role() = ANY (ARRAY[''admin''::text, ''teacher''::text])))) with check (((bucket_id = ''student-photos''::text) AND (pp5_current_role() = ANY (ARRAY[''admin''::text, ''teacher''::text])) AND (EXISTS ( SELECT 1
   FROM students s
  WHERE (s.id = (storage.foldername(objects.name))[1])))))';
end
$$;

