-- 11. Starting data: one settings row and the current academic year (Thai year, May = new year)
-- ====================================================================================================
do $$
declare
  v_year text := (extract(year from now())::int + 543 - case when extract(month from now()) < 5 then 1 else 0 end)::text;
begin
  insert into public.school_settings (id, school_name, academic_year, semester, settings_json)
    values ('default', 'ชื่อโรงเรียน (แก้ในหน้าตั้งค่าระบบกลาง)', v_year, 1, jsonb_build_object('grade_levels', 'primary'))
    on conflict (id) do nothing;
  insert into public.academic_years (academic_year, status, is_current) values (v_year, 'active', true)
    on conflict (academic_year) do nothing;
end
$$;

-- ====================================================================================================
-- 12. Installer helper: make the first administrator (run from the SQL Editor only)
-- ====================================================================================================
-- After creating the user in Authentication > Users:  select public.pp5_install_make_admin('admin@your-school.ac.th');
create or replace function public.pp5_install_make_admin(p_email text, p_display_name text default 'ผู้ดูแลระบบ')
returns text
language plpgsql
security definer
set search_path = public, auth, pg_temp
as $$
declare
  v_id uuid;
begin
  select id into v_id from auth.users where lower(email) = lower(btrim(p_email));
  if v_id is null then raise exception 'ไม่พบผู้ใช้ % ใน Authentication > Users กรุณาสร้างผู้ใช้ก่อน', p_email; end if;
  insert into public.user_profiles (id, username, role, display_name, allow_export, active)
    values (v_id, lower(btrim(p_email)), 'admin', p_display_name, true, true)
    on conflict (id) do update set role = 'admin', active = true, allow_export = true, updated_at = now();
  return 'ตั้งเป็นผู้ดูแลระบบแล้ว: ' || p_email;
end
$$;
revoke all on function public.pp5_install_make_admin(text, text) from public, anon, authenticated, service_role;

-- ====================================================================================================
-- 13. Repo migrations newer than the snapshot
-- ====================================================================================================
-- ---- 202610100026_lower_secondary_grades.sql ----
-- ม.ต้น (ม.1–ม.3) in the year-end transition and history corrections (owner 2026-10-10).
-- Generated by tools/build-lower-secondary-migration.mjs from the repo versions of these functions; only the
-- ม.ต้น lines differ:
--   * pp5_default_promoted_grade: ม.1 -> ม.2, ม.2 -> ม.3 (ป.6 and ม.3 still map to themselves, as before for ป.6)
--   * pp5_create_academic_year_transition_draft: ม.3 defaults to "graduate" like ป.6
--   * pp5_apply_academic_year_transition_v2_without_context (called by the v2 wrapper): accepts ม.1 -> ม.2, ม.2 -> ม.3
--   * pp5_correct_historical_record: a past-year roster may hold ม.1–ม.3
-- A primary-only school sees no difference (no ม. students).
-- Safety: the first block checks each live function body against the repo version and stops, changing nothing,
-- if any differs. Rollback: supabase/rollbacks/202610100026_lower_secondary_grades_rollback.sql
-- (202610100026_lower_secondary_grades.sql: runs inside this file's transaction)
do $$
declare
  v_expected constant jsonb := '{"public.pp5_default_promoted_grade(text)":"dfd144616de64c93dda1f3f5907ddd54","public.pp5_create_academic_year_transition_draft(text)":"08629e933f86a60e43b4421d901007f0","public.pp5_apply_academic_year_transition_v2_without_context(uuid,text,text)":"d6011109d7c956f0bf06f0b2cab60432","public.pp5_correct_historical_record(text,text,jsonb,jsonb,jsonb,text)":"d81b88e71f41398c3cf10577f32fa97c"}'::jsonb;
  v_sig text;
  v_hash text;
begin
  for v_sig in select jsonb_object_keys(v_expected) loop
    select md5(btrim(regexp_replace(p.prosrc, '\s+', ' ', 'g'))) into v_hash
      from pg_proc p where p.oid = to_regprocedure(v_sig);
    if v_hash is null then
      raise exception 'Stopped: function % is missing. Nothing was changed.', v_sig;
    end if;
    if v_hash <> v_expected->>v_sig then
      raise exception 'Stopped: function % on this database is not the version this file expects (it may have been replaced by another migration). Nothing was changed. Send this message to the developer.', v_sig;
    end if;
  end loop;
end
$$;

create or replace function public.pp5_default_promoted_grade(p_grade text)
returns text
language sql
immutable
as $$
  select case p_grade
    when 'อ.1' then 'อ.2'
    when 'อ.2' then 'อ.3'
    when 'อ.3' then 'ป.1'
    when 'ป.1' then 'ป.2'
    when 'ป.2' then 'ป.3'
    when 'ป.3' then 'ป.4'
    when 'ป.4' then 'ป.5'
    when 'ป.5' then 'ป.6'
    when 'ม.1' then 'ม.2'
    when 'ม.2' then 'ม.3'
    else p_grade
  end;
$$;

create or replace function public.pp5_create_academic_year_transition_draft(p_target_year text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_source_year text;
  v_existing_draft public.academic_year_transition_drafts%rowtype;
  v_draft_id uuid;
  v_revision text;
  v_student_count integer := 0;
  v_promote_count integer := 0;
  v_graduate_count integer := 0;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_target_data_count integer := 0;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));

  select academic_year into v_source_year
  from public.school_settings
  order by updated_at desc nulls last
  limit 1;

  if coalesce(trim(v_source_year), '') = '' then
    raise exception 'ไม่พบปีการศึกษาปัจจุบันในการตั้งค่าระบบ';
  end if;

  if coalesce(p_target_year, '') !~ '^[0-9]{4}$' then
    v_blockers := v_blockers || jsonb_build_array('ปีการศึกษาใหม่ต้องเป็นตัวเลข 4 หลัก');
  elsif p_target_year::integer <> v_source_year::integer + 1 then
    v_blockers := v_blockers || jsonb_build_array(
      format('เพื่อความปลอดภัย ระบบอนุญาตให้เปลี่ยนจากปี %s เป็น %s เท่านั้น', v_source_year, v_source_year::integer + 1)
    );
  end if;

  -- Check existing active draft (Idempotent return)
  select * into v_existing_draft
  from public.academic_year_transition_drafts
  where source_year = v_source_year
    and status in ('draft', 'validated')
  order by created_at desc
  limit 1;

  v_revision := public.pp5_compute_academic_year_revision(v_source_year);

  if v_existing_draft.id is not null then
    if v_existing_draft.source_revision = v_revision and v_existing_draft.target_year = p_target_year then
      return jsonb_build_object(
        'success', true,
        'draftId', v_existing_draft.id,
        'sourceYear', v_existing_draft.source_year,
        'targetYear', v_existing_draft.target_year,
        'status', v_existing_draft.status,
        'isIdempotent', true,
        'summary', v_existing_draft.summary,
        'blockers', v_existing_draft.blockers,
        'warnings', v_existing_draft.warnings
      );
    else
      -- Invalidate old stale draft
      update public.academic_year_transition_drafts
      set status = 'cancelled', updated_at = now()
      where id = v_existing_draft.id;
    end if;
  end if;

  -- Target year data check
  select count(*) into v_target_data_count
  from public.students
  where academic_year = p_target_year;

  if v_target_data_count > 0 then
    v_blockers := v_blockers || jsonb_build_array(
      format('ปี %s มีข้อมูลนักเรียนอยู่แล้ว %s คน จึงไม่อนุญาตให้สร้างทับ', p_target_year, v_target_data_count)
    );
  end if;

  -- Create fresh draft
  insert into public.academic_year_transition_drafts (
    source_year, target_year, status, source_revision, created_by
  ) values (
    v_source_year, p_target_year, 'draft', v_revision, auth.uid()
  ) returning id into v_draft_id;

  -- Populate student decision rows
  insert into public.academic_year_transition_students (
    draft_id, student_id, source_grade, source_room, source_student_number,
    source_enrollment_status, default_action, selected_action, target_grade, target_room
  )
  select
    v_draft_id,
    s.id,
    s.grade,
    s.room,
    s.student_number,
    coalesce(r.enrollment_status, 'enrolled'),
    case s.grade
      when 'ป.6' then 'graduate'
      when 'ม.3' then 'graduate'
      else 'promote'
    end as default_action,
    case s.grade
      when 'ป.6' then 'graduate'
      when 'ม.3' then 'graduate'
      else 'promote'
    end as selected_action,
    case s.grade
      when 'ป.6' then null
      when 'ม.3' then null
      else public.pp5_default_promoted_grade(s.grade)
    end as target_grade,
    s.room as target_room
  from public.students s
  left join public.student_year_rosters r
    on r.academic_year = v_source_year and r.student_id = s.id
  where s.academic_year = v_source_year
    and s.status = 'active';

  select count(*) into v_student_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id;

  select count(*) into v_promote_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id and selected_action = 'promote';

  select count(*) into v_graduate_count
  from public.academic_year_transition_students
  where draft_id = v_draft_id and selected_action = 'graduate';

  if v_student_count = 0 then
    v_blockers := v_blockers || jsonb_build_array('ไม่พบนักเรียนสถานะ active ในปีปัจจุบัน');
  end if;

  update public.academic_year_transition_drafts
  set summary = jsonb_build_object(
        'studentCount', v_student_count,
        'promoteCount', v_promote_count,
        'graduateCount', v_graduate_count,
        'retainCount', 0,
        'targetYear', p_target_year,
        'sourceYear', v_source_year
      ),
      blockers = v_blockers,
      warnings = v_warnings,
      updated_at = now()
  where id = v_draft_id;

  return jsonb_build_object(
    'success', true,
    'draftId', v_draft_id,
    'sourceYear', v_source_year,
    'targetYear', p_target_year,
    'status', 'draft',
    'studentCount', v_student_count,
    'promoteCount', v_promote_count,
    'graduateCount', v_graduate_count,
    'blockers', v_blockers,
    'warnings', v_warnings
  );
end;
$$;

create or replace function public.pp5_apply_academic_year_transition_v2_without_context(
  p_draft_id uuid,
  p_expected_revision text,
  p_confirmation_token text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_draft public.academic_year_transition_drafts%rowtype;
  v_current_rev text;
  v_expected_token text;
  v_settings public.school_settings%rowtype;
  v_transition_id uuid;
  v_manifest jsonb;
  v_student record;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));

  lock table public.students,public.student_year_rosters,public.school_settings,public.scores,
    public.attendance_daily,public.attendance_monthly,public.assessments,public.student_growth,
    public.student_comments,public.teacher_assignments in share row exclusive mode;

  select * into v_draft
  from public.academic_year_transition_drafts
  where id = p_draft_id
  for update;

  if v_draft.id is null then
    raise exception 'ไม่พบฉบับร่างการเลื่อนชั้นรหัส %', p_draft_id;
  end if;

  if v_draft.status <> 'validated' then
    raise exception 'ฉบับร่างต้องผ่านการตรวจสอบ (validated) ก่อน Apply เท่านั้น (สถานะปัจจุบัน: %)', v_draft.status;
  end if;

  v_expected_token := format('CONFIRM_APPLY_%s_TO_%s', v_draft.source_year, v_draft.target_year);
  if p_confirmation_token is distinct from v_expected_token then
    raise exception 'Confirmation token ไม่ถูกต้อง (ต้องการ: %)', v_expected_token;
  end if;

  v_current_rev := public.pp5_compute_academic_year_revision(v_draft.source_year);
  if v_current_rev is distinct from p_expected_revision or v_current_rev is distinct from v_draft.source_revision then
    raise exception 'Source revision ไม่ตรงกับค่าที่ตรวจสอบไว้ ข้อมูลมีการเปลี่ยนแปลงหลังการตรวจสอบ';
  end if;

  select * into v_settings
  from public.school_settings
  order by updated_at desc nulls last
  limit 1
  for update;

  if v_settings.academic_year is distinct from v_draft.source_year
     or v_draft.target_year::integer <> v_draft.source_year::integer+1 then
    raise exception 'ปีต้นทางไม่ใช่ปีปัจจุบันหรือปีปลายทางไม่ใช่ปีถัดไป';
  end if;
  if exists(select 1 from public.student_year_rosters where academic_year=v_draft.target_year)
    or exists(select 1 from public.students where academic_year=v_draft.target_year)
    or exists(select 1 from public.scores where academic_year=v_draft.target_year)
    or exists(select 1 from public.assessments where academic_year=v_draft.target_year)
    or exists(select 1 from public.attendance_daily where academic_year=v_draft.target_year)
    or exists(select 1 from public.attendance_monthly where academic_year=v_draft.target_year)
    or exists(select 1 from public.student_growth where academic_year=v_draft.target_year)
    or exists(select 1 from public.student_comments where academic_year=v_draft.target_year) then
    raise exception 'ปีปลายทางมีข้อมูลแล้ว ต้องตรวจสอบก่อนเลื่อนชั้น';
  end if;
  if exists(select 1 from public.academic_year_transition_students where draft_id=p_draft_id and selected_action='pending_review')
    or (select count(*) from public.academic_year_transition_students where draft_id=p_draft_id)
       <> (select count(*) from public.students where academic_year=v_draft.source_year and status='active') then
    raise exception 'คำตัดสินยังไม่ครบ';
  end if;
  if exists(select 1 from public.academic_year_transition_students ts join public.students s on s.id=ts.student_id
    where ts.draft_id=p_draft_id and (s.academic_year is distinct from v_draft.source_year or s.status<>'active'
      or s.grade is distinct from ts.source_grade or s.room is distinct from ts.source_room))
    or exists(select 1 from public.students s where s.academic_year=v_draft.source_year and s.status='active'
      and not exists(select 1 from public.student_year_rosters r where r.academic_year=v_draft.source_year and r.student_id=s.id)) then
    raise exception 'ทะเบียนต้นทางไม่ตรงกับฉบับร่างหรือไม่ครบ';
  end if;
  if exists(select 1 from public.academic_year_transition_students ts where ts.draft_id=p_draft_id
    and ts.selected_action in ('promote','retain') and (coalesce(btrim(ts.target_room),'')=''
      or ts.target_grade is distinct from case when ts.selected_action='retain' then ts.source_grade
        else case ts.source_grade when 'อ.1' then 'อ.2' when 'อ.2' then 'อ.3' when 'อ.3' then 'ป.1'
        when 'ป.1' then 'ป.2' when 'ป.2' then 'ป.3' when 'ป.3' then 'ป.4' when 'ป.4' then 'ป.5' when 'ป.5' then 'ป.6'
        when 'ม.1' then 'ม.2' when 'ม.2' then 'ม.3' end end)) then
    raise exception 'ชั้นหรือห้องปลายทางไม่ถูกต้อง';
  end if;
  -- Preserve exact lifecycle/settings/roster for rollback, not only row counts.
  -- Build data manifest before locking
  v_manifest := jsonb_build_object(
    'closedAt', now(),
    'sourceYear', v_draft.source_year,
    'targetYear', v_draft.target_year,
    'scoresCount', (select count(*) from public.scores where academic_year = v_draft.source_year),
    'attendanceDailyCount', (select count(*) from public.attendance_daily where academic_year = v_draft.source_year),
    'assessmentsCount', (select count(*) from public.assessments where academic_year = v_draft.source_year),
    'growthCount', (select count(*) from public.student_growth where academic_year = v_draft.source_year),
    'studentCount', (select count(*) from public.students where academic_year = v_draft.source_year and status = 'active')
  );

  -- Record in legacy transition table for audit & backward compatibility
  insert into public.academic_year_transitions (
    from_year, to_year, status, student_count, promoted_count,
    graduated_count, snapshot, summary, requested_by, applied_at
  ) values (
    v_draft.source_year, v_draft.target_year, 'applied',
    coalesce((v_draft.summary->>'studentCount')::integer, 0),
    coalesce((v_draft.summary->>'promoteCount')::integer, 0),
    coalesce((v_draft.summary->>'graduateCount')::integer, 0),
    jsonb_build_object('draftId', p_draft_id, 'manifest', v_manifest,
      'studentsBefore', (select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) from public.students s join public.academic_year_transition_students ts on ts.student_id=s.id where ts.draft_id=p_draft_id),
      'rostersBefore', (select coalesce(jsonb_agg(to_jsonb(r) order by r.student_id),'[]'::jsonb) from public.student_year_rosters r where r.academic_year=v_draft.source_year),
      'settingsBefore', to_jsonb(v_settings)),
    v_draft.summary,
    auth.uid(),
    now()
  ) returning id into v_transition_id;

  -- Process each student according to individual decision
  for v_student in
    select ts.*, s.status as student_lifecycle
    from public.academic_year_transition_students ts
    join public.students s on s.id = ts.student_id
    where ts.draft_id = p_draft_id
  loop
    -- Update closing year roster
    update public.student_year_rosters
    set enrollment_status = case v_student.selected_action
          when 'promote' then 'completed'
          when 'retain' then 'retained'
          when 'graduate' then 'graduated'
          when 'transfer_out' then 'transferred_out'
          when 'withdraw' then 'withdrawn'
          when 'deceased' then 'deceased'
          else 'completed'
        end,
        updated_at = now()
    where academic_year = v_draft.source_year and student_id = v_student.student_id;

    if v_student.selected_action in ('promote', 'retain') then
      -- Create provisional roster for target year
      insert into public.student_year_rosters (
        academic_year, student_id, prefix, first_name, last_name, gender, national_id, grade, room, student_number,
        enrollment_status, source, is_provisional, dmc_verification_status,
        source_transition_id, created_at, updated_at
      ) values (
        v_draft.target_year,
        v_student.student_id,
        (select prefix from public.students where id=v_student.student_id),
        (select first_name from public.students where id=v_student.student_id),
        (select last_name from public.students where id=v_student.student_id),
        (select gender from public.students where id=v_student.student_id),
        (select national_id from public.students where id=v_student.student_id),
        v_student.target_grade,
        v_student.target_room,
        v_student.target_student_number,
        'enrolled',
        'transition',
        true,
        'not_checked',
        v_transition_id,
        now(),
        now()
      ) on conflict (academic_year, student_id) do update
      set grade = excluded.grade,
          room = excluded.room,
          student_number = excluded.student_number,
          enrollment_status = 'enrolled',
          is_provisional = true,
          updated_at = now();

      -- Advance active student in main table
      update public.students
      set academic_year = v_draft.target_year,
          grade = v_student.target_grade,
          room = v_student.target_room,
          student_number = v_student.target_student_number,
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'graduate' then
      -- Lifecycle graduated, no target roster
      update public.students
      set status = 'graduated',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'transfer_out' then
      update public.students
      set status = 'transferred_out',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'withdraw' then
      update public.students
      set status = 'withdrawn',
          updated_at = now()
      where id = v_student.student_id;

    elsif v_student.selected_action = 'deceased' then
      update public.students
      set status = 'deceased',
          updated_at = now()
      where id = v_student.student_id;
    end if;
  end loop;

  update public.academic_year_transitions set snapshot=snapshot || jsonb_build_object(
    'studentsAfter',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]'::jsonb) from public.students s join public.academic_year_transition_students ts on ts.student_id=s.id where ts.draft_id=p_draft_id),
    'rostersAfter',(select coalesce(jsonb_agg(to_jsonb(r) order by r.academic_year,r.student_id),'[]'::jsonb) from public.student_year_rosters r where r.academic_year in (v_draft.source_year,v_draft.target_year)))
  where id=v_transition_id;
  -- Lock closing year and set target year as current
  insert into public.academic_years (
    academic_year, is_current, status, is_locked, locked_at, locked_by, lock_reason, data_manifest
  ) values (
    v_draft.source_year, false, 'closed', true, now(), auth.uid(), 'ปิดปีการศึกษาและเลื่อนชั้นสู่ปี ' || v_draft.target_year, v_manifest
  ) on conflict (academic_year) do update
  set is_current = false,
      status = 'closed',
      is_locked = true,
      locked_at = now(),
      locked_by = auth.uid(),
      lock_reason = excluded.lock_reason,
      data_manifest = v_manifest;

  insert into public.academic_years (
    academic_year, is_current, status, is_locked
  ) values (
    v_draft.target_year, true, 'active', false
  ) on conflict (academic_year) do update
  set is_current = true,
      status = 'active',
      is_locked = false;

  -- Update school_settings
  update public.school_settings
  set academic_year = v_draft.target_year,
      semester = 1,
      updated_at = now()
  where id = v_settings.id;

  update public.academic_year_transitions set snapshot=snapshot || jsonb_build_object('settingsAfter', (select to_jsonb(s) from public.school_settings s where s.id=v_settings.id)) where id=v_transition_id;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail) values(auth.uid(),'apply_transition','academic_history',v_transition_id::text,jsonb_build_object('academic_year',v_draft.source_year,'target_year',v_draft.target_year));
  -- Mark draft as applied
  update public.academic_year_transition_drafts
  set status = 'applied',
      applied_by = auth.uid(),
      applied_at = now(),
      transition_id = v_transition_id,
      updated_at = now()
  where id = p_draft_id;

  return jsonb_build_object(
    'success', true,
    'transitionId', v_transition_id,
    'sourceYear', v_draft.source_year,
    'targetYear', v_draft.target_year,
    'manifest', v_manifest
  );
end;
$$;

create or replace function public.pp5_correct_historical_record(
  p_table text, p_year text, p_key jsonb, p_expected jsonb, p_patch jsonb, p_reason text
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_keys text[]; v_fields text[]; v_before jsonb; v_after jsonb; v_merged jsonb;
  v_where text; v_set text; v_count integer; v_grade numeric; v_status text;
  v_sum numeric; v_rawmax numeric; v_finalmax numeric;
begin
  perform public.pp5_assert_admin();
  perform pg_advisory_xact_lock(hashtext('pp5_academic_year_transition'));
  if p_year is null or p_year !~ '^\d{4}$' or length(btrim(coalesce(p_reason,''))) < 5 then
    raise exception 'กรุณาระบุปีและเหตุผลอย่างน้อย 5 ตัวอักษร';
  end if;
  if not exists(select 1 from public.academic_years where academic_year=p_year and not is_current and not is_locked)
    or exists(select 1 from public.school_settings where academic_year=p_year) then
    raise exception 'ปีนี้ยังล็อกอยู่หรือเป็นปีปัจจุบัน กรุณาเปิดแก้ปีเก่าก่อน';
  end if;
  case p_table
    when 'scores' then
      v_keys := array['student_id','subject_id','semester','academic_year'];
      v_fields := array['formative_score','summative_score','total_score','grade_point','grade_text','score_breakdown'];
    when 'student_comments' then
      v_keys := array['student_id','academic_year','semester']; v_fields := array['comment'];
    when 'assessments' then v_keys := array['id']; v_fields := array['score'];
    when 'attendance_daily' then v_keys := array['student_id','attendance_date']; v_fields := array['status'];
    when 'student_year_rosters' then
      v_keys := array['student_id','academic_year']; v_fields := array['prefix','first_name','last_name','grade','room','student_number'];
    else raise exception 'ไม่อนุญาตให้แก้ตารางนี้';
  end case;
  if jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_patch) is distinct from 'object'
    or jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'ข้อมูลไม่ถูกต้อง'; end if;
  if (select count(*) from jsonb_object_keys(p_key)) <> cardinality(v_keys)
    or exists(select 1 from unnest(v_keys) k where not p_key ? k or p_key->>k is null)
    or exists(select 1 from jsonb_object_keys(p_patch) k where not k = any(v_fields))
    or p_patch = '{}'::jsonb then raise exception 'ฟิลด์หรือรหัสข้อมูลไม่ถูกต้อง'; end if;
  select string_agg(format('t.%I::text = ($1->>%L)',k,k),' and ') into v_where from unnest(v_keys) k;
  execute format('select to_jsonb(t) from public.%I t where %s and t.academic_year::text=$2 for update',p_table,v_where)
    into v_before using p_key,p_year;
  if v_before is null then raise exception 'ไม่พบข้อมูลในปีที่เลือก'; end if;
  if v_before is distinct from p_expected then raise exception 'ข้อมูลถูกแก้หลังจากเปิด กรุณาโหลดใหม่' using errcode='40001'; end if;
  if not exists(select 1 from public.student_year_rosters where academic_year=p_year and student_id=v_before->>'student_id') then
    raise exception 'ไม่พบทะเบียนนักเรียนของปีนี้';
  end if;
  v_merged := v_before || p_patch;
  if p_table='scores' then
    if not (p_patch ?& v_fields) then raise exception 'ต้องส่งคะแนนครบชุด'; end if;
    if jsonb_typeof(v_merged->'score_breakdown') is distinct from 'object'
      or (v_merged->'score_breakdown') - array['scores','mid','final','total','grade','entered','entryState']
        is distinct from coalesce(v_before->'score_breakdown','{}'::jsonb) - array['scores','mid','final','total','grade','entered','entryState'] then
      raise exception 'ห้ามเปลี่ยนข้อมูลประกอบและคะแนนเต็มเดิม';
    end if;
    if (v_merged->>'formative_score')::numeric is null or (v_merged->>'summative_score')::numeric is null
       or (v_merged->>'total_score')::numeric is null
       or not ((v_merged->>'formative_score')::numeric between 0 and 100)
       or not ((v_merged->>'summative_score')::numeric between 0 and 100)
       or not ((v_merged->>'total_score')::numeric between 0 and 100)
       or abs((v_merged->>'total_score')::numeric-(v_merged->>'formative_score')::numeric-(v_merged->>'summative_score')::numeric)>0.051 then
       raise exception 'คะแนนรวมไม่ถูกต้อง';
    end if;
    v_grade := case when round((v_merged->>'total_score')::numeric)>=80 then 4
      when round((v_merged->>'total_score')::numeric)>=75 then 3.5 when round((v_merged->>'total_score')::numeric)>=70 then 3
      when round((v_merged->>'total_score')::numeric)>=65 then 2.5 when round((v_merged->>'total_score')::numeric)>=60 then 2
      when round((v_merged->>'total_score')::numeric)>=55 then 1.5 when round((v_merged->>'total_score')::numeric)>=50 then 1 else 0 end;
    if (v_merged->>'grade_point')::numeric is distinct from v_grade
      or coalesce(v_merged->>'grade_text','') not in ('ร','มส',v_grade::text) then raise exception 'ผลการเรียนไม่ตรงกับคะแนน'; end if;
    if jsonb_typeof(v_before#>'{score_breakdown,scores}')='array' then
      if jsonb_typeof(v_merged#>'{score_breakdown,scores}') is distinct from 'array'
        or v_merged#>'{score_breakdown,fullScores}' is distinct from v_before#>'{score_breakdown,fullScores}'
        or v_merged#>'{score_breakdown,fullFinal}' is distinct from v_before#>'{score_breakdown,fullFinal}'
        or jsonb_array_length(v_merged#>'{score_breakdown,scores}') <> jsonb_array_length(v_before#>'{score_breakdown,scores}') then
        raise exception 'ห้ามเปลี่ยนโครงสร้างคะแนนเต็มระหว่างแก้ย้อนหลัง';
      end if;
      if exists(select 1 from jsonb_array_elements(v_merged#>'{score_breakdown,scores}') with ordinality a(val,n)
        where val::text::numeric < 0 or val::text::numeric > (v_merged#>'{score_breakdown,fullScores}'->>(n::int-1))::numeric) then
        raise exception 'คะแนนรายครั้งเกินคะแนนเต็ม';
      end if;
      select sum(val::text::numeric) into v_sum from jsonb_array_elements(v_merged#>'{score_breakdown,scores}') val;
      select sum(val::text::numeric) into v_rawmax from jsonb_array_elements(v_merged#>'{score_breakdown,fullScores}') val;
      v_finalmax := (v_merged#>>'{score_breakdown,fullFinal}')::numeric;
      if v_rawmax is null or v_rawmax<=0 or v_finalmax is null or v_finalmax not between 0 and 100
        or abs(round(v_sum/v_rawmax*(100-v_finalmax),1)-(v_merged->>'formative_score')::numeric)>0.051
        or (v_merged->>'summative_score')::numeric>v_finalmax then raise exception 'คะแนนรายครั้งไม่ตรงคะแนนรวม'; end if;
    end if;
    if (v_merged#>>'{score_breakdown,total}')::numeric is distinct from (v_merged->>'total_score')::numeric
      or (v_merged#>>'{score_breakdown,mid}')::numeric is distinct from (v_merged->>'formative_score')::numeric
      or (v_merged#>>'{score_breakdown,final}')::numeric is distinct from (v_merged->>'summative_score')::numeric then
      raise exception 'รายละเอียดคะแนนไม่ตรงคะแนนรวม'; end if;
  elsif p_table='attendance_daily' then
    if coalesce(v_merged->>'status','') not in ('present','absent','leave','late') then raise exception 'สถานะเวลาเรียนไม่ถูกต้อง'; end if;
  elsif p_table='assessments' then
    if (v_merged->>'score')::numeric is null or not ((v_merged->>'score')::numeric between 0 and 3) then raise exception 'ผลประเมินต้องอยู่ระหว่าง 0–3'; end if;
    if v_before->>'assessment_type'='activity' and (v_merged->>'score')::numeric not in (0,1) then raise exception 'กิจกรรมใช้ 0 หรือ 1'; end if;
  elsif p_table='student_comments' then
    if length(btrim(coalesce(v_merged->>'comment','')))=0 then raise exception 'กรุณาระบุความคิดเห็น'; end if;
  elsif p_table='student_year_rosters' then
    if length(btrim(coalesce(v_merged->>'first_name','')))=0 or length(btrim(coalesce(v_merged->>'last_name','')))=0
       or coalesce(v_merged->>'grade','') not in ('อ.1','อ.2','อ.3','ป.1','ป.2','ป.3','ป.4','ป.5','ป.6','ม.1','ม.2','ม.3')
       or length(btrim(coalesce(v_merged->>'room','')))=0 then raise exception 'ชื่อ ชั้น หรือห้องไม่ถูกต้อง'; end if;
  end if;
  select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$3)).%I',k,p_table,k),',') into v_set from jsonb_object_keys(p_patch) k;
  v_set := v_set || ',updated_at=clock_timestamp()';
  if p_table in ('scores','assessments','student_comments') then v_set:=v_set||',recorded_by=auth.uid()'; end if;
  execute format('update public.%I t set %s where %s and t.academic_year::text=$2 returning to_jsonb(t)',p_table,v_set,v_where)
    into v_after using p_key,p_year,v_merged;
  get diagnostics v_count=row_count;
  if v_count<>1 then raise exception 'ผลการบันทึกไม่ครบ ยกเลิกการแก้ไข'; end if;
  insert into public.audit_logs(actor_id,action,entity_type,entity_id,detail)
    values(auth.uid(),'correct_record','academic_history',p_key::text,
      jsonb_build_object('academic_year',p_year,'table',p_table,'reason',btrim(p_reason),'before',v_before,'after',v_after));
  return v_after;
end; $$;
-- ---- 202610110027_teacher_scope.sql ----
-- Stage scoped teacher access. Applying this file does NOT enable enforcement.
-- Owner applies in SQL Editor on the TEST project first; see docs/TEACHER_PERMISSIONS.md.
-- (202610110027_teacher_scope.sql: runs inside this file's transaction)
create table if not exists public.teacher_scope_settings (
  id boolean primary key default true check (id),
  enabled boolean not null default false,
  legacy_backfilled boolean not null default false,
  updated_at timestamptz not null default now()
);
insert into public.teacher_scope_settings(id) values (true) on conflict do nothing;
create table if not exists public.teacher_access_assignments (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  academic_year text not null check (academic_year ~ '^[0-9]{4}$'),
  scope text not null check (scope in ('homeroom','subject')),
  grade text not null check (grade ~ '^(ป\.[1-6]|ม\.[1-3])$'),
  room text not null check (length(btrim(room)) > 0),
  subject_id text references public.subjects(id),
  semester smallint not null default 0 check (semester in (0,1,2)),
  active boolean not null default true,
  check ((scope = 'homeroom' and subject_id is null and semester = 0)
      or (scope = 'subject' and subject_id is not null))
);
create unique index if not exists teacher_access_unique on public.teacher_access_assignments
  (user_id, academic_year, scope, grade, room, coalesce(subject_id,''), semester);
alter table public.teacher_scope_settings enable row level security;
alter table public.teacher_access_assignments enable row level security;
revoke all on public.teacher_scope_settings, public.teacher_access_assignments from public, anon, authenticated;
grant select on public.teacher_scope_settings, public.teacher_access_assignments to authenticated;
grant all on public.teacher_scope_settings, public.teacher_access_assignments to service_role;
drop policy if exists scope_settings_read on public.teacher_scope_settings;
create policy scope_settings_read on public.teacher_scope_settings for select to authenticated using (auth.uid() is not null);
drop policy if exists scope_assignments_read on public.teacher_access_assignments;
create policy scope_assignments_read on public.teacher_access_assignments for select to authenticated
  using (public.pp5_current_role() = 'admin' or (user_id = auth.uid() and public.pp5_current_role() = 'teacher'));

create or replace function public.pp5_teacher_scope_enabled()
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select enabled from public.teacher_scope_settings where id),false)
$$;
create or replace function public.pp5_teacher_scope_year()
returns text language sql stable security definer set search_path = public, pg_temp as $$
  select academic_year from public.school_settings order by id limit 1
$$;

-- Never infer identity from printable teacher names. Copy only existing account IDs.
do $$ begin
if not (select legacy_backfilled from public.teacher_scope_settings where id) then
insert into public.teacher_access_assignments(user_id, academic_year, scope, grade, room)
select distinct a.user_id,a.academic_year,'homeroom',a.grade,a.room
from public.teacher_assignments a join public.user_profiles p on p.id=a.user_id
where a.active and p.active and p.role='teacher' and a.grade ~ '^(ป\.[1-6]|ม\.[1-3])$'
on conflict do nothing;
insert into public.teacher_access_assignments(user_id, academic_year, scope, grade, room)
select p.id,public.pp5_teacher_scope_year(),'homeroom',p.grade,p.room from public.user_profiles p
where p.active and p.role='teacher' and p.grade ~ '^(ป\.[1-6]|ม\.[1-3])$' and nullif(btrim(p.room),'') is not null
  and public.pp5_teacher_scope_year() ~ '^[0-9]{4}$'
on conflict do nothing;
update public.teacher_scope_settings set legacy_backfilled=true where id;
end if;
end $$;

-- SECURITY DEFINER reads the roster without recursing through its RLS. The caller is always auth.uid().
-- roster_names is reserved for the minimal-name RPC, NOT a base-table policy.
create or replace function public.pp5_teacher_scope_access(
  p_table text, p_student text, p_year text default null,
  p_subject text default null, p_semester integer default null, p_write boolean default false)
returns boolean language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_role text := public.pp5_current_role();
  v_year text := coalesce(p_year,public.pp5_teacher_scope_year());
begin
  if v_role='admin' then return true; end if;
  if not p_write and v_role='parent' then return public.pp5_can_read_student(p_student); end if;
  if v_role is distinct from 'teacher' then return false; end if;
  if p_table not in ('students','student_year_rosters','student_details','scores','assessments',
      'attendance_daily','attendance_monthly','student_comments','student_growth','behavior_records','roster_names')
    then return false; end if;
  if p_write and (v_year is null or not exists(select 1 from public.academic_years
      where academic_year=v_year and status='active' and not is_locked)) then return false; end if;
  return exists(
    select 1 from public.teacher_access_assignments a
    where a.user_id=auth.uid() and a.active
      and (a.academic_year=v_year or (p_year is null and not p_write and p_table in ('students','roster_names')))
      and (
        exists(select 1 from public.student_year_rosters r where r.student_id=p_student
          and r.academic_year=a.academic_year and r.grade=a.grade and r.room=a.room)
        or (not exists(select 1 from public.student_year_rosters r where r.student_id=p_student and r.academic_year=a.academic_year)
          and exists(select 1 from public.students s where s.id=p_student and s.academic_year=a.academic_year
            and s.grade=a.grade and s.room=a.room))
      )
      and (p_table<>'scores' or (p_semester in (1,2) and exists(
        select 1 from public.subjects s where s.id=p_subject and s.grade=a.grade
          and (s.semester is null or s.semester=p_semester))))
      and (a.scope='homeroom' or (a.scope='subject' and (
        p_table='roster_names' or (p_table='scores' and a.subject_id=p_subject
          and (a.semester=0 or a.semester=p_semester)
          and exists(select 1 from public.subjects s where s.id=p_subject and s.grade=a.grade
            and (s.semester is null or s.semester=p_semester)))
      )))
  );
end $$;

create or replace function public.pp5_teacher_scope_context()
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_role text := public.pp5_current_role();
begin
  if v_role is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object('installed',true,'enabled',public.pp5_teacher_scope_enabled(),
    'role',v_role,'userId',auth.uid(),'academicYear',public.pp5_teacher_scope_year(),
    'assignments',coalesce((select jsonb_agg(to_jsonb(a) order by a.academic_year,a.grade,a.room,a.scope,a.subject_id)
      from public.teacher_access_assignments a where a.user_id=auth.uid() and a.active),'[]'::jsonb));
end $$;

-- Subject teachers receive only the roster fields needed for score entry, never identity/family/health data.
create or replace function public.pp5_teacher_scope_roster(p_year text)
returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if public.pp5_current_role() is distinct from 'teacher' then raise exception 'TEACHER_REQUIRED' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id',r.student_id,'student_id',r.student_id,
    'prefix',r.prefix,'first_name',r.first_name,'last_name',r.last_name,'gender',r.gender,
    'student_number',r.student_number,'grade',r.grade,'room',r.room,'academic_year',r.academic_year,'status',r.status)
    order by r.grade,r.room,r.student_number)
    from (
      select student_id,prefix,first_name,last_name,gender,student_number,grade,room,academic_year,status
      from public.student_year_rosters where academic_year=p_year
      union all
      select s.id,s.prefix,s.first_name,s.last_name,s.gender,s.student_number,s.grade,s.room,s.academic_year,s.status
      from public.students s where s.academic_year=p_year and not exists(
        select 1 from public.student_year_rosters r where r.student_id=s.id and r.academic_year=p_year)
    ) r where public.pp5_teacher_scope_access('roster_names',r.student_id,p_year)), '[]'::jsonb);
end $$;

create or replace function public.pp5_replace_teacher_access(p_user uuid,p_year text,p_assignments jsonb)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare v jsonb; v_scope text; v_subject public.subjects%rowtype;
begin
  if public.pp5_current_role() is distinct from 'admin' then raise exception 'ADMIN_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.user_profiles where id=p_user and role='teacher' and active)
    then raise exception 'เลือกบัญชีครูที่เปิดใช้งาน'; end if;
  if p_year !~ '^[0-9]{4}$' or p_year is null or not exists(select 1 from public.academic_years where academic_year=p_year)
    then raise exception 'ปีการศึกษาไม่ถูกต้อง'; end if;
  if jsonb_typeof(p_assignments) is distinct from 'array' or jsonb_array_length(p_assignments)>200
    then raise exception 'รายการมอบหมายไม่ถูกต้อง'; end if;
  -- Serialize competing editors and activation; validate the entire request before replacing anything.
  perform 1 from public.teacher_scope_settings where id for update;
  for v in select value from jsonb_array_elements(p_assignments) loop
    v_scope := v->>'scope';
    if v_scope is null or v_scope not in ('homeroom','subject') or not exists(
      select 1 from public.student_year_rosters where academic_year=p_year and grade=v->>'grade' and room=v->>'room'
      union all select 1 from public.students where academic_year=p_year and grade=v->>'grade' and room=v->>'room')
      then raise exception 'ห้องหรือประเภทงานไม่ถูกต้อง'; end if;
    if v_scope='homeroom' then
      if nullif(v->>'subject_id','') is not null or coalesce((v->>'semester')::integer,0)<>0
        then raise exception 'ครูประจำชั้นไม่ต้องระบุวิชาหรือภาค'; end if;
    else
      select * into v_subject from public.subjects where id=v->>'subject_id' and grade=v->>'grade';
      if not found or coalesce((v->>'semester')::integer,0) not in (0,1,2)
        or (v_subject.semester is not null and coalesce((v->>'semester')::integer,0)<>v_subject.semester)
        then raise exception 'วิชาหรือภาคเรียนไม่ตรงกับห้อง'; end if;
    end if;
  end loop;
  if public.pp5_teacher_scope_enabled() and p_year=public.pp5_teacher_scope_year() and jsonb_array_length(p_assignments)=0
    then raise exception 'ขณะเปิดใช้สิทธิ์ ต้องปิดบัญชีครูหรือมอบหมายงานใหม่ก่อนถอนงานทั้งหมด'; end if;
  delete from public.teacher_access_assignments where user_id=p_user and academic_year=p_year;
  insert into public.teacher_access_assignments(user_id,academic_year,scope,grade,room,subject_id,semester)
    select distinct p_user,p_year,item.value->>'scope',item.value->>'grade',item.value->>'room',
      nullif(item.value->>'subject_id',''),coalesce((item.value->>'semester')::integer,0)
    from jsonb_array_elements(p_assignments) as item(value);
  return jsonb_build_object('success',true);
end $$;

create or replace function public.pp5_enable_teacher_scope(p_confirmation text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if public.pp5_current_role() is distinct from 'admin' then raise exception 'ADMIN_REQUIRED' using errcode='42501'; end if;
  if p_confirmation is distinct from 'ENABLE_TEACHER_SCOPE' then raise exception 'กรุณายืนยันการเปิดสิทธิ์'; end if;
  perform 1 from public.teacher_scope_settings where id for update;
  if not exists(select 1 from public.academic_years where academic_year=public.pp5_teacher_scope_year() and status='active' and not is_locked)
    then raise exception 'ปีการศึกษาปัจจุบันยังไม่เปิดให้บันทึก'; end if;
  if exists(select 1 from public.user_profiles p where p.role='teacher' and p.active and not exists(
    select 1 from public.teacher_access_assignments a where a.user_id=p.id and a.active
      and a.academic_year=public.pp5_teacher_scope_year()
      and (exists(select 1 from public.student_year_rosters r where r.academic_year=a.academic_year and r.grade=a.grade and r.room=a.room)
        or exists(select 1 from public.students s where s.academic_year=a.academic_year and s.grade=a.grade and s.room=a.room))
      and (a.scope='homeroom' or exists(select 1 from public.subjects s where s.id=a.subject_id and s.grade=a.grade
        and (s.semester is null or s.semester=a.semester)))))
    then raise exception 'ยังมีบัญชีครูที่ไม่ได้รับมอบหมายงานในปีปัจจุบัน'; end if;
  update public.teacher_scope_settings set enabled=true,updated_at=now() where id;
  return jsonb_build_object('success',true,'enabled',true);
end $$;

-- Restrictive policies are ANDed with existing permissive policies. Old policies cannot bypass these.
do $$
declare t text; yr text; sub text; sem text; rd text; wr text;
begin
  foreach t in array array['students','student_year_rosters','student_details','scores','assessments',
    'attendance_daily','attendance_monthly','student_comments','student_growth','behavior_records'] loop
    yr := case when t in ('students','student_details') then 'null' else 'academic_year' end;
    sub := case when t='scores' then 'subject_id' else 'null' end;
    sem := case when t='scores' then 'semester' else 'null' end;
    rd := format('not public.pp5_teacher_scope_enabled() or public.pp5_teacher_scope_access(%L,%I,%s,%s,%s,false)',
      t,case when t='students' then 'id' else 'student_id' end,yr,sub,sem);
    wr := format('not public.pp5_teacher_scope_enabled() or public.pp5_teacher_scope_access(%L,%I,%s,%s,%s,true)',
      t,case when t='students' then 'id' else 'student_id' end,yr,sub,sem);
    execute format('drop policy if exists pp5_scoped_read on public.%I',t);
    execute format('create policy pp5_scoped_read on public.%I as restrictive for select to authenticated using (%s)',t,rd);
    execute format('drop policy if exists pp5_scoped_insert on public.%I',t);
    execute format('drop policy if exists pp5_scoped_update on public.%I',t);
    execute format('drop policy if exists pp5_scoped_delete on public.%I',t);
    if t in ('students','student_year_rosters') then
      execute format('create policy pp5_scoped_insert on public.%I as restrictive for insert to authenticated with check (not public.pp5_teacher_scope_enabled() or public.pp5_current_role()=''admin'')',t);
      execute format('create policy pp5_scoped_delete on public.%I as restrictive for delete to authenticated using (not public.pp5_teacher_scope_enabled() or public.pp5_current_role()=''admin'')',t);
    else
      execute format('create policy pp5_scoped_insert on public.%I as restrictive for insert to authenticated with check (%s)',t,wr);
      execute format('create policy pp5_scoped_delete on public.%I as restrictive for delete to authenticated using (%s)',t,wr);
    end if;
    execute format('create policy pp5_scoped_update on public.%I as restrictive for update to authenticated using (%s) with check (%s)',t,wr,wr);
  end loop;
  foreach t in array array['academic_year_transition_drafts','academic_year_transition_students','line_notifications','teachers'] loop
    execute format('drop policy if exists pp5_scoped_admin_read on public.%I',t);
    execute format('create policy pp5_scoped_admin_read on public.%I as restrictive for select to authenticated using (not public.pp5_teacher_scope_enabled() or public.pp5_current_role()=''admin'')',t);
  end loop;
end $$;

-- Changing a student's placement/status or identity key remains an administrator operation.
create or replace function public.pp5_scope_guard_student_placement()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if public.pp5_teacher_scope_enabled() and public.pp5_current_role()='teacher' and (
      (to_jsonb(new)->>'grade',to_jsonb(new)->>'room',to_jsonb(new)->>'academic_year',
       to_jsonb(new)->>'status',to_jsonb(new)->>'national_id',to_jsonb(new)->>'enrollment_status',
       to_jsonb(new)->>'id',to_jsonb(new)->>'student_id')
      is distinct from
      (to_jsonb(old)->>'grade',to_jsonb(old)->>'room',to_jsonb(old)->>'academic_year',
       to_jsonb(old)->>'status',to_jsonb(old)->>'national_id',to_jsonb(old)->>'enrollment_status',
       to_jsonb(old)->>'id',to_jsonb(old)->>'student_id'))
    then raise exception 'การย้ายห้อง เปลี่ยนปี สถานะ หรือเลขประจำตัว ต้องให้ผู้ดูแลดำเนินการ' using errcode='42501'; end if;
  return new;
end $$;
drop trigger if exists pp5_scope_guard_student_placement on public.students;
create trigger pp5_scope_guard_student_placement before update on public.students
  for each row execute function public.pp5_scope_guard_student_placement();
drop trigger if exists pp5_scope_guard_student_placement on public.student_year_rosters;
create trigger pp5_scope_guard_student_placement before update on public.student_year_rosters
  for each row execute function public.pp5_scope_guard_student_placement();

-- Private photo URLs follow homeroom scope; subject-only teachers use names, not family/health/photos.
do $$ declare cmd text; begin
  if to_regclass('storage.objects') is not null then
    drop policy if exists pp5_scoped_photo_read on storage.objects;
    create policy pp5_scoped_photo_read on storage.objects as restrictive for select to authenticated
      using (bucket_id<>'student-photos' or not public.pp5_teacher_scope_enabled()
        or public.pp5_teacher_scope_access('student_details',split_part(name,'/',1)));
    foreach cmd in array array['insert','update','delete'] loop
      execute format('drop policy if exists pp5_scoped_photo_%s on storage.objects',cmd);
      execute format('create policy pp5_scoped_photo_%s on storage.objects as restrictive for %s to authenticated %s %s',
        cmd,cmd,
        case when cmd<>'insert' then 'using (bucket_id<>''student-photos'' or not public.pp5_teacher_scope_enabled() or public.pp5_teacher_scope_access(''student_details'',split_part(name,''/'',1),null,null,null,true))' else '' end,
        case when cmd<>'delete' then 'with check (bucket_id<>''student-photos'' or not public.pp5_teacher_scope_enabled() or public.pp5_teacher_scope_access(''student_details'',split_part(name,''/'',1),null,null,null,true))' else '' end);
    end loop;
  end if;
end $$;

-- Explicit execute grants; no default PUBLIC access to these SECURITY DEFINER functions.
do $$ declare f text; begin
  foreach f in array array[
    'pp5_teacher_scope_enabled()','pp5_teacher_scope_year()',
    'pp5_teacher_scope_access(text,text,text,text,integer,boolean)',
    'pp5_teacher_scope_context()','pp5_teacher_scope_roster(text)',
    'pp5_replace_teacher_access(uuid,text,jsonb)','pp5_enable_teacher_scope(text)',
    'pp5_scope_guard_student_placement()'] loop
    execute 'revoke all on function public.'||f||' from public,anon,authenticated';
    execute 'grant execute on function public.'||f||' to authenticated,service_role';
  end loop;
end $$;
notify pgrst, 'reload schema';
-- ---- 202610120028_login_username_lookup.sql ----
-- 202610120028_login_username_lookup (owner 2026-10-12)
-- Teachers created with a real e-mail (admin-users uses that e-mail as the Auth identity) could not sign in with
-- their short username: the login page always tried "<username>@pp5smart.local". The login page now asks this
-- function for the sign-in e-mail of ONE exact username, then signs in from the user's own browser as before
-- (Supabase's per-IP sign-in limit stays per user; nothing signs in on the server).
--
-- Trade-off accepted by the owner: anyone who knows a teacher's/admin's username can learn that account's sign-in
-- e-mail. It never returns a list, never returns parent accounts, inactive accounts or ambiguous names, and never
-- reveals anything else (role, name, existence of parents). Passwords are still checked only by Supabase Auth.
-- Safe to run again. Rollback: supabase/rollbacks/202610120028_login_username_lookup_rollback.sql

create or replace function public.pp5_login_email(p_username text)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_name text := lower(btrim(coalesce(p_username, '')));
  v_count integer;
  v_email text;
begin
  if v_name = '' or length(v_name) > 160 or position('@' in v_name) > 0 then
    return null;
  end if;

  select count(*)::integer, min(u.email::text)
    into v_count, v_email
  from public.user_profiles p
  join auth.users u on u.id = p.id
  where lower(p.username) = v_name
    and p.active
    and p.role in ('admin', 'teacher')
    and u.email is not null;

  if v_count <> 1 then
    return null;
  end if;
  return lower(v_email);
end;
$$;

comment on function public.pp5_login_email(text) is
  'Sign-in e-mail for one exact active admin/teacher username (login page). Returns null otherwise. owner 2026-10-12';

revoke all on function public.pp5_login_email(text) from public;
grant execute on function public.pp5_login_email(text) to anon, authenticated;
-- ---- 202610120029_dmc_growth_month.sql ----
-- 202610120029_dmc_growth_month (generated by tools/build-dmc-growth-migration.mjs — do not edit by hand)
-- DMC import failed with: null value in column "month" of relation "student_growth" violates not-null constraint.
-- The DMC import now fills month (from the measurement date) and the next free round_no of that month; the DMC
-- rollback restores month / round_no / bmi / note / nutrition_status from its snapshot. No data is changed by this
-- file itself. Each function is replaced only if its current body is the expected old (or already new) version.
-- Rollback: supabase/rollbacks/202610120029_dmc_growth_month_rollback.sql
-- (202610120029_dmc_growth_month.sql: runs inside this file's transaction)
do $$
declare v_md5 text;
begin
  select md5(replace(p.prosrc, chr(13), '')) into v_md5 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'pp5_apply_dmc_student_import';
  if v_md5 is distinct from '8fa6d8c7d711ee220a679d17279499f4' and v_md5 is distinct from '50bf4c56073202979aa89b3247334661' then
    raise exception 'pp5_apply_dmc_student_import differs from the expected version (md5 %); stop and compare before applying', v_md5;
  end if;
  select md5(replace(p.prosrc, chr(13), '')) into v_md5 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'pp5_rollback_dmc_student_import';
  if v_md5 is distinct from '6307f31d998c47947e5ebd5033894fc8' and v_md5 is distinct from '9cff849a33e237221fd63916eca95fb0' then
    raise exception 'pp5_rollback_dmc_student_import differs from the expected version (md5 %); stop and compare before applying', v_md5;
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.pp5_apply_dmc_student_import(p_rows jsonb, p_academic_year text, p_file_name text, p_file_type text, p_source_count integer, p_skipped_count integer DEFAULT 0, p_measured_on date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_import_id uuid;
  v_incoming integer;
  v_existing integer;
  v_inserted integer;
  v_preserved_missing integer;
  v_snapshot_count integer;
  v_measured_on date := coalesce(p_measured_on, current_date);
  v_summary jsonb;
begin
  perform public.pp5_validate_dmc_student_payload(p_rows, p_academic_year);
  if lower(coalesce(p_file_type, '')) not in ('csv', 'xlsx') then
    raise exception 'ชนิดไฟล์ DMC ไม่ถูกต้อง';
  end if;
  if coalesce(p_source_count, 0) < jsonb_array_length(p_rows)
     or coalesce(p_skipped_count, 0) < 0 then
    raise exception 'จำนวนแถวของไฟล์ DMC ไม่ถูกต้อง';
  end if;

  perform pg_advisory_xact_lock(hashtext('pp5_dmc_import:' || p_academic_year));
  v_incoming := jsonb_array_length(p_rows);

  -- Lock every existing row that will be snapshotted so a concurrent edit
  -- cannot slip between the snapshot and the upsert.
  perform 1 from public.students s
  where exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = s.id)
  for update;
  perform 1 from public.student_details d
  where exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = d.student_id)
  for update;
  perform 1 from public.student_growth g
  where g.measured_on = v_measured_on
    and exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = g.student_id)
  for update;
  perform 1 from public.student_year_rosters roster
  where roster.academic_year = p_academic_year
    and exists (select 1 from jsonb_array_elements(p_rows) item where item->>'student_id' = roster.student_id)
  for update;

  select count(*)::integer into v_existing
  from public.students s
  where exists (
    select 1 from jsonb_array_elements(p_rows) item
    where item->>'student_id' = s.id
  );
  v_inserted := v_incoming - v_existing;

  select count(*)::integer into v_preserved_missing
  from public.student_year_rosters roster
  where roster.academic_year = p_academic_year
    and roster.status = 'active'
    and not exists (
      select 1 from jsonb_array_elements(p_rows) item
      where item->>'student_id' = roster.student_id
    );

  insert into public.student_import_runs (
    academic_year, file_name, file_type, source_count, valid_count,
    skipped_count, inserted_count, updated_count, preserved_missing_count,
    summary, requested_by, status, snapshot_count, measured_on, applied_at
  ) values (
    p_academic_year, left(coalesce(p_file_name, ''), 255), lower(p_file_type),
    p_source_count, v_incoming, p_skipped_count, v_inserted, v_existing,
    v_preserved_missing, jsonb_build_object('state', 'snapshot_created'),
    auth.uid(), 'applied', 0, v_measured_on, clock_timestamp()
  ) returning id into v_import_id;

  insert into public.student_import_snapshots (
    import_id, student_id, was_student_present,
    student_row, detail_row, growth_row, roster_row
  )
  select
    v_import_id,
    incoming.student_id,
    s.id is not null,
    case when s.id is null then null else to_jsonb(s) end,
    (select to_jsonb(d) from public.student_details d where d.student_id = incoming.student_id),
    (select to_jsonb(g) from public.student_growth g
      where g.student_id = incoming.student_id and g.measured_on = v_measured_on limit 1),
    (select to_jsonb(roster) from public.student_year_rosters roster
      where roster.student_id = incoming.student_id and roster.academic_year = p_academic_year)
  from jsonb_to_recordset(p_rows) as incoming(student_id text)
  left join public.students s on s.id = incoming.student_id;

  get diagnostics v_snapshot_count = row_count;
  if v_snapshot_count <> v_incoming then
    raise exception 'สร้าง snapshot ก่อนนำเข้าไม่ครบ: ต้องได้ % แต่ได้ %', v_incoming, v_snapshot_count;
  end if;

  insert into public.students (
    id, national_id, student_number, prefix, first_name, last_name,
    gender, grade, room, academic_year, status, updated_at
  )
  select
    r.student_id, nullif(r.national_id, ''), r.student_number,
    nullif(r.prefix, ''), r.first_name, r.last_name,
    r.gender, r.grade, r.room, p_academic_year, 'active', now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, national_id text, student_number integer, prefix text,
    first_name text, last_name text, gender text, grade text, room text
  )
  on conflict (id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    academic_year = excluded.academic_year,
    status = 'active',
    updated_at = now();

  insert into public.student_details (
    student_id, birth_date, religion, blood_type, ethnicity, nationality,
    address, subdistrict, district, province,
    father_name, father_last_name, father_occupation,
    mother_name, mother_last_name, mother_occupation,
    guardian_name, guardian_occupation, guardian_relation,
    disadvantage, disposal_blocked, source_data, updated_at
  )
  select
    r.student_id, nullif(r.birth_date, '')::date,
    nullif(r.religion, ''), nullif(r.blood_type, ''),
    nullif(r.ethnicity, ''), nullif(r.nationality, ''),
    nullif(r.address, ''), nullif(r.subdistrict, ''),
    nullif(r.district, ''), nullif(r.province, ''),
    nullif(r.father_name, ''), nullif(r.father_last_name, ''), nullif(r.father_occupation, ''),
    nullif(r.mother_name, ''), nullif(r.mother_last_name, ''), nullif(r.mother_occupation, ''),
    nullif(r.guardian_name, ''), nullif(r.guardian_occupation, ''), nullif(r.guardian_relation, ''),
    nullif(r.disadvantage, ''), nullif(r.disposal_blocked, ''),
    coalesce(r.source_data, '{}'::jsonb), now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, birth_date text, religion text, blood_type text,
    ethnicity text, nationality text, address text, subdistrict text,
    district text, province text, father_name text, father_last_name text,
    father_occupation text, mother_name text, mother_last_name text,
    mother_occupation text, guardian_name text, guardian_occupation text,
    guardian_relation text, disadvantage text, disposal_blocked text,
    source_data jsonb
  )
  on conflict (student_id) do update set
    birth_date = excluded.birth_date,
    religion = excluded.religion,
    blood_type = excluded.blood_type,
    ethnicity = excluded.ethnicity,
    nationality = excluded.nationality,
    address = excluded.address,
    subdistrict = excluded.subdistrict,
    district = excluded.district,
    province = excluded.province,
    father_name = excluded.father_name,
    father_last_name = excluded.father_last_name,
    father_occupation = excluded.father_occupation,
    mother_name = excluded.mother_name,
    mother_last_name = excluded.mother_last_name,
    mother_occupation = excluded.mother_occupation,
    guardian_name = excluded.guardian_name,
    guardian_occupation = excluded.guardian_occupation,
    guardian_relation = excluded.guardian_relation,
    disadvantage = excluded.disadvantage,
    disposal_blocked = excluded.disposal_blocked,
    source_data = excluded.source_data,
    updated_at = now();

  -- month / round_no are required (nutrition rounds): month of the measurement date, next free round of that month
  insert into public.student_growth (
    student_id, measured_on, academic_year, month, round_no, weight_kg, height_cm,
    recorded_by, updated_at
  )
  select
    r.student_id, v_measured_on, p_academic_year,
    extract(month from v_measured_on)::smallint,
    coalesce((select max(g.round_no) from public.student_growth g
      where g.student_id = r.student_id and g.academic_year = p_academic_year
        and g.month = extract(month from v_measured_on)::smallint), 0) + 1,
    r.weight_kg, r.height_cm, auth.uid(), now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, weight_kg numeric, height_cm numeric
  )
  where r.weight_kg is not null or r.height_cm is not null
  on conflict (student_id, measured_on) do update set
    academic_year = excluded.academic_year,
    weight_kg = excluded.weight_kg,
    height_cm = excluded.height_cm,
    recorded_by = excluded.recorded_by,
    updated_at = now();

  insert into public.student_year_rosters (
    academic_year, student_id, national_id, student_number, prefix,
    first_name, last_name, gender, grade, room, status, updated_at
  )
  select
    p_academic_year, r.student_id, nullif(r.national_id, ''), r.student_number,
    nullif(r.prefix, ''), r.first_name, r.last_name, r.gender,
    r.grade, r.room, 'active', now()
  from jsonb_to_recordset(p_rows) as r(
    student_id text, national_id text, student_number integer, prefix text,
    first_name text, last_name text, gender text, grade text, room text
  )
  on conflict (academic_year, student_id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    status = 'active',
    updated_at = now();

  v_summary := jsonb_build_object(
    'academicYear', p_academic_year,
    'sourceCount', p_source_count,
    'validCount', v_incoming,
    'skippedCount', p_skipped_count,
    'insertedCount', v_inserted,
    'updatedCount', v_existing,
    'preservedMissingCount', v_preserved_missing,
    'resultRosterCount', v_incoming + v_preserved_missing,
    'measurementDate', v_measured_on,
    'snapshotCount', v_snapshot_count,
    'rollbackAvailable', true,
    'destructiveChanges', 0
  );

  update public.student_import_runs
  set summary = v_summary,
      snapshot_count = v_snapshot_count,
      applied_at = clock_timestamp()
  where id = v_import_id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, detail)
  values (auth.uid(), 'dmc_student_import', 'student_import_run', v_import_id::text, v_summary);

  return v_summary || jsonb_build_object('importId', v_import_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.pp5_rollback_dmc_student_import(p_import_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run public.student_import_runs%rowtype;
  v_guard jsonb;
  v_summary jsonb;
  v_deleted_new_students integer := 0;
begin
  perform public.pp5_assert_admin();

  select * into v_run
  from public.student_import_runs
  where id = p_import_id
  for update;

  if v_run.id is null then
    raise exception 'ไม่พบประวัติการนำเข้า DMC ที่ระบุ';
  end if;

  -- Use the same year-scoped lock as the import RPC so an import and its
  -- rollback can never overlap.
  perform pg_advisory_xact_lock(hashtext('pp5_dmc_import:' || v_run.academic_year));

  -- Rollback is rare and admin-only. These locks make the safety check and
  -- restore one indivisible operation, so new attendance/score rows cannot
  -- appear after the guard has approved the rollback.
  lock table public.students, public.student_details, public.student_growth,
    public.student_year_rosters, public.attendance_daily, public.attendance_monthly,
    public.scores, public.assessments, public.student_comments,
    public.parent_student_links in share row exclusive mode;

  v_guard := public.pp5_dmc_student_rollback_guard(p_import_id);
  if coalesce((v_guard->>'eligible')::boolean, false) is not true then
    raise exception 'ไม่สามารถย้อนกลับอัตโนมัติ: %', coalesce(v_guard->>'reason', 'ไม่ผ่านเงื่อนไขความปลอดภัย');
  end if;

  insert into public.students (
    id, national_id, student_number, prefix, first_name, last_name,
    gender, grade, room, academic_year, status, created_at, updated_at
  )
  select
    snap.student_row->>'id', nullif(snap.student_row->>'national_id', ''),
    nullif(snap.student_row->>'student_number', '')::integer,
    snap.student_row->>'prefix', snap.student_row->>'first_name', snap.student_row->>'last_name',
    snap.student_row->>'gender', snap.student_row->>'grade', snap.student_row->>'room',
    snap.student_row->>'academic_year', snap.student_row->>'status',
    coalesce(nullif(snap.student_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.student_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.was_student_present
  on conflict (id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    academic_year = excluded.academic_year,
    status = excluded.status,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.student_details d
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = d.student_id
    and snap.detail_row is null;

  insert into public.student_details (
    student_id, birth_date, religion, blood_type, address,
    father_name, father_occupation, mother_name, mother_occupation,
    guardian_name, guardian_occupation, guardian_relation, guardian_phone,
    updated_at, ethnicity, nationality, subdistrict, district, province,
    father_last_name, mother_last_name, disadvantage, disposal_blocked, source_data
  )
  select
    snap.student_id, nullif(snap.detail_row->>'birth_date', '')::date,
    snap.detail_row->>'religion', snap.detail_row->>'blood_type', snap.detail_row->>'address',
    snap.detail_row->>'father_name', snap.detail_row->>'father_occupation',
    snap.detail_row->>'mother_name', snap.detail_row->>'mother_occupation',
    snap.detail_row->>'guardian_name', snap.detail_row->>'guardian_occupation',
    snap.detail_row->>'guardian_relation', snap.detail_row->>'guardian_phone',
    coalesce(nullif(snap.detail_row->>'updated_at', '')::timestamptz, now()),
    snap.detail_row->>'ethnicity', snap.detail_row->>'nationality',
    snap.detail_row->>'subdistrict', snap.detail_row->>'district', snap.detail_row->>'province',
    snap.detail_row->>'father_last_name', snap.detail_row->>'mother_last_name',
    snap.detail_row->>'disadvantage', snap.detail_row->>'disposal_blocked',
    coalesce(snap.detail_row->'source_data', '{}'::jsonb)
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.detail_row is not null
  on conflict (student_id) do update set
    birth_date = excluded.birth_date,
    religion = excluded.religion,
    blood_type = excluded.blood_type,
    address = excluded.address,
    father_name = excluded.father_name,
    father_occupation = excluded.father_occupation,
    mother_name = excluded.mother_name,
    mother_occupation = excluded.mother_occupation,
    guardian_name = excluded.guardian_name,
    guardian_occupation = excluded.guardian_occupation,
    guardian_relation = excluded.guardian_relation,
    guardian_phone = excluded.guardian_phone,
    updated_at = excluded.updated_at,
    ethnicity = excluded.ethnicity,
    nationality = excluded.nationality,
    subdistrict = excluded.subdistrict,
    district = excluded.district,
    province = excluded.province,
    father_last_name = excluded.father_last_name,
    mother_last_name = excluded.mother_last_name,
    disadvantage = excluded.disadvantage,
    disposal_blocked = excluded.disposal_blocked,
    source_data = excluded.source_data;

  delete from public.student_growth growth
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = growth.student_id
    and growth.measured_on = v_run.measured_on
    and snap.growth_row is null;

  insert into public.student_growth (
    id, student_id, measured_on, academic_year, month, round_no, weight_kg, height_cm,
    bmi, note, nutrition_status, recorded_by, created_at, updated_at
  )
  select
    nullif(snap.growth_row->>'id', '')::bigint,
    snap.student_id,
    nullif(snap.growth_row->>'measured_on', '')::date,
    snap.growth_row->>'academic_year',
    coalesce(nullif(snap.growth_row->>'month', '')::smallint,
      extract(month from nullif(snap.growth_row->>'measured_on', '')::date)::smallint),
    coalesce(nullif(snap.growth_row->>'round_no', '')::smallint, 1),
    nullif(snap.growth_row->>'weight_kg', '')::numeric,
    nullif(snap.growth_row->>'height_cm', '')::numeric,
    nullif(snap.growth_row->>'bmi', '')::numeric,
    nullif(snap.growth_row->>'note', ''),
    nullif(snap.growth_row->>'nutrition_status', ''),
    nullif(snap.growth_row->>'recorded_by', '')::uuid,
    coalesce(nullif(snap.growth_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.growth_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.growth_row is not null
  on conflict (student_id, measured_on) do update set
    academic_year = excluded.academic_year,
    weight_kg = excluded.weight_kg,
    height_cm = excluded.height_cm,
    recorded_by = excluded.recorded_by,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.student_year_rosters roster
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and snap.student_id = roster.student_id
    and roster.academic_year = v_run.academic_year
    and snap.roster_row is null;

  insert into public.student_year_rosters (
    academic_year, student_id, national_id, student_number, prefix,
    first_name, last_name, gender, grade, room, status, source_transition_id,
    created_at, updated_at
  )
  select
    snap.roster_row->>'academic_year', snap.student_id,
    nullif(snap.roster_row->>'national_id', ''),
    nullif(snap.roster_row->>'student_number', '')::integer,
    snap.roster_row->>'prefix', snap.roster_row->>'first_name', snap.roster_row->>'last_name',
    snap.roster_row->>'gender', snap.roster_row->>'grade', snap.roster_row->>'room',
    snap.roster_row->>'status', nullif(snap.roster_row->>'source_transition_id', '')::uuid,
    coalesce(nullif(snap.roster_row->>'created_at', '')::timestamptz, now()),
    coalesce(nullif(snap.roster_row->>'updated_at', '')::timestamptz, now())
  from public.student_import_snapshots snap
  where snap.import_id = v_run.id and snap.roster_row is not null
  on conflict (academic_year, student_id) do update set
    national_id = excluded.national_id,
    student_number = excluded.student_number,
    prefix = excluded.prefix,
    first_name = excluded.first_name,
    last_name = excluded.last_name,
    gender = excluded.gender,
    grade = excluded.grade,
    room = excluded.room,
    status = excluded.status,
    source_transition_id = excluded.source_transition_id,
    created_at = excluded.created_at,
    updated_at = excluded.updated_at;

  delete from public.students s
  using public.student_import_snapshots snap
  where snap.import_id = v_run.id
    and not snap.was_student_present
    and snap.student_id = s.id;
  get diagnostics v_deleted_new_students = row_count;

  v_summary := jsonb_build_object(
    'success', true,
    'importId', v_run.id,
    'academicYear', v_run.academic_year,
    'restoredStudentCount', v_run.updated_count,
    'removedNewStudentCount', v_deleted_new_students,
    'snapshotCount', v_run.snapshot_count,
    'message', format('ย้อนกลับการนำเข้า DMC ปี %s เรียบร้อยแล้ว', v_run.academic_year)
  );

  update public.student_import_runs
  set status = 'rolled_back',
      rolled_back_at = clock_timestamp(),
      rolled_back_by = auth.uid(),
      rollback_summary = v_summary
  where id = v_run.id;

  insert into public.audit_logs (actor_id, action, entity_type, entity_id, detail)
  values (auth.uid(), 'dmc_student_import_rolled_back', 'student_import_run', v_run.id::text, v_summary);

  return v_summary;
end;
$function$;

notify pgrst, 'reload schema';
-- ---- 202610140030_clubs.sql ----
-- 202610140030_clubs (owner 2026-10-14: "ต่อไปอยากได้ระบบลงทะเบียนชุมนุม")
-- Owner decisions: teachers AND students can register · every grade may join every club · one club per student per
-- semester (ภาค 1 / ภาค 2 separate) · the club name shows on the activity assessment and ปพ.5 / ปพ.6 automatically
-- (js/gas-bridge.js loadActivityAssessment falls back to club_members when no club name was typed).
--
--   clubs          one row per club per academic year + semester (admins create / edit / delete)
--   club_members   one row per student per academic year + semester; written ONLY through the functions below
--   school_settings.settings_json.club_registration = {"opens_at": "...", "closes_at": "..."}  (students' window)
--
-- Students have no account: pp5_club_student_view / pp5_club_student_join check the student id + birth date
-- (student_details.birth_date) and, for joining, that "now" is inside the window. Capacity is checked under a row
-- lock on the club, so two students cannot take the last seat. Teachers use pp5_club_set_member (any time).
-- Safe to run again. Rollback: supabase/rollbacks/202610140030_clubs_rollback.sql
-- (202610140030_clubs.sql: runs inside this file's transaction)
create table if not exists public.clubs (
  id uuid primary key default gen_random_uuid(),
  academic_year text not null,
  semester integer not null check (semester in (1, 2)),
  name text not null check (length(btrim(name)) between 1 and 120),
  advisor text check (advisor is null or length(advisor) <= 160),
  capacity integer not null default 30 check (capacity between 1 and 500),
  description text check (description is null or length(description) <= 500),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (academic_year, semester, name)
);

create table if not exists public.club_members (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references public.clubs(id) on delete cascade,
  student_id text not null references public.students(id) on delete cascade,
  academic_year text not null,
  semester integer not null check (semester in (1, 2)),
  registered_by text not null default 'teacher' check (registered_by in ('teacher', 'student')),
  created_at timestamptz not null default now(),
  unique (student_id, academic_year, semester)
);
create index if not exists club_members_club_idx on public.club_members (club_id);

alter table public.clubs enable row level security;
alter table public.club_members enable row level security;

drop policy if exists clubs_staff_read on public.clubs;
create policy clubs_staff_read on public.clubs for select to authenticated
  using (public.pp5_current_role() in ('admin', 'teacher'));
drop policy if exists clubs_admin_write on public.clubs;
create policy clubs_admin_write on public.clubs for all to authenticated
  using (public.pp5_current_role() = 'admin') with check (public.pp5_current_role() = 'admin');
drop policy if exists club_members_staff_read on public.club_members;
create policy club_members_staff_read on public.club_members for select to authenticated
  using (public.pp5_current_role() in ('admin', 'teacher'));

revoke all on table public.clubs, public.club_members from anon;
grant select, insert, update, delete on table public.clubs to authenticated;
grant select on table public.club_members to authenticated;
grant all on table public.clubs, public.club_members to service_role;

-- current academic year / semester of the school
create or replace function public.pp5_club_term()
returns table (academic_year text, semester integer)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(nullif(btrim(s.academic_year::text), ''), '0'), coalesce(s.semester, 1)
  from public.school_settings s
  order by s.id
  limit 1;
$$;

-- students' registration window (public: the login page shows the link only while it is open)
create or replace function public.pp5_club_registration_window()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_window jsonb;
  v_opens timestamptz;
  v_closes timestamptz;
  v_year text;
  v_semester integer;
begin
  select s.settings_json -> 'club_registration' into v_window from public.school_settings s order by s.id limit 1;
  select t.academic_year, t.semester into v_year, v_semester from public.pp5_club_term() t;
  begin
    v_opens := nullif(v_window ->> 'opens_at', '')::timestamptz;
    v_closes := nullif(v_window ->> 'closes_at', '')::timestamptz;
  exception when others then
    v_opens := null; v_closes := null;
  end;
  return jsonb_build_object(
    'open', v_opens is not null and v_closes is not null and now() >= v_opens and now() < v_closes,
    'opens_at', v_opens, 'closes_at', v_closes, 'academic_year', v_year, 'semester', v_semester);
end;
$$;

-- put a student in a club (or remove with p_club_id null) for the current term; capacity under a row lock
create or replace function public.pp5_club_place_member(p_student_id text, p_club_id uuid, p_by text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text;
  v_semester integer;
  v_club public.clubs%rowtype;
  v_taken integer;
begin
  select t.academic_year, t.semester into v_year, v_semester from public.pp5_club_term() t;
  if not exists (select 1 from public.students s where s.id = p_student_id) then
    raise exception using errcode = 'P0001', message = 'ไม่พบนักเรียน';
  end if;
  if p_club_id is null then
    delete from public.club_members m where m.student_id = p_student_id and m.academic_year = v_year and m.semester = v_semester;
    return jsonb_build_object('success', true, 'club_id', null);
  end if;
  select * into v_club from public.clubs c where c.id = p_club_id for update;
  if not found or not v_club.active or v_club.academic_year <> v_year or v_club.semester <> v_semester then
    raise exception using errcode = 'P0001', message = 'ไม่พบชุมนุมนี้ในภาคเรียนปัจจุบัน';
  end if;
  select count(*)::integer into v_taken from public.club_members m
    where m.club_id = p_club_id and m.student_id <> p_student_id;
  if v_taken >= v_club.capacity then
    raise exception using errcode = 'P0001', message = 'ชุมนุม ' || v_club.name || ' เต็มแล้ว';
  end if;
  insert into public.club_members (club_id, student_id, academic_year, semester, registered_by)
    values (p_club_id, p_student_id, v_year, v_semester, p_by)
    on conflict (student_id, academic_year, semester)
    do update set club_id = excluded.club_id, registered_by = excluded.registered_by, created_at = now();
  return jsonb_build_object('success', true, 'club_id', p_club_id, 'count', v_taken + 1);
end;
$$;
revoke all on function public.pp5_club_place_member(text, uuid, text) from public, anon, authenticated;

-- teachers / admins: any student, any time
create or replace function public.pp5_club_set_member(p_student_id text, p_club_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  return public.pp5_club_place_member(p_student_id, p_club_id, 'teacher');
end;
$$;

-- students: same answer for a wrong id and a wrong birth date (no guessing which one was wrong)
create or replace function public.pp5_club_check_student(p_student_id text, p_birth_date date)
returns public.students
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_student public.students%rowtype;
  v_birth date;
begin
  select s.* into v_student from public.students s
    where s.id = btrim(coalesce(p_student_id, '')) and coalesce(s.status, 'active') = 'active';
  select d.birth_date into v_birth from public.student_details d where d.student_id = v_student.id;
  if v_student.id is null or p_birth_date is null or v_birth is distinct from p_birth_date then
    if v_student.id is not null and v_birth is null then
      raise exception using errcode = 'P0001', message = 'ยังไม่มีวันเกิดของนักเรียนในระบบ กรุณาให้ครูลงทะเบียนชุมนุมให้';
    end if;
    raise exception using errcode = 'P0001', message = 'เลขประจำตัวหรือวันเกิดไม่ถูกต้อง';
  end if;
  return v_student;
end;
$$;
revoke all on function public.pp5_club_check_student(text, date) from public, anon, authenticated;

create or replace function public.pp5_club_student_view(p_student_id text, p_birth_date date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_student public.students%rowtype;
  v_year text;
  v_semester integer;
  v_current uuid;
begin
  v_student := public.pp5_club_check_student(p_student_id, p_birth_date);
  select t.academic_year, t.semester into v_year, v_semester from public.pp5_club_term() t;
  select m.club_id into v_current from public.club_members m
    where m.student_id = v_student.id and m.academic_year = v_year and m.semester = v_semester;
  return jsonb_build_object(
    'student', jsonb_build_object('name', concat_ws(' ', nullif(v_student.prefix, ''), v_student.first_name, v_student.last_name),
      'grade', v_student.grade, 'room', v_student.room),
    'window', public.pp5_club_registration_window(),
    'current_club_id', v_current,
    'clubs', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'advisor', c.advisor, 'description', c.description,
        'capacity', c.capacity, 'count', (select count(*) from public.club_members m where m.club_id = c.id)) order by c.name)
      from public.clubs c where c.active and c.academic_year = v_year and c.semester = v_semester), '[]'::jsonb));
end;
$$;

create or replace function public.pp5_club_student_join(p_student_id text, p_birth_date date, p_club_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_student public.students%rowtype;
begin
  v_student := public.pp5_club_check_student(p_student_id, p_birth_date);
  if not coalesce((public.pp5_club_registration_window() ->> 'open')::boolean, false) then
    raise exception using errcode = 'P0001', message = 'ขณะนี้ไม่อยู่ในช่วงเวลาลงทะเบียนชุมนุม';
  end if;
  if p_club_id is null then
    raise exception using errcode = 'P0001', message = 'กรุณาเลือกชุมนุม';
  end if;
  return public.pp5_club_place_member(v_student.id, p_club_id, 'student');
end;
$$;

revoke all on function public.pp5_club_term() from public;
revoke all on function public.pp5_club_set_member(text, uuid) from public, anon;
revoke all on function public.pp5_club_student_view(text, date) from public;
revoke all on function public.pp5_club_student_join(text, date, uuid) from public;
revoke all on function public.pp5_club_registration_window() from public;
grant execute on function public.pp5_club_term() to authenticated, service_role;
grant execute on function public.pp5_club_set_member(text, uuid) to authenticated, service_role;
grant execute on function public.pp5_club_registration_window() to anon, authenticated, service_role;
grant execute on function public.pp5_club_student_view(text, date) to anon, authenticated, service_role;
grant execute on function public.pp5_club_student_join(text, date, uuid) to anon, authenticated, service_role;
-- ---- 202610140031_subject_attendance.sql ----
-- 202610140031_subject_attendance (owner 2026-10-14: "ในวิชานั้นๆมันต้องมีเช็คชื่อรายชั่วโมง จะทำอย่างไรดี")
-- Owner decisions: the SUBJECT TEACHER checks, and (owner 2026-10-14, for schools that mix class teaching and subject
-- teaching) the HOMEROOM TEACHER checks every subject of their own room; admins check anything · the teacher picks how many hours the
-- subject was taught that day (no timetable) · the page pre-fills each student from the daily attendance · the
-- attendance percentage = hours present ÷ hours actually taught and recorded.
--
--   subject_attendance   one row per student per subject per day: hours taught that day (1-8) + มา/ลา/ขาด
--                        written ONLY through pp5_save_subject_attendance (no direct table writes)
--
-- Who may check: admins always. Teachers: while teacher scope (SQL 027) is OFF, every teacher (same as scores);
-- while it is ON, the room's homeroom teacher (any subject of that room) or a teacher with a "subject" assignment for
-- that subject + room this year. Reading follows the same rule. One row per student / subject / day, so two people
-- saving the same day replace each other's record instead of adding a second one.
-- js/subject-attendance.js is the check page; js/gas-bridge.js computePp5SubjectSheets uses these rows for the
-- ปก ปพ.5 แบบรายวิชา (falls back to the daily attendance when a subject has no hourly records).
-- Safe to run again. Rollback: supabase/rollbacks/202610140031_subject_attendance_rollback.sql
-- (202610140031_subject_attendance.sql: runs inside this file's transaction)
create table if not exists public.subject_attendance (
  id bigint generated by default as identity primary key,
  academic_year text not null,
  subject_id text not null references public.subjects(id) on delete cascade,
  student_id text not null references public.students(id) on delete cascade,
  attendance_date date not null,
  hours smallint not null check (hours between 1 and 8),
  status text not null check (status in ('present', 'leave', 'absent')),
  recorded_by uuid default auth.uid(),
  updated_at timestamptz not null default now(),
  unique (subject_id, student_id, attendance_date)
);
create index if not exists subject_attendance_subject_idx
  on public.subject_attendance (subject_id, academic_year, attendance_date);
create index if not exists subject_attendance_student_idx on public.subject_attendance (student_id);

alter table public.subject_attendance enable row level security;

-- may the current user see / write this student's attendance in this subject?
create or replace function public.pp5_subject_attendance_can(p_student text, p_subject text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text := public.pp5_current_role();
  v_year text;
begin
  if v_role = 'admin' then return true; end if;
  if v_role is distinct from 'teacher' then return false; end if;
  if not public.pp5_teacher_scope_enabled() then return true; end if;
  v_year := public.pp5_teacher_scope_year();
  return exists (
    select 1 from public.teacher_access_assignments a
    where a.user_id = auth.uid() and a.active and a.academic_year = v_year
      and (
        exists (select 1 from public.student_year_rosters r where r.student_id = p_student
          and r.academic_year = a.academic_year and r.grade = a.grade and r.room = a.room)
        or (not exists (select 1 from public.student_year_rosters r where r.student_id = p_student and r.academic_year = a.academic_year)
          and exists (select 1 from public.students s where s.id = p_student and s.grade = a.grade and s.room = a.room))
      )
      and ((a.scope = 'subject' and a.subject_id = p_subject) or a.scope = 'homeroom')
  );
end;
$$;

drop policy if exists subject_attendance_read on public.subject_attendance;
create policy subject_attendance_read on public.subject_attendance for select to authenticated
  using (public.pp5_subject_attendance_can(student_id, subject_id, false));

revoke all on table public.subject_attendance from anon;
grant select on table public.subject_attendance to authenticated;
grant all on table public.subject_attendance to service_role;

-- save one day of one subject for a list of students: p_rows = [{"student_id": "...", "status": "present"|"leave"|"absent"}]
-- p_hours = hours taught that day (1-8); p_hours = 0 or a row with no status clears that student's record for the day
create or replace function public.pp5_save_subject_attendance(p_subject_id text, p_date date, p_hours integer, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_subject public.subjects%rowtype;
  v_year text;
  v_first date;
  v_last date;
  v_row jsonb;
  v_student text;
  v_status text;
  v_saved integer := 0;
  v_cleared integer := 0;
begin
  if coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  select * into v_subject from public.subjects where id = p_subject_id;
  if v_subject.id is null then
    raise exception using errcode = 'P0001', message = 'ไม่พบรายวิชานี้';
  end if;
  if p_hours is null or p_hours < 0 or p_hours > 8 then
    raise exception using errcode = 'P0001', message = 'จำนวนชั่วโมงต้องอยู่ระหว่าง 1 ถึง 8';
  end if;
  if p_date is null or p_date > (now() at time zone 'Asia/Bangkok')::date then
    raise exception using errcode = 'P0001', message = 'วันที่เช็คชื่อต้องไม่เกินวันนี้';
  end if;
  select nullif(btrim(s.academic_year::text), '') into v_year from public.school_settings s order by s.id limit 1;
  if v_year is null or v_year !~ '^[0-9]{4}$' then
    raise exception using errcode = 'P0001', message = 'ยังไม่ได้ตั้งปีการศึกษาในหน้าตั้งค่าระบบ';
  end if;
  v_first := make_date(v_year::integer - 543, 5, 1);
  v_last := make_date(v_year::integer - 542, 3, 31);
  if p_date < v_first or p_date > v_last then
    raise exception using errcode = 'P0001', message = 'วันที่ไม่อยู่ในปีการศึกษา ' || v_year;
  end if;
  if exists (select 1 from public.academic_years y where y.academic_year = v_year and y.is_locked) then
    raise exception using errcode = '42501', message = 'ปีการศึกษา ' || v_year || ' ถูกล็อกแล้ว แก้ไขไม่ได้';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 300 then
    raise exception using errcode = 'P0001', message = 'รายชื่อนักเรียนไม่ถูกต้อง';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_student := btrim(coalesce(v_row->>'student_id', ''));
    v_status := nullif(btrim(coalesce(v_row->>'status', '')), '');
    if not exists (
      select 1 from public.students s where s.id = v_student and (
        exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = v_year and r.grade = v_subject.grade)
        or (not exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = v_year)
          and s.grade = v_subject.grade))
    ) then
      raise exception using errcode = 'P0001', message = 'นักเรียน ' || v_student || ' ไม่ได้อยู่ชั้นของวิชานี้';
    end if;
    if not public.pp5_subject_attendance_can(v_student, p_subject_id, true) then
      raise exception using errcode = '42501', message = 'ไม่มีสิทธิ์เช็คชื่อวิชานี้ของนักเรียน ' || v_student;
    end if;
    if p_hours = 0 or v_status is null then
      delete from public.subject_attendance
        where subject_id = p_subject_id and student_id = v_student and attendance_date = p_date;
      v_cleared := v_cleared + 1;
      continue;
    end if;
    if v_status not in ('present', 'leave', 'absent') then
      raise exception using errcode = 'P0001', message = 'สถานะต้องเป็น มา ลา หรือ ขาด';
    end if;
    insert into public.subject_attendance (academic_year, subject_id, student_id, attendance_date, hours, status, recorded_by, updated_at)
      values (v_year, p_subject_id, v_student, p_date, p_hours, v_status, auth.uid(), now())
      on conflict (subject_id, student_id, attendance_date) do update
        set academic_year = excluded.academic_year, hours = excluded.hours, status = excluded.status,
            recorded_by = excluded.recorded_by, updated_at = now();
    v_saved := v_saved + 1;
  end loop;
  return jsonb_build_object('saved', v_saved, 'cleared', v_cleared, 'academic_year', v_year);
end;
$$;

revoke all on function public.pp5_subject_attendance_can(text, text, boolean) from public, anon;
revoke all on function public.pp5_save_subject_attendance(text, date, integer, jsonb) from public, anon;
grant execute on function public.pp5_subject_attendance_can(text, text, boolean) to authenticated, service_role;
grant execute on function public.pp5_save_subject_attendance(text, date, integer, jsonb) to authenticated, service_role;
-- ---- 202610150032_subject_periods.sql ----
-- 202610150032_subject_periods (owner 2026-10-15: "รายวิชา ภาษาไทย คณิต จะ 5 ชั่วโมง/สัปดาห์ วิชาอื่นๆส่วนมากจะ 1 ชม./สัปดาห์
-- และเป็นเรื่องสำคัญในการเช็คชื่อแต่ละชั่วโมงของครูประจำวิชา")
-- Owner decisions: check PER PERIOD (a double lesson = period 1 + period 2, each with its own มา/ลา/ขาด) · a simple
-- timetable that the TEACHER sets (which weekdays, how many periods) · warn about < 80% attendance (มส.) to the subject
-- teacher, the homeroom teacher and parents via LINE (warnings are computed by the web/Edge Function, not here).
--
--   subject_attendance.period   1-8; one row per student / subject / day / PERIOD. Every new row has hours = 1.
--                               Rows saved before this migration keep period 1 and their hours (1-8), so
--                               "hours present = sum(hours) where present" stays correct for old and new rows.
--   pp5_save_subject_period     saves ONE period of one day (new page). Clearing removes only that period.
--   pp5_save_subject_attendance (031) still works for a page that has not reloaded yet: it writes period 1 with
--                               the given hours and removes the other periods of that day (= its old meaning).
--   subject_schedules           weekly timetable per subject + room + semester: weekday 1 (Mon) .. 7 (Sun) -> periods 1-4.
--                               Written ONLY through pp5_save_subject_schedule; readable by staff.
--
-- Who may write: the same rule as 031 (admin; teacher scope OFF = every teacher; ON = the subject's teacher for that
-- room or the room's homeroom teacher). Safe to run again.
-- Rollback: supabase/rollbacks/202610150032_subject_periods_rollback.sql
-- (202610150032_subject_periods.sql: runs inside this file's transaction)
-- ---- 1. period number
alter table public.subject_attendance add column if not exists period smallint not null default 1;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'subject_attendance_period_check') then
    alter table public.subject_attendance add constraint subject_attendance_period_check check (period between 1 and 8);
  end if;
end $$;

-- one row per student / subject / day  ->  per student / subject / day / period
do $$
declare c text;
begin
  for c in
    select con.conname from pg_constraint con
    where con.conrelid = 'public.subject_attendance'::regclass and con.contype = 'u'
      and (select array_agg(att.attname::text order by att.attname)
           from unnest(con.conkey) k join pg_attribute att on att.attrelid = con.conrelid and att.attnum = k)
          = array['attendance_date', 'student_id', 'subject_id']
  loop
    execute format('alter table public.subject_attendance drop constraint %I', c);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'subject_attendance_period_key') then
    alter table public.subject_attendance add constraint subject_attendance_period_key
      unique (subject_id, student_id, attendance_date, period);
  end if;
end $$;

-- ---- 2. shared checks (role, subject, date inside the academic year, year not locked) -> the academic year
create or replace function public.pp5_subject_attendance_year(p_subject_id text, p_date date)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text;
begin
  if coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  if not exists (select 1 from public.subjects where id = p_subject_id) then
    raise exception using errcode = 'P0001', message = 'ไม่พบรายวิชานี้';
  end if;
  if p_date is null or p_date > (now() at time zone 'Asia/Bangkok')::date then
    raise exception using errcode = 'P0001', message = 'วันที่เช็คชื่อต้องไม่เกินวันนี้';
  end if;
  select nullif(btrim(s.academic_year::text), '') into v_year from public.school_settings s order by s.id limit 1;
  if v_year is null or v_year !~ '^[0-9]{4}$' then
    raise exception using errcode = 'P0001', message = 'ยังไม่ได้ตั้งปีการศึกษาในหน้าตั้งค่าระบบ';
  end if;
  if p_date < make_date(v_year::integer - 543, 5, 1) or p_date > make_date(v_year::integer - 542, 3, 31) then
    raise exception using errcode = 'P0001', message = 'วันที่ไม่อยู่ในปีการศึกษา ' || v_year;
  end if;
  if exists (select 1 from public.academic_years y where y.academic_year = v_year and y.is_locked) then
    raise exception using errcode = '42501', message = 'ปีการศึกษา ' || v_year || ' ถูกล็อกแล้ว แก้ไขไม่ได้';
  end if;
  return v_year;
end;
$$;

-- the student is in the subject's grade this year and the caller may check them
create or replace function public.pp5_subject_attendance_student(p_student text, p_subject_id text, p_year text)
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_grade text := (select grade from public.subjects where id = p_subject_id);
begin
  if not exists (
    select 1 from public.students s where s.id = p_student and (
      exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = p_year and r.grade = v_grade)
      or (not exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = p_year)
        and s.grade = v_grade))
  ) then
    raise exception using errcode = 'P0001', message = 'นักเรียน ' || p_student || ' ไม่ได้อยู่ชั้นของวิชานี้';
  end if;
  if not public.pp5_subject_attendance_can(p_student, p_subject_id, true) then
    raise exception using errcode = '42501', message = 'ไม่มีสิทธิ์เช็คชื่อวิชานี้ของนักเรียน ' || p_student;
  end if;
end;
$$;

-- ---- 3. save ONE period: p_rows = [{"student_id": "...", "status": "present"|"leave"|"absent"}]; no status = clear that period
create or replace function public.pp5_save_subject_period(p_subject_id text, p_date date, p_period integer, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text := public.pp5_subject_attendance_year(p_subject_id, p_date);
  v_row jsonb;
  v_student text;
  v_status text;
  v_saved integer := 0;
  v_cleared integer := 0;
begin
  if p_period is null or p_period < 1 or p_period > 8 then
    raise exception using errcode = 'P0001', message = 'คาบที่ต้องอยู่ระหว่าง 1 ถึง 8';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 300 then
    raise exception using errcode = 'P0001', message = 'รายชื่อนักเรียนไม่ถูกต้อง';
  end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_student := btrim(coalesce(v_row->>'student_id', ''));
    v_status := nullif(btrim(coalesce(v_row->>'status', '')), '');
    perform public.pp5_subject_attendance_student(v_student, p_subject_id, v_year);
    if v_status is null then
      delete from public.subject_attendance
        where subject_id = p_subject_id and student_id = v_student and attendance_date = p_date and period = p_period;
      v_cleared := v_cleared + 1;
      continue;
    end if;
    if v_status not in ('present', 'leave', 'absent') then
      raise exception using errcode = 'P0001', message = 'สถานะต้องเป็น มา ลา หรือ ขาด';
    end if;
    insert into public.subject_attendance (academic_year, subject_id, student_id, attendance_date, period, hours, status, recorded_by, updated_at)
      values (v_year, p_subject_id, v_student, p_date, p_period, 1, v_status, auth.uid(), now())
      on conflict (subject_id, student_id, attendance_date, period) do update
        set academic_year = excluded.academic_year, hours = 1, status = excluded.status,
            recorded_by = excluded.recorded_by, updated_at = now();
    v_saved := v_saved + 1;
  end loop;
  return jsonb_build_object('saved', v_saved, 'cleared', v_cleared, 'academic_year', v_year, 'period', p_period);
end;
$$;

-- ---- 4. the 031 day-level save, kept for pages that have not reloaded: period 1 = the whole day (old meaning)
create or replace function public.pp5_save_subject_attendance(p_subject_id text, p_date date, p_hours integer, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text := public.pp5_subject_attendance_year(p_subject_id, p_date);
  v_row jsonb;
  v_student text;
  v_status text;
  v_saved integer := 0;
  v_cleared integer := 0;
begin
  if p_hours is null or p_hours < 0 or p_hours > 8 then
    raise exception using errcode = 'P0001', message = 'จำนวนชั่วโมงต้องอยู่ระหว่าง 1 ถึง 8';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 300 then
    raise exception using errcode = 'P0001', message = 'รายชื่อนักเรียนไม่ถูกต้อง';
  end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_student := btrim(coalesce(v_row->>'student_id', ''));
    v_status := nullif(btrim(coalesce(v_row->>'status', '')), '');
    perform public.pp5_subject_attendance_student(v_student, p_subject_id, v_year);
    delete from public.subject_attendance
      where subject_id = p_subject_id and student_id = v_student and attendance_date = p_date
        and (p_hours = 0 or v_status is null or period > 1);
    if p_hours = 0 or v_status is null then
      v_cleared := v_cleared + 1;
      continue;
    end if;
    if v_status not in ('present', 'leave', 'absent') then
      raise exception using errcode = 'P0001', message = 'สถานะต้องเป็น มา ลา หรือ ขาด';
    end if;
    insert into public.subject_attendance (academic_year, subject_id, student_id, attendance_date, period, hours, status, recorded_by, updated_at)
      values (v_year, p_subject_id, v_student, p_date, 1, p_hours, v_status, auth.uid(), now())
      on conflict (subject_id, student_id, attendance_date, period) do update
        set academic_year = excluded.academic_year, hours = excluded.hours, status = excluded.status,
            recorded_by = excluded.recorded_by, updated_at = now();
    v_saved := v_saved + 1;
  end loop;
  return jsonb_build_object('saved', v_saved, 'cleared', v_cleared, 'academic_year', v_year);
end;
$$;

-- ---- 5. weekly timetable
create table if not exists public.subject_schedules (
  id bigint generated by default as identity primary key,
  academic_year text not null check (academic_year ~ '^[0-9]{4}$'),
  semester smallint not null check (semester in (1, 2)),
  subject_id text not null references public.subjects(id) on delete cascade,
  grade text not null,
  room text not null check (length(btrim(room)) > 0),
  weekday smallint not null check (weekday between 1 and 7),
  periods smallint not null check (periods between 1 and 4),
  updated_by uuid default auth.uid(),
  updated_at timestamptz not null default now(),
  unique (academic_year, semester, subject_id, grade, room, weekday)
);
create index if not exists subject_schedules_room_idx on public.subject_schedules (academic_year, grade, room);
alter table public.subject_schedules enable row level security;
drop policy if exists subject_schedules_read on public.subject_schedules;
create policy subject_schedules_read on public.subject_schedules for select to authenticated
  using (public.pp5_current_role() in ('admin', 'teacher'));
revoke all on table public.subject_schedules from anon;
grant select on table public.subject_schedules to authenticated;
grant all on table public.subject_schedules to service_role;

-- may the caller set the timetable of this subject in this room? (same rule as checking attendance)
create or replace function public.pp5_subject_schedule_can(p_subject_id text, p_grade text, p_room text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text := public.pp5_current_role();
begin
  if v_role = 'admin' then return true; end if;
  if v_role is distinct from 'teacher' then return false; end if;
  if not public.pp5_teacher_scope_enabled() then return true; end if;
  return exists (
    select 1 from public.teacher_access_assignments a
    where a.user_id = auth.uid() and a.active and a.academic_year = public.pp5_teacher_scope_year()
      and a.grade = p_grade and a.room = p_room
      and (a.scope = 'homeroom' or (a.scope = 'subject' and a.subject_id = p_subject_id))
  );
end;
$$;

-- replace the whole week of one subject + room + semester: p_days = [{"weekday": 1-7, "periods": 1-4}], [] = no timetable
create or replace function public.pp5_save_subject_schedule(p_subject_id text, p_grade text, p_room text, p_semester integer, p_days jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text;
  v_day jsonb;
  v_weekday integer;
  v_periods integer;
  v_seen integer[] := '{}';
begin
  if coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  if not exists (select 1 from public.subjects where id = p_subject_id and grade = p_grade) then
    raise exception using errcode = 'P0001', message = 'วิชานี้ไม่ใช่ของชั้น ' || coalesce(p_grade, '');
  end if;
  if p_semester is null or p_semester not in (1, 2) then
    raise exception using errcode = 'P0001', message = 'ภาคเรียนต้องเป็น 1 หรือ 2';
  end if;
  select nullif(btrim(s.academic_year::text), '') into v_year from public.school_settings s order by s.id limit 1;
  if v_year is null or v_year !~ '^[0-9]{4}$' then
    raise exception using errcode = 'P0001', message = 'ยังไม่ได้ตั้งปีการศึกษาในหน้าตั้งค่าระบบ';
  end if;
  if exists (select 1 from public.academic_years y where y.academic_year = v_year and y.is_locked) then
    raise exception using errcode = '42501', message = 'ปีการศึกษา ' || v_year || ' ถูกล็อกแล้ว แก้ไขไม่ได้';
  end if;
  if not exists (select 1 from public.student_year_rosters where academic_year = v_year and grade = p_grade and room = p_room
      union all select 1 from public.students where grade = p_grade and room = p_room) then
    raise exception using errcode = 'P0001', message = 'ไม่พบห้อง ' || coalesce(p_grade, '') || '/' || coalesce(p_room, '');
  end if;
  if not public.pp5_subject_schedule_can(p_subject_id, p_grade, p_room) then
    raise exception using errcode = '42501', message = 'ไม่มีสิทธิ์ตั้งตารางสอนวิชานี้ของห้องนี้';
  end if;
  if p_days is null or jsonb_typeof(p_days) <> 'array' or jsonb_array_length(p_days) > 7 then
    raise exception using errcode = 'P0001', message = 'ตารางสอนไม่ถูกต้อง';
  end if;
  for v_day in select value from jsonb_array_elements(p_days) loop
    v_weekday := (v_day->>'weekday')::integer;
    v_periods := (v_day->>'periods')::integer;
    if v_weekday is null or v_weekday < 1 or v_weekday > 7 or v_periods is null or v_periods < 1 or v_periods > 4
        or v_weekday = any (v_seen) then
      raise exception using errcode = 'P0001', message = 'วันสอนต้องไม่ซ้ำ และสอนวันละ 1-4 คาบ';
    end if;
    v_seen := v_seen || v_weekday;
  end loop;
  delete from public.subject_schedules
    where academic_year = v_year and semester = p_semester and subject_id = p_subject_id and grade = p_grade and room = p_room;
  insert into public.subject_schedules (academic_year, semester, subject_id, grade, room, weekday, periods, updated_by, updated_at)
    select v_year, p_semester, p_subject_id, p_grade, p_room, (d->>'weekday')::smallint, (d->>'periods')::smallint, auth.uid(), now()
    from jsonb_array_elements(p_days) d;
  return jsonb_build_object('saved', jsonb_array_length(p_days), 'academic_year', v_year,
    'periods_per_week', coalesce((select sum((d->>'periods')::integer) from jsonb_array_elements(p_days) d), 0));
end;
$$;

revoke all on function public.pp5_subject_attendance_year(text, date) from public, anon;
revoke all on function public.pp5_subject_attendance_student(text, text, text) from public, anon;
revoke all on function public.pp5_save_subject_period(text, date, integer, jsonb) from public, anon;
revoke all on function public.pp5_save_subject_attendance(text, date, integer, jsonb) from public, anon;
revoke all on function public.pp5_subject_schedule_can(text, text, text) from public, anon;
revoke all on function public.pp5_save_subject_schedule(text, text, text, integer, jsonb) from public, anon;
grant execute on function public.pp5_subject_attendance_year(text, date) to authenticated, service_role;
grant execute on function public.pp5_subject_attendance_student(text, text, text) to authenticated, service_role;
grant execute on function public.pp5_save_subject_period(text, date, integer, jsonb) to authenticated, service_role;
grant execute on function public.pp5_save_subject_attendance(text, date, integer, jsonb) to authenticated, service_role;
grant execute on function public.pp5_subject_schedule_can(text, text, text) to authenticated, service_role;
grant execute on function public.pp5_save_subject_schedule(text, text, text, integer, jsonb) to authenticated, service_role;
-- ---- 202610150033_subject_semester_jobs.sql ----
-- 202610150033_subject_semester_jobs (owner 2026-10-15: ยกวิชาให้ครูรายวิชาเฉพาะภาคเรียนที่ 2)
-- Owner decisions: a subject job may be for the whole year, semester 1 or semester 2 (teacher-access page) · the homeroom
-- teacher keeps every subject of the room (sees everything, may still edit) but is WARNED when the subject has a subject
-- teacher · semesters split like the ปพ.5 subject sheets: พ.ค.–ต.ค. = 1, พ.ย.–เม.ย. = 2.
--
--   pp5_subject_room_teachers(grade, room)   names of the subject teachers of a room (this year) for the warning.
--                                            Teachers may read only each other's ASSIGNMENTS through this function;
--                                            a teacher sees a room only if they have a job in it (scope ON).
--   pp5_semester_of(date)                    1 for May–October, 2 otherwise.
--   pp5_subject_attendance_can_on(…, date)   like pp5_subject_attendance_can(…, true) but a semester-1/2 subject job
--                                            only counts on dates of that semester (homeroom / whole-year jobs: always).
--   pp5_subject_schedule_can(…, semester)    the timetable of a semester only for a job of that semester (or whole year).
--   pp5_save_subject_period / pp5_save_subject_attendance / pp5_save_subject_schedule: same as 032, calling the
--                                            semester-aware checks. Scores already checked the job semester (027).
-- Reading is unchanged (a semester-2 teacher may still read semester-1 attendance). Safe to run again.
-- Rollback: supabase/rollbacks/202610150033_subject_semester_jobs_rollback.sql
-- (202610150033_subject_semester_jobs.sql: runs inside this file's transaction)
create or replace function public.pp5_semester_of(p_date date)
returns integer
language sql
immutable
as $$
  select case when extract(month from p_date) between 5 and 10 then 1 else 2 end
$$;

create or replace function public.pp5_subject_room_teachers(p_grade text, p_room text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text := public.pp5_current_role();
  v_year text := public.pp5_teacher_scope_year();
begin
  if coalesce(v_role, '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  if v_role = 'teacher' and public.pp5_teacher_scope_enabled() and not exists (
    select 1 from public.teacher_access_assignments a
    where a.user_id = auth.uid() and a.active and a.academic_year = v_year and a.grade = p_grade and a.room = p_room
  ) then
    return '[]'::jsonb;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('subject_id', a.subject_id, 'semester', a.semester, 'user_id', a.user_id,
      'teacher_name', coalesce(nullif(btrim(p.display_name), ''), p.username)) order by a.subject_id, a.semester, p.username)
    from public.teacher_access_assignments a
    join public.user_profiles p on p.id = a.user_id
    where a.active and a.scope = 'subject' and a.academic_year = v_year and a.grade = p_grade and a.room = p_room
  ), '[]'::jsonb);
end;
$$;

create or replace function public.pp5_subject_attendance_can_on(p_student text, p_subject text, p_date date)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_role text := public.pp5_current_role();
  v_year text;
  v_sem integer := public.pp5_semester_of(p_date);
begin
  if v_role = 'admin' then return true; end if;
  if v_role is distinct from 'teacher' then return false; end if;
  if not public.pp5_teacher_scope_enabled() then return true; end if;
  v_year := public.pp5_teacher_scope_year();
  return exists (
    select 1 from public.teacher_access_assignments a
    where a.user_id = auth.uid() and a.active and a.academic_year = v_year
      and (
        exists (select 1 from public.student_year_rosters r where r.student_id = p_student
          and r.academic_year = a.academic_year and r.grade = a.grade and r.room = a.room)
        or (not exists (select 1 from public.student_year_rosters r where r.student_id = p_student and r.academic_year = a.academic_year)
          and exists (select 1 from public.students s where s.id = p_student and s.grade = a.grade and s.room = a.room))
      )
      and (a.scope = 'homeroom' or (a.scope = 'subject' and a.subject_id = p_subject and a.semester in (0, v_sem)))
  );
end;
$$;

-- the 032 check, with the date: student in the subject's grade and the caller may check them ON THAT DATE
create or replace function public.pp5_subject_attendance_student(p_student text, p_subject_id text, p_year text, p_date date)
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_grade text := (select grade from public.subjects where id = p_subject_id);
begin
  if not exists (
    select 1 from public.students s where s.id = p_student and (
      exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = p_year and r.grade = v_grade)
      or (not exists (select 1 from public.student_year_rosters r where r.student_id = s.id and r.academic_year = p_year)
        and s.grade = v_grade))
  ) then
    raise exception using errcode = 'P0001', message = 'นักเรียน ' || p_student || ' ไม่ได้อยู่ชั้นของวิชานี้';
  end if;
  if not public.pp5_subject_attendance_can_on(p_student, p_subject_id, p_date) then
    raise exception using errcode = '42501', message = 'ไม่มีสิทธิ์เช็คชื่อวิชานี้ของนักเรียน ' || p_student
      || ' ในภาคเรียนที่ ' || public.pp5_semester_of(p_date);
  end if;
end;
$$;

create or replace function public.pp5_subject_schedule_can(p_subject_id text, p_grade text, p_room text, p_semester integer)
