create or replace function public.pp5_save_subject_attendance(p_subject_id text, p_date date, p_hours integer, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text := public.pp5_subject_attendance_year(p_subject_id, p_date);
  v_row jsonb;
  v_student text;
  v_status text;
  v_saved integer := 0;
  v_cleared integer := 0;
begin
  if p_hours is null or p_hours < 0 or p_hours > 8 then
    raise exception using errcode = 'P0001', message = 'จำนวนชั่วโมงต้องอยู่ระหว่าง 1 ถึง 8';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 300 then
    raise exception using errcode = 'P0001', message = 'รายชื่อนักเรียนไม่ถูกต้อง';
  end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_student := btrim(coalesce(v_row->>'student_id', ''));
    v_status := nullif(btrim(coalesce(v_row->>'status', '')), '');
    perform public.pp5_subject_attendance_student(v_student, p_subject_id, v_year, p_date);
    delete from public.subject_attendance
      where subject_id = p_subject_id and student_id = v_student and attendance_date = p_date
        and (p_hours = 0 or v_status is null or period > 1);
    if p_hours = 0 or v_status is null then
      v_cleared := v_cleared + 1;
      continue;
    end if;
    if v_status not in ('present', 'leave', 'absent') then
      raise exception using errcode = 'P0001', message = 'สถานะต้องเป็น มา ลา หรือ ขาด';
    end if;
    insert into public.subject_attendance (academic_year, subject_id, student_id, attendance_date, period, hours, status, recorded_by, updated_at)
      values (v_year, p_subject_id, v_student, p_date, 1, p_hours, v_status, auth.uid(), now())
      on conflict (subject_id, student_id, attendance_date, period) do update
        set academic_year = excluded.academic_year, hours = excluded.hours, status = excluded.status,
            recorded_by = excluded.recorded_by, updated_at = now();
    v_saved := v_saved + 1;
  end loop;
  return jsonb_build_object('saved', v_saved, 'cleared', v_cleared, 'academic_year', v_year);
end;
$$;

create or replace function public.pp5_save_subject_schedule(p_subject_id text, p_grade text, p_room text, p_semester integer, p_days jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text;
  v_day jsonb;
  v_weekday integer;
  v_periods integer;
  v_seen integer[] := '{}';
begin
  if coalesce(public.pp5_current_role(), '') not in ('admin', 'teacher') then
    raise exception using errcode = '42501', message = 'ต้องเป็นครูหรือผู้ดูแลระบบ';
  end if;
  if not exists (select 1 from public.subjects where id = p_subject_id and grade = p_grade) then
    raise exception using errcode = 'P0001', message = 'วิชานี้ไม่ใช่ของชั้น ' || coalesce(p_grade, '');
  end if;
  if p_semester is null or p_semester not in (1, 2) then
    raise exception using errcode = 'P0001', message = 'ภาคเรียนต้องเป็น 1 หรือ 2';
  end if;
  select nullif(btrim(s.academic_year::text), '') into v_year from public.school_settings s order by s.id limit 1;
  if v_year is null or v_year !~ '^[0-9]{4}$' then
    raise exception using errcode = 'P0001', message = 'ยังไม่ได้ตั้งปีการศึกษาในหน้าตั้งค่าระบบ';
  end if;
  if exists (select 1 from public.academic_years y where y.academic_year = v_year and y.is_locked) then
    raise exception using errcode = '42501', message = 'ปีการศึกษา ' || v_year || ' ถูกล็อกแล้ว แก้ไขไม่ได้';
  end if;
  if not exists (select 1 from public.student_year_rosters where academic_year = v_year and grade = p_grade and room = p_room
      union all select 1 from public.students where grade = p_grade and room = p_room) then
    raise exception using errcode = 'P0001', message = 'ไม่พบห้อง ' || coalesce(p_grade, '') || '/' || coalesce(p_room, '');
  end if;
  if not public.pp5_subject_schedule_can(p_subject_id, p_grade, p_room, p_semester) then
    raise exception using errcode = '42501', message = 'ไม่มีสิทธิ์ตั้งตารางสอนวิชานี้ของห้องนี้';
  end if;
  if p_days is null or jsonb_typeof(p_days) <> 'array' or jsonb_array_length(p_days) > 7 then
    raise exception using errcode = 'P0001', message = 'ตารางสอนไม่ถูกต้อง';
  end if;
  for v_day in select value from jsonb_array_elements(p_days) loop
    v_weekday := (v_day->>'weekday')::integer;
    v_periods := (v_day->>'periods')::integer;
    if v_weekday is null or v_weekday < 1 or v_weekday > 7 or v_periods is null or v_periods < 1 or v_periods > 4
        or v_weekday = any (v_seen) then
      raise exception using errcode = 'P0001', message = 'วันสอนต้องไม่ซ้ำ และสอนวันละ 1-4 คาบ';
    end if;
    v_seen := v_seen || v_weekday;
  end loop;
  delete from public.subject_schedules
    where academic_year = v_year and semester = p_semester and subject_id = p_subject_id and grade = p_grade and room = p_room;
  insert into public.subject_schedules (academic_year, semester, subject_id, grade, room, weekday, periods, updated_by, updated_at)
    select v_year, p_semester, p_subject_id, p_grade, p_room, (d->>'weekday')::smallint, (d->>'periods')::smallint, auth.uid(), now()
    from jsonb_array_elements(p_days) d;
  return jsonb_build_object('saved', jsonb_array_length(p_days), 'academic_year', v_year,
    'periods_per_week', coalesce((select sum((d->>'periods')::integer) from jsonb_array_elements(p_days) d), 0));
end;
$$;

revoke all on function public.pp5_semester_of(date) from public, anon;
revoke all on function public.pp5_subject_room_teachers(text, text) from public, anon;
revoke all on function public.pp5_subject_attendance_can_on(text, text, date) from public, anon;
revoke all on function public.pp5_subject_attendance_student(text, text, text, date) from public, anon;
revoke all on function public.pp5_subject_schedule_can(text, text, text, integer) from public, anon;
grant execute on function public.pp5_semester_of(date) to authenticated, service_role;
grant execute on function public.pp5_subject_room_teachers(text, text) to authenticated, service_role;
grant execute on function public.pp5_subject_attendance_can_on(text, text, date) to authenticated, service_role;
grant execute on function public.pp5_subject_attendance_student(text, text, text, date) to authenticated, service_role;
grant execute on function public.pp5_subject_schedule_can(text, text, text, integer) to authenticated, service_role;
-- ---- 202610150034_subject_assessments.sql ----
-- 202610150034_subject_assessments (owner 2026-10-15: "ให้ครูประจำวิชาประเมินคุณลักษณะ อ่านคิดเขียน และสมรรถนะในวิชาตัวเอง")
-- Owner decisions: every subject teacher assesses the FULL sets (คุณลักษณะ 8 · อ่านคิดเขียน 5 · สมรรถนะ 25) for their own
-- subject, per semester · the homeroom teacher makes the student's official result; the web offers the average of the
-- subject teachers as a starting value that the homeroom teacher accepts or changes.
--
-- Storage: the existing table public.assessments, three new assessment_type values, the subject in criteria_code:
--   subj_char  criteria_code = '<subject id>|c1' … '|c8'
--   subj_rtw   criteria_code = '<subject id>|rtw1' … '|rtw5'
--   subj_comp  criteria_code = '<subject id>|cp1' … '|cp25'
-- (unique (student_id, assessment_type, criteria_code, semester, academic_year) already makes it one row per subject)
--
-- Rights while teacher scope is ON: the homeroom teacher keeps everything of the room (027). A SUBJECT teacher may read
-- and write only subj_* rows of a subject they teach, for students of that room, in the semester of the job (semester
-- 0 = whole year). The write also needs an active, unlocked year (same as 027). Scope OFF: unchanged (staff).
-- Safe to run again. Rollback: supabase/rollbacks/202610150034_subject_assessments_rollback.sql
-- (202610150034_subject_assessments.sql: runs inside this file's transaction)
create or replace function public.pp5_subject_assessment_access(
  p_student text, p_year text, p_type text, p_criteria text, p_semester integer, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_year text := coalesce(p_year, public.pp5_teacher_scope_year());
  v_subject text := split_part(coalesce(p_criteria, ''), '|', 1);
  -- (a CASE inside an IF condition would end the condition at its first THEN — keep the pattern in a variable)
  v_pattern text := case p_type
      when 'subj_char' then '^[^|]+[|]c[1-8]$'
      when 'subj_rtw' then '^[^|]+[|]rtw[1-5]$'
      when 'subj_comp' then '^[^|]+[|]cp([1-9]|1[0-9]|2[0-5])$' end;
begin
  if public.pp5_current_role() is distinct from 'teacher' then return false; end if;
  if p_year is null or p_semester is null or p_semester not in (1, 2)
    or v_pattern is null or coalesce(p_criteria, '') !~ v_pattern then return false; end if;
  if p_write and (v_year is null or not exists (select 1 from public.academic_years
      where academic_year = v_year and status = 'active' and not is_locked)) then
    return false;
  end if;
  return exists (
    select 1 from public.teacher_access_assignments a
    join public.subjects s on s.id = a.subject_id and s.grade = a.grade
    where a.user_id = auth.uid() and a.active and a.academic_year = v_year
      and a.scope = 'subject' and a.subject_id = v_subject and a.semester in (0, p_semester)
      and (s.semester is null or s.semester = p_semester)
      and (
        exists (select 1 from public.student_year_rosters r where r.student_id = p_student
          and r.academic_year = a.academic_year and r.grade = a.grade and r.room = a.room)
        or (not exists (select 1 from public.student_year_rosters r where r.student_id = p_student and r.academic_year = a.academic_year)
          and exists (select 1 from public.students st where st.id = p_student and st.academic_year = a.academic_year
            and st.grade = a.grade and st.room = a.room))
      )
  );
end;
$$;

revoke all on function public.pp5_subject_assessment_access(text, text, text, text, integer, boolean) from public, anon;
grant execute on function public.pp5_subject_assessment_access(text, text, text, text, integer, boolean) to authenticated, service_role;

-- The 027 restrictive policies of assessments, plus the subject-teacher path (ANDed with the permissive staff policies).
drop policy if exists pp5_scoped_read on public.assessments;
create policy pp5_scoped_read on public.assessments as restrictive for select to authenticated using (
  not public.pp5_teacher_scope_enabled()
  or public.pp5_teacher_scope_access('assessments', student_id, academic_year, null, null, false)
  or public.pp5_subject_assessment_access(student_id, academic_year, assessment_type, criteria_code, semester, false));
drop policy if exists pp5_scoped_insert on public.assessments;
create policy pp5_scoped_insert on public.assessments as restrictive for insert to authenticated with check (
  not public.pp5_teacher_scope_enabled()
  or public.pp5_teacher_scope_access('assessments', student_id, academic_year, null, null, true)
  or public.pp5_subject_assessment_access(student_id, academic_year, assessment_type, criteria_code, semester, true));
drop policy if exists pp5_scoped_update on public.assessments;
create policy pp5_scoped_update on public.assessments as restrictive for update to authenticated using (
  not public.pp5_teacher_scope_enabled()
  or public.pp5_teacher_scope_access('assessments', student_id, academic_year, null, null, true)
  or public.pp5_subject_assessment_access(student_id, academic_year, assessment_type, criteria_code, semester, true))
  with check (
  not public.pp5_teacher_scope_enabled()
  or public.pp5_teacher_scope_access('assessments', student_id, academic_year, null, null, true)
  or public.pp5_subject_assessment_access(student_id, academic_year, assessment_type, criteria_code, semester, true));
drop policy if exists pp5_scoped_delete on public.assessments;
create policy pp5_scoped_delete on public.assessments as restrictive for delete to authenticated using (
  not public.pp5_teacher_scope_enabled()
  or public.pp5_teacher_scope_access('assessments', student_id, academic_year, null, null, true)
  or public.pp5_subject_assessment_access(student_id, academic_year, assessment_type, criteria_code, semester, true));
-- ---- 202610180035_student_transfers.sql ----
-- 202610180035_student_transfers (owner 2026-10-18: "เพิ่มเมนูนักเรียนย้าย เลือกนักเรียนแล้วออกเอกสารให้ ผอ.เซ็น")
-- Owner decisions: round 1 prints แบบ บค.19 (คำร้องผู้ปกครอง) + บค.20 (หนังสือส่งตัว) · keep a history · the student
-- leaves the class list only when an admin confirms (ระเบียบ: จำหน่ายหลังเขตอนุญาต) · the letter number is typed by hand.
--
--   student_transfers   one row per transfer request; status requested -> transferred (or cancelled)
--                       form = the typed fields of the two forms (destination, reason, addresses, ป.พ. counts ...)
--                       student_snapshot = name / ID / birth date / class at the time of the request, so a reprint
--                       still shows the class the student left from
--   pp5_confirm_student_transfer(id)  admin only: marks the transfer done and sets the student + this year's roster
--                       row to 'inactive' (the same status the existing "จำหน่ายนักเรียน" button uses). Grades,
--                       attendance and every other record stay.
--
-- Admins only (งานทะเบียน). Safe to run again. Rollback: supabase/rollbacks/202610180035_student_transfers_rollback.sql
-- (202610180035_student_transfers.sql: runs inside this file's transaction)
create table if not exists public.student_transfers (
  id uuid primary key default gen_random_uuid(),
  student_id text not null references public.students(id) on delete cascade,
  academic_year text not null,
  status text not null default 'requested' check (status in ('requested', 'transferred', 'cancelled')),
  destination_school text not null check (length(btrim(destination_school)) between 1 and 200),
  doc_no text check (doc_no is null or length(doc_no) <= 80),
  doc_date date,
  form jsonb not null default '{}'::jsonb check (jsonb_typeof(form) = 'object' and length(form::text) <= 8000),
  student_snapshot jsonb not null default '{}'::jsonb check (jsonb_typeof(student_snapshot) = 'object' and length(student_snapshot::text) <= 4000),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  confirmed_by uuid,
  confirmed_at timestamptz
);
-- one open request per student (a second request must cancel or finish the first)
create unique index if not exists student_transfers_one_open_idx on public.student_transfers (student_id) where status = 'requested';
create index if not exists student_transfers_year_idx on public.student_transfers (academic_year, created_at desc);

alter table public.student_transfers enable row level security;
drop policy if exists student_transfers_admin_all on public.student_transfers;
create policy student_transfers_admin_all on public.student_transfers for all to authenticated
  using (public.pp5_current_role() = 'admin') with check (public.pp5_current_role() = 'admin');

revoke all on table public.student_transfers from anon;
grant select, insert, update, delete on table public.student_transfers to authenticated;
grant all on table public.student_transfers to service_role;

-- status/confirmation columns change only through pp5_confirm_student_transfer or a cancel (requested -> cancelled)
create or replace function public.pp5_student_transfers_guard()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' then
    if new.status <> 'requested' or new.confirmed_at is not null or new.confirmed_by is not null then
      raise exception using errcode = '42501', message = 'เรื่องย้ายใหม่ต้องเริ่มที่สถานะ "ส่งเรื่องแล้ว"';
    end if;
    return new;
  end if;
  if old.status <> 'requested' and current_setting('pp5.transfer_confirm', true) is distinct from 'on' then
    raise exception using errcode = '42501', message = 'เรื่องย้ายนี้ปิดแล้ว แก้ไขไม่ได้';
  end if;
  if new.status is distinct from old.status and current_setting('pp5.transfer_confirm', true) is distinct from 'on'
     and not (old.status = 'requested' and new.status = 'cancelled') then
    raise exception using errcode = '42501', message = 'ยืนยันย้ายออกได้จากปุ่ม "ยืนยันย้ายออก" เท่านั้น';
  end if;
  if (new.confirmed_at is distinct from old.confirmed_at or new.confirmed_by is distinct from old.confirmed_by)
     and current_setting('pp5.transfer_confirm', true) is distinct from 'on' then
    raise exception using errcode = '42501', message = 'แก้วันที่ยืนยันย้ายออกเองไม่ได้';
  end if;
  return new;
end;
$$;
drop trigger if exists student_transfers_guard on public.student_transfers;
create trigger student_transfers_guard before insert or update on public.student_transfers
  for each row execute function public.pp5_student_transfers_guard();

create or replace function public.pp5_confirm_student_transfer(p_transfer_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  t public.student_transfers;
  s_year text;
begin
  if coalesce(public.pp5_current_role(), '') <> 'admin' then
    raise exception using errcode = '42501', message = 'ต้องเป็นผู้ดูแลระบบ';
  end if;
  select * into t from public.student_transfers where id = p_transfer_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'ไม่พบเรื่องย้ายนี้';
  end if;
  if t.status <> 'requested' then
    raise exception using errcode = '22023', message = 'เรื่องย้ายนี้ไม่ได้อยู่ในสถานะ "ส่งเรื่องแล้ว"';
  end if;

  perform set_config('pp5.transfer_confirm', 'on', true);
  update public.student_transfers
     set status = 'transferred', confirmed_at = now(), confirmed_by = auth.uid()
   where id = t.id;
  perform set_config('pp5.transfer_confirm', 'off', true);

  update public.students set status = 'inactive', updated_at = now()
   where id = t.student_id
  returning academic_year into s_year;
  update public.student_year_rosters set status = 'inactive', updated_at = now()
   where student_id = t.student_id and academic_year in (t.academic_year, coalesce(s_year, t.academic_year));

  return jsonb_build_object('success', true, 'transfer_id', t.id, 'student_id', t.student_id);
end;
$$;

revoke all on function public.pp5_confirm_student_transfer(uuid) from public, anon;
grant execute on function public.pp5_confirm_student_transfer(uuid) to authenticated, service_role;
revoke all on function public.pp5_student_transfers_guard() from public, anon, authenticated;

commit;
